(window.GIM_TS=window.GIM_TS||{})["Menachot.5"]={"from":120,"a":[["ו\u0003כיצד\u0004 מניף הקדשים \u0003עושה\u0004 בהם לפני הנפתם? — בתחילה הוא \u0003מניח\u0004 את ה\u0003אימורין\u0004 (החלקים הקרבים על אש המזבח) \u0003על פיסת\u0004 (כף) \u0003היד, ו\u0004את ה\u0003חזה ו\u0004ה\u0003שוק\u0004 (הניתנים לכהנים לאכילה) מניח \u0003עליהן. ובכל מקום שיש\u0004 עם הקרבן גם \u0003לחם\u0004 — \u0003הלחם\u0004 מונח \u0003מלמעלה\u0004 בהנפה.","ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 מצאנו בקרבנות המונפים שהלחם המונף צריך להיות מלמעלה? \u0003אמר רב פפא:\u0004 באיל ה\u0003מלואים\u0004 שנאמר בו \"ויקח את החלב ואת האליה ואת כל החלב אשר על הקרב... ואת שוק הימין. ומסל המצות אשר לפני ה' לקח חלת מצה אחת וחלת לחם שמן אחת ורקיק אחד וישם על החלבים ועל שוק הימין. ויתן את הכל על כפי אהרן ועל כפי בניו וינף אותם תנופה לפני ה' \" (ויקרא ח, כה— כז).","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לכך שבתחילה מניחים את האימורים, ומעליהם את החזה והשוק? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנלמד הדבר \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף תנופה\u0004 לפני ה' והיה לך ולבניך אתך לחק עולם....\" (שם י, טו), הרי שהחזה והשוק ניתנים על החלבים בתנופה, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 כתוב אחר \u0003\"את החלב על החזה יביאנו\u0004 את החזה להניף אותו תנופה לפני ה' \" (שם ז, ל), להיפך, שהחלבים ניתנים על החזה והשוק להנפה, ולא מתחתיהם!","\u0003אמר אביי:\u0004 אין להקשות מאותו כתוב, שכן הכתוב \u0003ההוא\u0004 אינו מדבר על אופן ההנחה בשעת התנופה אלא על אופן ההנחה בזמן \u0003דמייתי ליה\u0004 \u0005[שמביא אותו,\u0006 את הקרבן העומד להנפה\u0005]\u0006 ה\u0003כהן\u0004 הבא \u0003מבית המטבחיים\u0004 לאחר שנשחט הקרבן לכהן אחר לצורך הנפתו. ואצל הכהן המביא מניחים בתחילה את השוק ואת החזה, ולאחר מכן מניחים את החלבים. \u0003ו\u0004באופן זה של נשיאת החלקים, נמצא שכאשר \u0003רמי ליה\u0004 \u0005[מטיל אותו,\u0006 הופך ומניח\u0005]\u0006 את הקרבן על כפי הכהן המניף, בתחילה יושמו על כפיו החלבים (הנמצאים למעלה), ואחר כך מעליהם יושמו החזה והשוק.","ומקשים על כך: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 כתוב \u0005נוסף המורה ששמים את החלבים מעל החזה והשוק, ולא מתחתיהם, שכן נאמר\u0006 \u0003\"וישימו את החלבים על החזות\"\u0004 (שם ט, כ)! ומשיבים: אף מכתוב זה אין להקשות, שכן הכתוב \u0003ההוא\u0004 מדבר בזמן \u0003דיהיב ליה\u0004 \u0005[שנותן אותו,\u0006 את החלקים המונפים\u0005]\u0006 הכהן המניף, לאחר ההנפה, \u0003לכהן אחרינא\u0004 \u0005[אחר],\u0006 המעלה על המזבח את החלקים הקרבים עליו, ונמצא איפוא שבתחילה שם הכהן המניף על ידו של הכהן המקטיר את החזה והשוק, ולאחר מכן הוא שם עליהם את החלבים. \u0003ואזיל\u0004 \u0005[והולך]\u0006 כהן זה \u0003ומקטר ליה\u0004 \u0005[ומקטיר אותו].\u0006","\u0003והא\u0004 \u0005[וזה],\u0006 שלושת הכתובים הללו ופירושם \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו,\u0006 מלמדנו\u0005],\u0006 \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003שלשה כהנים,\u0004 לעבודה (המביא מבית המטבחיים, המניף, המקטיר), ואין כהן אחד עושה את שלוש העבודות הללו. וטעם הדבר: \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח), שכבודו של מלך הוא שתיעשה מלאכתו בידי רבים.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003שתי הלחם ושני כבשי עצרת\u0004 חייבים בהנפה, וכיצד הוא עושה בהנפתם? נותן את שתי הלחם על גבי שני הכבשים, ומניפם. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר \"והניף הכהן אותם על לחם הביכורים תנופה לפני ה' על שני כבשים קדש יהיו לה' לכהן\" (ויקרא כג, כ), ומן האמור בתחילתו \u0003\"והניף הכהן אתם על לחם הבכרים\"\u0004","\u0003יכול\u0004 היית ללמוד כי מצווה הכהן המניף ש\u0003יניח\u0004 את ה\u0003כבשים על גבי הלחם,\u0004 ויניפם. ולכך \u0003תלמוד לומר\u0004 בהמשך הכתוב \"תנופה לפני \u0003ה'\u0004 \u0003על שני כבשים\"\u0004 — ללמדנו ששתי הלחם נמצאים על הכבשים בשעת ההנפה! וכן לצד האחר, \u0003אי\u0004 \u0005[אם]\u0006 תלמד דין הנפה מן \u0003\"על שני כבשים\", יכול\u0004 היית לומר כי מצווה הכהן המניף שיניח את שתי ה\u0003לחם על גבי כבשים,\u0004 ויניפם. לכך \u0003תלמוד לומר \"על לחם הבכורים\"\u0004 — ללמדנו שהלחם נתון מתחת לכבשים בשעת ההנפה.","נמצא כי \u0003נישתקל\u0004 \u0005[שקול]\u0006 הוא \u0003הכתוב,\u0004 שיש בו שתי אמירות סותרות. \u0003ו\u0004מעתה \u0003איני יודע\u0004 כיצד היא הנפתם, \u0003אם\u0004 ה\u0003לחם\u0004 נמצא \u0003על גבי כבשים, ואם\u0004 ה\u0003כבשים\u0004 הם הנמצאים \u0003על גבי\u0004 ה\u0003לחם.\u0004 ותיפתר הבעיה כך: \u0003מה מצינו\u0004 (כשם שמצאנו) \u0003בכל מקום\u0004 שנעשית הנפה, שה\u0003לחם\u0004 נתון \u0003למעלה, אף כאן\u0004 בשתי הלחם וכבשי העצרת ה\u0003לחם\u0004 נתון \u0003למעלה\u0004 בהנפה. ואגב הרצאת דברי הברייתא מבררים: \u0003היכא\u0004 \u0005[היכן]\u0006 באיזה מקום מצאנו שהלחם נתון למעלה בהנפה? \u0003אמר רב פפא: ב\u0004איל ה\u0003מילואים.\u0004","ושבים לדברי הברייתא, \u0003ר' יוסי בן המשולם\u0004 חולק על דברי חכמים, ו\u0003אומר\u0004 שאין כבשי העצרת מונחים למטה ושתי הלחם מונחים למעלה בשעת ההנפה, אלא ה\u0003כבשים\u0004 הם המונחים \u0003למעלה,\u0004 ושתי הלחם מלמטה. \u0003ומה\u0004 (כיצד) \u0003אני מקיים\u0004 את האמור בכתוב \u0003\"על שני כבשים\"\u0004 המורה לכאורה ששתי הלחם נמצאים מעל הכבשים? — בא כתוב זה לומר שאין הנפת הכבשים עם הלחמים נוהגת אלא בשני הכבשים (של עצרת), שהם שלמי ציבור, ו\u0003להוציא\u0004 (למעט) מכלל דין זה \u0003את\u0004 \u0003שבעה\u0004 הכבשים, שהם עולות, הבאים גם הם עם הלחם, שאין הם מונפים עם הלחם.","ואילו החכם \u0003חנינא בן חכינאי אומר:\u0004 \u0003מניח\u0004 את \u0003שתי הלחם בין ירכותיהן של\u0004 שני ה\u0003כבשים, ומניף\u0004 אותם כך, \u0003ונמצא\u0004 שבאופן זה הריהו \u0003מקיים\u0004 את \u0003שני\u0004 ה\u0003מקראות הללו,\u0004 שיש באופן זה גם \u0003לחם על גבי כבשים ו\u0004גם \u0003כבשים על גבי הלחם.\u0004 על כך \u0003אמר רבי:\u0004 אין לנהוג כדברי חנינא בן חכינאי, שהרי אם \u0003לפני מלך בשר ודם אין עושין כן\u0004 להניח על שולחנם לחם הנתון בין ירכותיהם של הכבשים, \u0003לפני מלך מלכי המלכים הקדוש ברוך הוא עושין כן?! אלא\u0004 כך יש לעשות: \u0003מניח\u0004 את שתי הלחם ושני הכבשים הבאים בעצרת \u0003זה בצד זה, ומניף\u0004 אותם יחד, ונמצא מקיים את שני המקראות, בדרך של כבוד לפני המקום.","ומקשים על שיטת רבי: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיתקיים בהנפה הכתוב \u0003\"על\"\u0004 (\"על לחם הביכורים\" או \"על שני כבשים\") ואילו באופן זה אין האחד נמצא על חבירו אלא לצידו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב המנונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב המנונא לרב חסדא:\u0004 \u0003רבי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003דאמר\u0004 \u0005[שאמר]\u0006 שהתיבה \u0003\"על\"\u0004 משמשת גם במובן של \u0003בסמוך.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר בלחם הפנים \u0003\"ונתת על המערכת לבנה זכה\"\u0004 (ויקרא כד, ז), \u0003רבי אומר: \"על\"\u0004 האמור בכתוב זה משמעו \u0003בסמוך,\u0004 שאין הלבונה ניתנת על מערכת לחם הפנים עצמו, אלא לידו. \u0003אתה אומר\u0004 כי \u0003\"על\"\u0004 משמעה \u0003בסמוך, או אינו אלא\u0004 שמשמעה \u0003על ממש?\u0004 על כך יש להשיב: \u0003כשהוא\u0004 (הכתוב) \u0003אומר\u0004 בדינה של הפרוכת והארון: \u0003\"ושמת שם את ארון העדות\u0004 \u0003וסכת על הארן את הפרכת\"\u0004 (שמות מ, ג), והרי אין הפרוכת נתונה מעל הארון, אלא מצידו, כמחיצה. ומכאן \u0003הוי אומר\u0004 כי אף בענייננו הכתוב \u0003\"על\"\u0004 כוונתו \u0003בסמוך,\u0004 ולא על ממש.","שנינו במשנתנו שהנפת שתי הלחם ושני כבשי עצרת נעשית כך, מניח את שתי ידיו מלמטה ו\u0003מוליך\u0004 (מושיט) כלפי כל רוח מארבע רוחות השמים, \u0003ומביא\u0004 (ומחזיר אליו), ו\u0003מעלה\u0004 כלפי מעלה \u0003ומוריד\u0004 מטה. ובענין זה עוד \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: מוליך\u0004 כנגד ארבע רוחות השמים \u0003ומביא\u0004 — כהודיה \u0003ל\u0004קדוש ברוך הוא, \u0003מי\u0004 שכל \u0003הרוחות\u0004 (הצדדים בעולם) הן \u0003שלו,\u0004 ו\u0003מעלה ומוריד\u0004 — כהודיה \u0003ל\u0004קדוש ברוך הוא, \u0003מי שהשמים והארץ\u0004 הם \u0003שלו.\u0004","\u0003במערבא מתנו הכי\u0004 \u0005[בארץ ישראל היו שונים כך],\u0006 \u0003אמר רב חמא בר עוקבא,\u0004 \u0003אמר ר' יוסי בר ר' חנינא: מוליך ומביא\u0004 לארבע רוחות השמים — \u0003כדי לעצור\u0004 בעד \u0003רוחות רעות\u0004 שלא תבואנה לעולם, ו\u0003מעלה ומוריד\u0004 — \u0003כדי לעצור\u0004 בעד \u0003טללים רעים\u0004 מלרדת לעולם.","\u0003אמר ר' יוסי בר רב אבין: זאת\u0004 \u0003אומרת\u0004 כי מעלת \u0003שירי\u0004 (נספחי, טפלי) \u0003מצוה,\u0004 וכגון ההנפה שאינה עיקר מצות הקרבן (שהרי הקרבן מכפר אף אם לא נעשתה בו הנפה), שהם \u0003מעכבים\u0004 (מונעים) \u0003את\u0004 \u0003הפורענות\u0004 מלבוא, \u0003דהא\u0004 \u0005[שהרי]\u0006 ה\u0003תנופה שירי מצוה היא,\u0004 \u0003ו\u0004הריהי \u0003עוצרת רוחות רעות וטללים רעים\u0004 מלבוא לעולם. \u0003אמר רבה: וכן\u0004 צריך להוליך ולהביא לארבע רוחות השמים ולהעלות מעלה ולהוריד מטה את ה\u0003לולב\u0004 בחג הסוכות.","ונמסר כי \u0003רב אחא בר יעקב ממטי ליה ומייתי ליה ומחוי הכי ואמר\u0004 \u0005[היה מוליך אותו ומביא אותו,\u0006 את הלולב, \u0005ומראה כך ואומר]:\u0006 יורה \u0003אני\u0004 \u0003גירא בעינא דשטנא\u0004 \u0005[חץ בעינו של השטן].\u0006 ומעירים: \u0003ולאו מילתא\u0004 \u0005[ולא דבר,\u0006 עשייה\u0005]\u0006 ראויה \u0003היא,\u0004 \u0003משום דאתי\u0004 \u0005[ש\u0006בכך \u0005יבוא]\u0006 השטן \u0003לאתגרויי ביה\u0004 \u0005[להתגרות בו].\u0006","ועוד בענין ההנפה בקרבנות \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003זבחי שלמי צבור\u0004 חייבים בתנופה בעודם חיים, וכן הריהם \u0003טעונין\u0004 (חייבים) \u0003תנופה לאחר שחיטה, ותנופתן\u0004 לאחר שנשחטו הריהי נעשית בשלמותם, \u0003כמות שהן\u0004 בחייהם. אלו \u0003דברי רבי. ו\u0004אילו \u0003חכמים אומרים:\u0004 אין ההנפה בכל הקרבן השחוט, אלא רק \u0003בחזה ושוק.\u0004","ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה \u0005עקרון,\u0006 \u0005הם חלוקים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב המנונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב המנונא לרב חסדא\u0004 בהסבר מחלוקת רבי וחכמים, כי בשאלה העקרונית לגבי הלימוד מגזירה שווה הם נחלקים. האם נלמד מגזירה שווה \u0003ב\u0004אופן שיש ל\u0003דון מינה ומינה\u0004 \u0005[ללמוד ממנה וממנה],\u0006 כלומר, נלמד מכל פרטיו של הדבר המלמד לעניינו של הדבר הלמד. או שמא גזירה שווה מלמדת \u0003ב\u0004אופן שיש ל\u0003דון מינה ואוקי באתרה\u0004 \u0005[ללמוד ממנה\u0006 רק לענין הפרט בו נגזרה הגזירה שווה, \u0005והעמד\u0006 את הדבר הלמד בשאר פרטיו \u0005במקומה].\u0006 ובזאת \u0003קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006","ומפרטים: למדים אנו דין הנפה בשלמי ציבור מדין הנפה בשלמי יחיד בגזירה שווה, \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כגישה העקרונית האומרת \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 ולכך בענייננו גם כן נאמר: \u0003מה זבחי שלמי יחיד טעונין תנופה לאחר שחיטה, אף זבחי שלמי צבור טעונין תנופה לאחר שחיטה. ומינה\u0004 \u0005[וממנה]\u0006 נוסיף ונלמד עוד בשאר הפרטים: \u0003מה התם\u0004 \u0005[שם,\u0006 בשלמי יחיד\u0005]\u0006 ההנפה נעשית \u0003בחזה ושוק\u0004 בלבד, \u0003אף הכא נמי\u0004 \u0005[כאן,\u0006 בשלמי ציבור, \u0005גם כן]\u0006 ההנפה נעשית \u0003בחזה ושוק\u0004 בלבד.","\u0003ו\u0004אילו \u0003רבי סבר\u0004 \u0005[סבור]\u0006 כשיטה העקרונית שיש ל\u0003דון מינה ואוקי באתרה\u0004 \u0005[ללמוד ממנה ולהעמיד במקומה],\u0006 ומשום כך, אף בענייננו, אכן לומד הוא בגזירה שווה: \u0003מה זבחי שלמי יחיד\u0004 — \u0003טעונין תנופה לאחר שחיטה, אף זבחי שלמי צבור\u0004 — \u0003טעונין תנופה לאחר שחיטה, ו\u0004אולם בשאר פרטים \u0003אוקי באתרה\u0004 \u0005[העמד\u0006 את ההלכה הנלמדת \u0005במקומה],\u0006 ודווקא \u0003התם\u0004 \u0005[שם,\u0006 בשלמי יחיד\u0005]\u0006 דין ההנפה \u0003הוא\u0004 ב\u0003חזה ושוק, אבל הכא\u0004 \u0005[כאן,\u0006 בשלמי ציבור\u0005]\u0006 ההנפה היא \u0003כמות שהן,\u0004 שמונפים הם בשלמותם, \u0003כמות שהן בחיים.\u0004"],["\u0003רב פפא אמר\u0004 הסבר אחר למחלוקתם של רבי וחכמים: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל],\u0006 אף לדעת רבי אופן הלימוד בגזירה שווה, יש ל\u0003דון מינה ומינה\u0004 \u0005[ללמוד ממנה וממנה]\u0006 \u0003הוא, ו\u0004אולם \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רבי\u0004 הסבור שמניפים את שלמי הציבור לאחר שחיטתם בשלמותם, ולא את החזה והשוק בלבד (כבשלמי יחיד): \u0003כי התם\u0004 \u0005[כמו שם,\u0006 בשלמי יחיד\u0005],\u0006 \u0003מה התם\u0004 \u0005[שם]\u0006 מניפים את ה\u0003דבר ש\u0004הוא \u0003מתנה\u0004 (הניתן) \u0003לכהן,\u0004 שהרי החזה והשוק ניתנים לכהנים לאכילה, \u0003אף הכא\u0004 \u0005[כאן,\u0006 בשלמי ציבור\u0005]\u0006 מניפים את ה\u0003דבר ש\u0004הוא \u0003מתנה לכהן,\u0004 וכיון ששלמי ציבור ניתנים כולם לכהנים, אף הנפתם בשלמותם.","ואילו \u0003רבינא אמר\u0004 הסבר הפוך מזה של רב פפא: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 אף לדעת חכמים בגזירה שווה יש ל\u0003דון מינה ואוקי באתרה\u0004 \u0005[ממנה\u0006 רק בפרט המסויים, \u0005ולהעמיד\u0006 את \u0005ההלכה הנלמדת בשאר פרטיה\u0006 \u0005במקומה],\u0006 \u0003ו\u0004אולם \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שאין מניפים בשלמי ציבור אלא את החזה והשוק: משום שנאמר בדינם של שלמי יחיד \"כי את חזה התנופה ואת שוק התרומה לקחתי מאת בני ישראל מזבחי שלמיהם ואתן אותם לאהרן הכהן ולבניו...\" (ויקרא ז, לד), והרי המלה \u0003\"שלמיהם\"\u0004 הנאמרת בלשון רבים (ולא בלשון יחיד, אף שבשלמי יחיד הכתוב מדבר) \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 וללמדנו שאף בשלמי ציבור הוא הדין, שמניפים מהם את השוק ואת החזה בלבד.","שנינו במשנתנו ש\u0003ר' שמעון אומר\u0004 כי \u0003שלשה מינין\u0004 של קרבנות \u0003טעונין שלש מצו‍ת\u0004 הנעשות בהם. \u0003שתים\u0004 משלוש המצוות הללו נוהגות \u0003בכל אחד\u0004 ואחד משלשת מיני הקרבנות הללו, \u0003ו\u0004אילו המצוה ה\u0003שלישית אין\u0004 נוהגת \u0003בהן. ואלו הן\u0004 שלושת מיני הקרבנות: \u0003זבחי שלמי יחיד\u0004 (קרבנות שלמים שמביא אדם יחיד), \u0003וזבחי שלמי צבור\u0004 (שני כבשי עצרת), \u0003ו\u0004קרבן \u0003אשם\u0004 שמביא ה\u0003מצורע\u0004 הנרפא מצרעתו.","\u0003זבחי שלמי יחיד\u0004 — הריהם \u0003טעונין סמיכה\u0004 על ראש הקרבן בהיותו עדיין ב\u0003חיים, ו\u0004כן \u0003תנופה\u0004 של האימורים הבאים מהקרבנות ה\u0003שחוטין, ו\u0004אולם \u0003אין בהן\u0004 מצות \u0003תנופה\u0004 בעודם \u0003חיים.\u0004 ואילו \u0003זבחי שלמי צבור טעונין תנופה\u0004 של הקרבנות בעודם \u0003חיים ו\u0004כן של החזה והשוק שלהם בהיותם כבר \u0003שחוטין, ו\u0004אולם \u0003אין בהן\u0004 מצות \u0003סמיכה,\u0004 שאין הסמיכה נוהגת בקרבנות ציבור (מלבד בשעיר המשתלח ביום הכיפורים ובפר העלם דבר של ציבור). ואילו \u0003אשם מצורע\u0004 — \u0003טעון\u0004 הן \u0003סמיכה\u0004 (ככל קרבנות היחיד, מלבד הבכור והמעשר והפסח), \u0003ו\u0004הן \u0003תנופה\u0004 של הקרבן בעודו \u0003חי.\u0004 \u0003ו\u0004אולם \u0003אין בו\u0004 מצות \u0003תנופה\u0004 בקרבן ה\u0003שחוט.\u0004 ונמצא איפוא שבכל אחד משלושת הקרבנות הללו אין אלא שתי מצוות מתוך אלה השלוש.","ודנים בדברי ר' שמעון: \u0003ויהיו זבחי שלמי יחיד טעונין תנופה\u0004 אף בעודם \u0003חיים\u0004 כדרך שהם טעונים תנופה שחוטים, ויילמד הדבר \u0003מקל וחומר,\u0004 ובאופן זה: \u0003ומה זבחי שלמי צבור\u0004 הקלים בדינם משלמי יחיד, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003טעונין סמיכה\u0004 בעודם \u0003חיים\u0004 (כשלמי יחיד), ובכל זאת הריהם \u0003טעונין תנופה\u0004 כשהם \u0003חיים, זבחי שלמי יחיד\u0004 החמורים בדינם משלמי ציבור, \u0003ש\u0004הרי הם \u0003טעונין סמיכה\u0004 בעודם \u0003חיים\u0004 בעוד ששלמי ציבור אינם טעונים סמיכה חיים — \u0003אינו דין ש\u0004יהיו \u0003טעונין תנופה\u0004 כשהם \u0003חיים!\u0004","ומשיבים: אין אומרים כן, כיון ש\u0003מיעט רחמנא גבי\u0004 \u0005[הכתוב אצל]\u0006 הנאמר ב\u0003זבחי שלמי צבור,\u0004 בלשון \u0003\"אתם\"\u0004 (\"והניף הכהן אותם על לחם הביכורים תנופה לפני ה' על שני כבשים...\", שם כג, כ), והמלה \u0003\"אתם\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]:\u0006 \u0005שלמי ציבור מניפים בחיים, ואין מניפים בחיים\u0006 \u0003זבחי שלמי יחיד.\u0004","ושואלים עוד על דברי ר' שמעון: \u0003ויהיו זבחי שלמי צבור טעונין סמיכה\u0004 כמו שלמי יחיד, ויילמד הדבר \u0003מקל וחומר\u0004 כך: \u0003ומה זבחי שלמי יחיד\u0004 הקלים בדינם משלמי ציבור, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003טעונין תנופה\u0004 בעודם \u0003חיים\u0004 כדרך ששלמי ציבור טעונים — הריהם \u0003טעונין סמיכה.\u0004 מעתה, \u0003זבחי שלמי צבור\u0004 החמורים משלמי יחיד, \u0003ש\u0004הרי הם \u0003טעונין תנופה\u0004 בעודם \u0003חיים\u0004 — \u0003אינו דין ש\u0004יהיו אף הם \u0003טעונין סמיכה! אמר רבינא\u0004 בתשובה לשאלה זו: \u0003גמירי\u0004 \u0005[למודים]\u0006 חכמים במסורת הבאה מסיני, כי אין נוהגות אלא \u0003שתי סמיכות\u0004 בלבד \u0003ב\u0004קרבנות \u0003צבור,\u0004 בפר העלם דבר, ובשעיר המשתלח, ולכך אין ללמוד שתנהג סמיכה בשלמי ציבור.","ועוד שואלים על דברי ר' שמעון: \u0003ויהא אשם מצורע טעון תנופה\u0004 כשהוא כבר \u0003שחוט,\u0004 כדרך ששלמי יחיד טעונים תנופה כשהם שחוטים, ויילמד הדבר \u0003מקל וחומר\u0004 כך: \u0003מה זבחי שלמי יחיד\u0004 הקלים בדינם מאשם מצורע, \u0003ש\u0004כן \u0003אין\u0004 הם \u0003טעונין תנופה\u0004 בעודם \u0003חיים,\u0004 בעוד שאשם מצורע חייב בתנופה כשהוא חי — הריהם \u0003טעונין תנופה\u0004 כשהם \u0003שחוטין.\u0004 מעתה, \u0003אשם מצורע\u0004 החמור בדינו משלמי יחיד, \u0003ש\u0004הרי \u0003הוא\u0004 \u0003טעון תנופה\u0004 בעודו \u0003חי,\u0004 מה שאין כן שלמי יחיד — \u0003אינו דין ש\u0004יהא \u0003טעון תנופה\u0004 כשהוא \u0003שחוט!\u0004","ומשיבים: אין לומר כן, כיון ש\u0003מיעט רחמנא גבי\u0004 \u0005[הכתוב אצל]\u0006 הנאמר ב\u0003זבחי שלמי יחיד\u0004 בלשון \u0003\"אתו\"\u0004 (\"ידיו תביאינה את אשי ה'... את החזה להניף אותו תנופה לפני ה' \", ויקרא ז, ל), והרי המלה \u0003\"אתו\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]:\u0006 בשלמי יחיד נוהגת הנפה בחיים, \u0005ואין היא נוהגת ב\u0006\u0003אשם מצורע.\u0004","ועוד בדין התנופה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חמשה\u0004 אנשים \u0003שהביאו\u0004 בשותפות \u0003קרבן אחד\u0004 — \u0003אחד\u0004 מהם \u0003מניף על ידי\u0004 (עבור) \u0003כולם. והאשה\u0004 — \u0003כהן מניף על ידה\u0004 (עבורה). \u0003וכן השולח קרבנותיו ממדינת הים\u0004 (מחוץ לארץ) — \u0003כהן מניף על ידו\u0004 (עבורו)."],["\u0003ה\u0004נודב מנחה למקדש ו\u0003אומר \"הרי עלי\u0004 מנחה העשויה \u0003במחבת\"\u0004 — \u0003לא יביא\u0004 מנחה העשויה \u0003במרחשת.\u0004 שאין הוא יוצא ידי נדרו, אלא כאשר מביא כאותה מנחה שנדב. וכן האומר \"הרי עלי מנחה העשויה \u0003במרחשת\"\u0004 — \u0003לא יביא\u0004 מנחה העשויה \u0003במחבת.\u0004 ואף שמנחות אלה דומות זו לזו, שכן שתיהן נעשות בכלי, מכל מקום הריהן מנחות שונות, ואין לשנות ממנחה שנדר בה למנחה אחרת. ומסבירים \u0003מה\u0004 השוני \u0003בין\u0004 ה\u0003מחבת ל\u0004בין ה\u0003מרחשת\u0004 — ה\u0003מרחשת יש לה כיסוי,\u0004 ואילו ה\u0003מחבת אין לה כיסוי.\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' חנינא בן גמליאל אומר:\u0004 ההבדל ביניהן הוא בזה שה\u0003מרחשת\u0004 \u0003עמוקה\u0004 ונותנים בה הרבה שמן, \u0003ו\u0004מתוך כך, \u0003מעשיה\u0004 (הדברים הנעשים בה, העיסה שבה) \u0003רוחשין\u0004 (מתנועעים) בתוכה והינם רכים. ואילו ה\u0003מחבת\u0004 הריהי \u0003צפה\u0004 (שטוחה, שאינה עמוקה), ואין נותנים בה אלא שמן מועט, \u0003ו\u0004מתוך כך \u0003מעשיה\u0004 (הדברים הנעשים בה, העיסה המיטגנת בה) הינם \u0003קשין,\u0004 שאינם רכים.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לדברי \u0003ר' יוסי\u0004 הגלילי שהמרחשת מכוסה והמחבת גלויה, שהרי בתורה לא נאמר כיצד נראים כלים אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שלמד כן, שהרי מנחת ה\u0003מרחשת,\u0004 מתוך \u0003דאתיא ארחושי הלב\u0004 \u0005[ש\u0006היא \u0005באה\u0006 לכפר \u0005על רחשי,\u0006 מחשבות עבירה של \u0005הלב]\u0006 שכן המחשבה נקראת \"רחש\", \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"רחש לבי דבר טוב\"\u0004 (תהלים מה, ב). וכשם שמחשבת הלב מכוסה, אף מנחה זו נעשית בכלי מכוסה. \u0003ו\u0004אילו מנחת ה\u0003מחבת,\u0004 מתוך \u0003דאתיא\u0004 \u0005[ש\u0006היא \u0005באה]\u0006 לכפר על עוונות שהיו ב\u0003מחבואי הפה,\u0004 ברכילות, \u0003והרי הדיבור גלוי, ו\u0004\u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים]\u0006 על אדם המדבר בקול רם שהוא \u0003מנבח נבוחי\u0004 \u0005[נובח נביחות],\u0006 ולכך היא נעשית בכלי גלוי.","ואולם אפשר להקשות על הסבר \u0003זה:\u0004 \u0003אימא איפכא\u0004 \u0005[אמור להיפך],\u0006 ובאופן זה: מנחת ה\u0003מחבת\u0004 היא זו הנעשית בכלי מכוסה, וטעם הדבר — משום \u0003דאתיא\u0004 \u0005[ש\u0006היא \u0005באה]\u0006 לכפר על \u0003מחבואי הלב,\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי לבן ליעקב: \u0003\"למה נחבאת לברח\u0004 ותגנוב אותי...\" (בראשית לא, כו). ואילו מנחת ה\u0003מרחשת\u0004 היא המנחה הנעשית בכלי גלוי, וטעם הדבר — משום \u0003דאתיא ארחושי\u0004 \u0005[ש\u0006היא \u0005באה\u0006 לכפר \u0005על רחשים,\u0006 דיבורים\u0005],\u0006 שכן הדיבור נקרא \"רחש\", \u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים]\u0006 בתיאור האדם המדבר: \u0003הוה מרחשן שיפתותיה\u0004 \u0005[היו שפתיו מרחשות]!\u0006 ומסכמים: לא למד ר' יוסי הגלילי את ההבחנה בין מרחשת למחבת מן הכתובים, \u0003אלא גמרא גמירי לה\u0004 \u0005[מסורת מקובלת היא]\u0006 כי המרחשת מכוסה והמחבת גלויה.","עוד שנינו במשנתנו כי \u0003ר' חנינא בן גמליאל אומר\u0004 שהמרחשת היא עמוקה ואילו המחבת שטוחה (\"צפה\"), ומבררים מה מקור הבחנה זו: ה\u0003מרחשת עמוקה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במנחתה \u0003\"וכל נעשה במרחשת\"\u0004 (ויקרא ז, ט), והרי זה מלמד שהדברים נעשים בכלי שיש לו תוך, והרי שעמוקה היא. ואילו ה\u0003מחבת\u0004 הריהי \u0003צפה\u0004 (שטוחה) — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במחתה באותו כתוב \u0003\"ועל מחבת\"\u0004 — והרי זה מלמד שהדברים נעשים עליה ולא בתוכה, משמע שאין לה תוך.","ועוד בדין המרחשת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בית שמאי אומרים:\u0004 אדם הנודר בלשון \"הרי עלי מנחת מרחשת\", ואף בלשון חסרה \"הרי עלי במרחשת\" — הריהו חייב במנחת מרחשת, ואולם \u0003האומר \"הרי עלי מרחשת\"\u0004 — \u0003יהא מונח\u0004 הדבר בספקו \u0003עד שיבא אליהו\u0004 הנביא, ויתברר מה דינו.","ומסבירים את ספקם של בית שמאי: \u0003מספקא להו\u0004 \u0005[\u0006היה \u0005מסופק להם]\u0006 מדוע נקראו מנחת המרחשת ומנחת המחבת כן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003על שום\u0004 \u0005[שם]\u0006 ה\u0003כלי\u0004 שבו הן נעשות \u0003נקראו,\u0004 שהשמות \"מרחשת\" ו\"מחבת\" מיוחדים הם לכלים, \u0003ו\"מנחת מרחשת\" או \"מנחת מחבת\" משמעה: המנחה הנעשית בכלים אלה.\u0004 \u0003או\u0004 שנקראו המנחות הללו \u0003על שום\u0004 \u0005[שם]\u0006 אופן \u0003מעשיהן\u0004 (עשייתם), ו\"מנחת מרחשת\" משמעה: המנחה הרוחשת בשעת עשייתה, ו\"מנחת מחבת\" משמעה: המנחה הצפה בשעת עשייתה. ומעתה, אם עיקר השם \"מרחשת\" הוא הכלי — זה הנודר \"מרחשת\", חייב בהבאת הכלי הנקרא כן. ואם עיקר השם \"מרחשת\" הוא דרך עשייתה של המנחה — חייב הנודר בהבאת מנחה זו. ומתוך שספק הוא, יהא מונח עד שיבוא אליהו.","\u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 שאין זה ספק, שכן \u0003כלי היה במקדש, ו\"מרחשת\" שמה,\u0004 ואם כן, הנודר \"מרחשת\" — התחייב להביא כלי זה. \u0003ו\u0004מוסיפים בית הלל ומתארים כלי זה: \u0003דומה\u0004 כלי זה \u0003כמין כלבוס\u0004 (יעויין ב\"החיים\") \u0003עמוק,\u0004 שיש בכלי זה שקעים, \u0003וכשבצק מונח בתוכו\u0004 הריהו נכנס לתוך השקעים שבו, ומקבל את צורתם, והריהו \u0003דומה\u0004 \u0003כמין תפוחי\u0004 עצי \u0003הברתים וכמין בלוטי\u0004 (פירות) \u0003היוונים.\u0004","\u0003ו\u0004מתוך ש\u0003אומר\u0004 הכתוב בלשון נפרדת על כל אחד מהכלים הללו, \u0003\"וכל נעשה במרחשת ועל מחבת\",\u0004 ולא נאמרה לשון כוללת \"וכל נעשה במרחשת ובמחבת\" — \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003על שום\u0004 \u0005[שם]\u0006 \u0003הכלים נקראו, ולא על שום\u0004 \u0005[שם]\u0006 \u0003מעשיהם,\u0004 שזו נעשית בתוך הכלי, וזו מעל הכלי.","אדם האומר \u0003\"הרי עלי\u0004 להביא מנחת מאפה הנעשה \u0003בתנור\"\u0004 — \u0003לא יביא\u0004 מנחת \u0003מאפה\u0004 שנעשתה \u0003ב\u0004\u0003כופח\u0004 (כלי אפיה קטן), \u0003ולא\u0004 מנחת \u0003מאפה\u0004 שנעשתה על גבי \u0003רעפים\u0004 (לבנים של חמר שלובנו על גבי האש), \u0003ו\u0004לא מנחת \u0003מאפה\u0004 שנעשתה \u0003ב\u0004\u0003יורות הערביים\u0004 (גומות חפורות באדמה, ומדופנות בטיט, המוסקות באש ומשמשות לאפיה). \u0003ר' יהודה אומר:\u0004 אם \u0003רצה\u0004 — הריהו \u0003מביא\u0004 בנדרו מנחת \u0003מאפה כופח,\u0004 שכן אף הוא בכלל תנור.","והלכה נוספת: האומר \u0003\"הרי עלי מנחת מאפה\u0004 תנור\" — חייב הוא להביא אותה או עשר חלות או עשרה רקיקים, אבל \u0003לא יביא\u0004 אותה \u0003מחצה\u0004 של עשרת הלחמים הללו (חמש) \u0003חלות ומחצה\u0004 (חמש) אחרת \u0003רקיקין.\u0004 ואילו \u0003ר' שמעון מתיר\u0004 להביא מחצה חלות ומחצה רקיקים, \u0003מפני ש\u0004הן החלות והן הרקיקים כתובים במנחת מאפה תנור, והרי \u0003הוא\u0004 איפוא \u0003קרבן אחד.\u0004","שנינו במשנתנו כי חכמים סבורים שאין שאר כלי האפייה (כופח, רעפים, יורות הערבים) נחשבים כתנור לענין מנחת מאפה תנור, ואילו \u0003ר' יהודה סבור שהכופח הוא בכלל תנור. ובענין זה מביאים עוד,\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בכתוב \"וכי תקריב קרבן מנחה \u0003מאפה תנור\"\u0004 (ויקרא ב, ד) בא להדגיש: דווקא מאפה תנור, \u0003ולא מאפה כופח, ולא מאפה רעפים, ולא מאפה יורות הערביים,\u0004 וכשיטת חכמים שבמשנתנו.","ואילו \u0003ר' יהודה אומר:\u0004 לשון \u0003\"תנור\"\u0004 נאמרה בכתוב זה, ונאמרה עוד לשון \u0003\"תנור\"\u0004 בכתוב נוסף (\"וכל מנחה אשר תאפה בתנור...\" שם ז, ט), ושתיהן באות למעט כלי אחר, והרי זה ככל דבר שנאמרו בו לשונות מיעוט \u0003שני פעמים,\u0004 שכלל הוא כי אין מיעוט אחר מיעוט אלא לרבות, ומכאן יש ללמוד \u0003להכשיר מאפה כופח\u0004 שגם הוא בכלל מאפה תנור. \u0003ר' שמעון אומר:\u0004 המלה \u0003\"תנור\" \"תנור\"\u0004 הנאמרת \u0003שני פעמים\u0004 באה ללמדנו שני לימודים, \u0003אחד\u0004 — \u0003שתהא אפייתן בתנור, ואחד\u0004 — \u0003שיהא הקדישן\u0004 (התקדשותה) של המנחה \u0003בתנור,\u0004 ולא בכלי שרת.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 מקבל\u0005]\u0006 \u0003ר' שמעון האי סברא\u0004 \u0005[סברה זו]\u0006 שהתנור מקדש? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכתנו\u0005]\u0006 כי \u0003ר' שמעון אומר: לעולם הוי רגיל לומר\u0004 כי \u0003שתי הלחם ולחם הפנים כשרות\u0004 אם נעשו (לישתם, עריכתם, אפייתם) \u0003ב\u0004תוך ה\u0003עזרה\u0004 שבמקדש, \u0003ו\u0004כמו כן הריהם \u0003כשרות\u0004 אם נעשו \u0003ב\u0004מקום הנקרא \u0003בית פאגי\u0004 המצוי מחוץ לחומת הר הבית. ומתוך שאין הן נפסלות (משום יוצא) בהיותם מחוץ לעזרה, משמע שאין הן מתקדשות בתוך כלי שרת!","\u0003אמר רבא\u0004 בתשובה: אכן לשיטת ר' שמעון אין התנור מקדש, ואשר לדבריו בברייתא כך \u0003אימא\u0004 \u0005[אמור]\u0006 בהם: שני לימודים למדנו. האחד — שתהא אפייתם בתנור, והשני — \u0003שיהא\u0004 גם מעשה \u0003הקדישן\u0004 מפורש, מתחילה צריך שיאמר כי הוא מקדישה \u0003לשום\u0004 \u0005[לשם]\u0006 אפייתה ב\u0003תנור.\u0004","שנינו במשנתנו כי האומר \u0003\"הרי עלי מנחת מאפה\u0004 תנור\" — \u0003לא יביא מחצה\u0004 חלות ומחצה רקיקין, ואילו ר' שמעון מתיר, שלדעתו שניהם קרבן אחד. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר במנחת מאפה תנור \"וכי תקריב קרבן מנחה מאפה תנור\". ומן הנאמר \u0003\"וכי תקריב\"\u0004 יש ללמוד שאין זו חובה, אלא \u0003כש\u0004תרצה ו\u0003תקריב,\u0004 ולימדנו בכך הכתוב \u0003לעשות\u0004 את הבאת מנחת מאפה תנור כ\u0003דבר\u0004 ה\u0003רשות.\u0004","ומן הנאמר עוד \u0003\"קרבן מנחה\"\u0004 — יש ללמוד כדרך \u0003ש\u0004\u0003אמר ר' יהודה: מנין לאומר \"הרי עלי מנחת מאפה\", שלא יביא מחצה\u0004 מעשרת הלחמים \u0003חלות ומחצה רקיקין? תלמוד לומר \"קרבן מנחה\"\u0004 — להורות: \u0003קרבן אחד\u0004 (שיהיו כל העשרה לחמים ממין אחד\u0003)\u0004 \u0003אמרתי לך\u0004 להביא, \u0003ולא שנים ושלשה קרבנות\u0004 ממינים שונים, ושלא כשיטת ר' שמעון.","\u0003אמר לו ר' שמעון\u0004 לר' יהודה בדחיית דבריו:"],["\u0003וכי נאמר\u0004 במנחת מאפה תנור המלה \u0003\"קרבן\" \"קרבן\" שני פעמים,\u0004 אחת במנחת חלות ואחת במנחת רקיקים, שאז יכול היית לומר כי שני מיני קרבן \u0003הם.\u0004 \u0003והלא לא נאמר אלא \"קרבן\"\u0004 פעם \u0003אחד\u0004 (\"וכי תקריב קרבן מנחה מאפה תנור חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן\". ויקרא ב, ד), \u0003ונאמר בו\u0004 באותו \"קרבן\" \u0003חלות ורקיקין,\u0004 לומר ששני אלה הם קרבן אחד.","ו\u0003מעתה\u0004 נסיק, שאם \u0003רצה להביא\u0004 עשר \u0003חלות\u0004 — \u0003מביא\u0004 עשר חלות, ואם רצה להביא עשרה \u0003רקיקין\u0004 — \u0003מביא\u0004 רקיקים, ואם רצה להביא \u0003מחצה\u0004 מהן (חמש) \u0003חלות ומחצה\u0004 מהן (חמישה) \u0003רקיקין\u0004 — הריהו \u0003מביא. ו\u0004כשמביא חמש חלות וחמישה רקיקים כיצד הוא נוהג? הריהו \u0003בוללן\u0004 (מערבב את כולם) \u0003וקומץ משניהם, ואם\u0004 אירע ש\u0003קמץ ועלה בידו\u0004 רק \u0003מ\u0004סוג \u0003אחד\u0004 (מחלות או מרקיקים בלבד) \u0003על שניהם\u0004 — \u0003יצא\u0004 בכך ידי חובה. \u0003ר' יוסי בר\u0004 (בנו של) \u0003ר' יהודה אומר: מנין\u0004 לנו \u0003ל\u0004דינו של אדם ה\u0003אומר \"הרי עלי מנחת מאפה\", שלא יביא מחצה חלות ומחצה רקיקין?\u0004 — שכן \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בדין המנחות \u0003\"וכל מנחה אשר תאפה בתנור\"\u0004 (שם ז, ט), וממשיך הכתוב ואומר \u0003\"וכל נעשה במרחשת ועל מחבת לכהן המקריב אתה לו תהיה\",\u0004 ובפסוק שלאחריו \u0003נאמר\u0004 \u0003\"וכל מנחה בלולה בשמן וחרבה לכל בני אהרן תהיה\u0004 איש כאחיו\" (שם י).","","הקיש הכתוב את דינה של מנחת מאפה תנור לדין מנחת מרחשת ומנחת מחבת, שבשתיהן נאמר \"וכל\", וכן לדינה של מנחת נדבה (\"בלולה בשמן\") ומנחת חוטא (\"חרבה\"), שכן אף בהן נאמר \"וכל\" — ללמדנו: \u0003מה \"וכל\" האמור למטה\u0004 (מאוחר יותר), במנחת מרחשת ומנחת מחבת, וכמו כן במנחת נדבה ומנחת חוטא — מדבר ב\u0003שני מינין\u0004 של מנחות \u0003חלוקין\u0004 (שונים). \u0003אף \"וכל\" האמור למעלה\u0004 (מקודם, בתחילת פסוק ט), במנחת מאפה תנור — ב\u0003שני מינין חלוקין\u0004 מדובר בו. ומכאן, שאין להביא מחצה מזה ומחצה מזה ולצרפם. ומבררים: \u0003ור' יהודה,\u0004 שלדעתו החלות והרקיקים שבמנחת מאפה תנור הם שני מיני קרבנות, והרי \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' שמעון\u0004 בדחיית ראיה זו, שנאמר בכתוב \u0003\"קרבן\" פעם אחת בלבד, ומה משיב ר' יהודה על טענה זו? ומתרצים:\u0004 \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 בתשובה: אף שלא נאמר בכתוב \"קרבן\" שתי פעמים, ואולם \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"בשמן\" \"בשמן\"\u0004 שתי פעמים (\"...חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן\") — הרי זה \u0003כמאן דכתיב\u0004 \u0005[כמו שכתוב]\u0006 \u0003\"קרבן\" \"קרבן\" דמי\u0004 \u0005[נחשב],\u0006 ללמדנו כי שני מיני קרבן הם. ושואלים שוב: \u0003ור' שמעון,\u0004 מה משיב הוא על טענתו זו של ר' יהודה? ומתרצים: נכתבה המלה \"בשמן\" \"בשמן\" שתי פעמים, לצורך לימוד אחר. שכן \u0003אי לא כתיב\u0004 \u0005[אם לא היה כתוב]\u0006 \u0003\"בשמן\" \"בשמן\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003דווקא\u0004 באופן זה באה מנחת מאפה תנור, \u0003מחצה חלות ומחצה רקיקין, אבל חלות לחודייהו\u0004 \u0005[לחוד]\u0006 \u0003ורקיקין לחודייהו\u0004 \u0005[לחוד]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 באות. לכך \u0003קא משמע לן\u0004 \u0005[\u0006הכתוב \"בשמן\" \"בשמן\" \u0005משמיע לנו]\u0006 שבאה מנחת מאפה תנור, או בעשר חלות, או בעשרה רקיקים, או בעשרה המצורפים מזה ומזה. ומבררים עוד: בברייתא הובאו דבריו של ר' יוסי בנו של ר' יהודה האומר כי החלות והרקיקים שני מינים הם, ומה צורך להשמיענו זאת, שהרי שיטת \u0003ר' יוסי בר' יהודה היינו\u0004 \u0005[זוהי]\u0006 כשיטת \u0003אבוה\u0004 \u0005[אביו,\u0006 ר' יהודה\u0005]\u0006 הנזכרת בברייתא? ומסבירים: צריך היה להביא אף את דבריו של ר' יוסי בנו של ר' יהודה, שכן \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, במקרה \u0003דאי\u0004 \u0005[שאם]\u0006 עבר אדם ו\u0003עבד\u0004 \u0005[עשה]\u0006 מנחת מאפה תנור המצורפת מחלות ומרקיקים, שלדעתו של ר' יהודה — הריהי כשרה בדיעבד, ולדעתו של ר' יוסי בנו — איננה כשרה אף בדיעבד. \u0003ר' ישמעאל אומר:\u0004 כאשר זמן הקרבת ה\u0003עומר\u0004 (למחרת יום הראשון של חג הפסח, בששה עשר בניסן) \u0003היה בא\u0004 (חל) \u0003ב\u0004יום ה\u0003שבת\u0004 — מצמצמים בעבודה ולא היו קוצרים לצורך העומר אלא \u0003שלש סאין\u0004 (איפה) שעורים בלבד. ומהם היו מוציאים עשירית האיפה קמח מובחר. \u0003ו\u0004אם חל זמן הקרבת \u0003העומר\u0004 \u0003ב\u0004יום \u0003חול\u0004 — היו קוצרים \u0003מחמש\u0004 סאים, ומהן היו מוציאים את עשרון הקמח לצורך המנחה. \u0003וחכמים\u0004 \u0003אומרים: אחד\u0004 (בין) ביום \u0003שבת ואחד\u0004 (ובין) ביום \u0003חול\u0004 — \u0003משלש\u0004 סאים בלבד \u0003היה\u0004 העומר \u0003בא.\u0004 ועוד נחלקו חכמים בדרך קצירת העומר בשבת ובחול, ש\u0003ר' חנינא סגן הכהנים אומר:\u0004 אם חל ששה עשר בניסן \u0003ב\u0004יום ה\u0003שבת\u0004 — \u0003היה\u0004 העומר \u0003נקצר ביחיד\u0004 (על ידי אדם אחר), \u0003ו\u0004הקצירה היתה נעשית \u0003ב\u0004אמצעות \u0003מגל אחד, ו\u0004השיבולים הקצורות היו מוכנסות \u0003ב\u0004תוך \u0003קופה\u0004 (סל) \u0003אחת, ו\u0004אולם אם חל ששה עשר בניסן \u0003ב\u0004יום \u0003חול\u0004 — היה העומר נקצר \u0003ב\u0004ידי \u0003שלשה\u0004 קוצרים, והשיבולים הקצורות היו ניתנות \u0003ב\u0004תוך \u0003שלש קופות, ו\u0004הקצירה היתה נעשית באמצעות \u0003שלש מגלות. וחכמים אומרים: אחד\u0004 ביום \u0003שבת ואחד\u0004 ביום \u0003חול\u0004 — הקצירה נעשית \u0003ב\u0004ידי \u0003שלשה\u0004 קוצרים, וניתנות השיבולים הקצורות \u0003ב\u0004תוך \u0003שלש קופות, ו\u0004היתה הקצירה נעשית \u0003ב\u0004אמצעות \u0003שלש מגלות.\u0004","","","","","","","שנינו במשנתנו שנחלקו חכמים בשאלה מכמה סאים שעורים היה בא עשרון הקמח למנחת העומר, שלדעת ר' ישמעאל אם זמן הבאת העומר חל בשבת — בא העשרון משלוש סאים, ואם חל ביום חול — בא העשרון מחמש סאים, ואילו לדעת חכמים, בין כשחל ביום שבת ובין כשחל ביום חול — בא העשרון משלוש סאים. ודנים בשיטותיהם, \u0003בשלמא רבנן\u0004 \u0005[נניח,\u0006 מובנת היא שיטת \u0005חכמים],\u0006 שאינם מחלקים בדין העומר בין אם חל זמנו ביום חול או בשבת, שכן \u0003קא סברי\u0004 \u0005[הם סבורים]\u0006 כי \u0003עשרון\u0004 קמח \u0003מובחר\u0004 אף \u0003ב\u0004ניפוי מ\u0003שלשה סאין\u0004 שעורים הוא \u0003אתי\u0004 \u0005[בא],\u0006 \u0003ו\u0004לכן \u0003לא שנא\u0004 \u0005[לא שונה]\u0006 דין הכנת העומר \u0003ב\u0004יום \u0003חול ולא שנא\u0004 \u0005[ולא שונה]\u0006 דינו \u0003ב\u0004יום ה\u0003שבת,\u0004 שבשניהם קוצרים בתחילה שלוש סאים בלבד. \u0003אלא ר' ישמעאל\u0004 המבחין בין שבת ויום חול, \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]:\u0006 ש\u0003עשרון\u0004 קמח \u0003מובחר לא אתי\u0004 \u0005[לא בא]\u0006 \u0003אלא מ\u0004תוך \u0003חמש\u0004 סאים — \u0003אפילו בשבת נמי\u0004 \u0005[גם כן]\u0006 יעשה מחמש סאים! ו\u0003אי\u0004 \u0005[אם]\u0006 הוא סבור כי עשרון מובחר אף \u0003משלש\u0004 סאים הוא \u0003אתי\u0004 \u0005[בא]\u0006 — \u0003אפילו בחול נמי\u0004 \u0005[גם כן]\u0006 לא יביא אלא משלוש סאים!","","\u0003אמר רבא\u0004 בהסבר שיטת ר' ישמעאל: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' ישמעאל\u0004 כי \u0003עשרון מובחר בלא טירחא\u0004 מרובה הריהו \u0003אתי\u0004 \u0005[בא]\u0006 רק \u0003מחמש\u0004 סאים, ואולם \u0003בטירחא\u0004 מרובה, שירבה בניפוי הקמח יותר מהרגיל, הריהו \u0003אתי\u0004 \u0005[בא]\u0006 גם \u0003משלש\u0004 סאים. ולכן, כשחל זמן הבאת העומר \u0003ב\u0004יום \u0003חול\u0004 — \u0003מייתינן\u0004 \u0005[מביאים אנו]\u0006 את העשרון דווקא \u0003מ\u0004תוך \u0003חמש\u0004 סאים, משום \u0003דהכי שביחא מילתא\u0004 \u0005[שכך משובח\u0006 יותר \u0005הדבר].\u0006 ואולם כשחל זמן הבאת העומר \u0003ב\u0004יום \u0003שבת\u0004 — אומרים אנו כי \u0003מוטב שירבה במלאכה אחת, ב\u0004מלאכת \u0003הרקדה\u0004 (ניפוי) של שלוש סאים, \u0003ואל ירבה במלאכות הרבה\u0004 בשבת, בקצירה ושאר מלאכות, בשתי הסאים הנוספות.","כיון שאמרו בהסבר שיטת ר' ישמעאל שהיא משום מניעת טירחה יתירה בשבת, מביאים עוד מה ש\u0003אמר רבה: ר' ישמעאל\u0004 במשנתנו, \u0003ור' ישמעאל בנו של ר' יוחנן בן ברוקה אמרו דבר אחד,\u0004 כלומר, הולכים בשיטה אחת, שיש למעט ככל האפשר בטירחה ביום השבת אף בדבר המותר. ומפרטים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יום\u0004 \u0003ארבעה עשר\u0004 בניסן (זמן הקרבת קרבן הפסח) \u0003שחל להיות ב\u0004יום ה\u0003שבת,\u0004 הריהו \u0003מפשיט את\u0004 עורו של קרבן \u0003הפסח\u0004 (על מנת להוציא מגופו את האימורים הקרבים) רק \u0003עד החזה,\u0004 אלו \u0003דברי ר' ישמעאל בנו של ר' יוחנן בן ברוקה. וחכמים אומרים:\u0004 הריהו מפשיט את עור הקרבן \u0003עד שיפשיט את כולו.\u0004","ומסבירים את מחלוקתם: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' ישמעאל בנו של ר' יוחנן בן ברוקה התם\u0004 \u0005[שם,\u0006 בדין הפשטת הפסח\u0005]\u0006 שמפשיט רק עד החזה ולא יותר משום ש\u0003כל היכא\u0004 \u0005[היכן,\u0006 אופן\u0005]\u0006 שבו \u0003אפשר\u0004 להגיע ביום השבת אל התוצאה הדרושה בדרך שיש בה מלאכה מועטת, \u0003לא טרחינן\u0004 \u0005[אין\u0006 אנו \u0005טורחים]\u0006 ועושים מלאכה מרובה (ולכך, מפשיטים את עור קרבן הפסח רק עד החזה, שכן די בכך כדי להוציא את אימוריו). ומעתה נאמר, כי \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בהבאת העומר, \u0005גם כן]\u0006 סבור ר' ישמעאל בנו של ר' יוחנן בן ברוקה ש\u0003כיון\u0004 ש\u0003אפשר\u0004 להביא עשרון משלוש סאים בניפוי מרובה — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים]\u0006 ומביאים אותו מחמש סאים, וכשיטת ר' ישמעאל.","ודוחים את דברי רבה: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח ששוות הן השיטות, ואף ר' ישמעאל סבור שאין מפשיטים את עור קרבן הפסח בשבת אלא עד החזה, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל הכא\u0004 \u0005[כאן]\u0006 את שיטתו זו שיש למעט במלאכות בשבת, \u0003אלא\u0004 משום \u0003דליכא\u0004 \u0005[שאין]\u0006 כרוך בדבר כל \u0003בזיון\u0004 ל\u0003קדשים,\u0004 בכך שמביאים את העשרון משלוש סאים ולא מחמש. \u0003אבל התם\u0004 \u0005[שם]\u0006 בהפשטת עור הפסח \u0003דאיכא\u0004 \u0005[שיש]\u0006 בדבר משום \u0003בזיון קדשים,\u0004 שנשאר הקרבן כך, עורו מופשט למחצה, עד הלילה, והריהו נראה כנבילה,"],["\u0003אימא\u0004 \u0005[\u0006יכול אני \u0005לומר]\u0006 \u0003לך\u0004 כי ר' ישמעאל \u0003כ\u0004שיטתם של \u0003רבנן סבירא ליה\u0004 \u0005[חכמים\u0006 החולקים על ר' ישמעאל בנו של ר' יוחנן בן ברוקה \u0005הוא סבור],\u0006 ולדעתו יש להפשיט את עור קרבן הפסח כולו, ומוסיפים,","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לפרוך לצד השני: שמא \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא\u0004 אלא דווקא \u0003התם\u0004 \u0005[שם,\u0006 בהפשטת עור הפסח\u0005],\u0006 ואין טעמו \u0003אלא\u0004 משום שכאשר מגיע המפשיט את עור הקרבן לחזהו — כבר \u0003איתעביד ליה\u0004 \u0005[נעשה לו,\u0006 התקיים\u0005]\u0006 \u0003צורך גבוה\u0004 (עבודת הקודש), שהרי עתה יכול הוא להוציא את האימורים, ואין בהמשך הפשטת עור הקרבן עוד ענין לעבודת הקודש, \u0003ו\u0004משום כך סבור ר' ישמעאל בנו של ר' יוחנן בן ברוקה כי \u0003לא צריך\u0004 עוד \u0003אחולי\u0004 \u0005[לחלל]\u0006 \u0003שבת\u0004 ולהוסיף ולפשוט את העור כולו. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בדין הבאת העומר\u0005]\u0006 שעדיין \u0003לא איתעביד ליה\u0004 \u0005[לא נעשה לו]\u0006 \u0003צורך גבוה,\u0004 שהרי מובחר הדבר כאשר העשרון בא מחמש סאים, \u0003ו\u0004לשם כך \u0003צריך\u0004 עוד \u0003לאחולי\u0004 \u0005[לחלל]\u0006 \u0003שבת\u0004 במלאכות נוספות — \u0003אימא\u0004 \u0005[יכול\u0006 אני \u0005לומר]\u0006 לך כי ר' ישמעאל בנו של ר' יוחנן בן ברוקה \u0003כ\u0004שיטת \u0003רבנן סבירא ליה\u0004 \u0005[חכמים\u0006 החולקים על ר' ישמעאל \u0005הוא סבור]!\u0006","\u0003אלא אמר רבה\u0004 באופן שונה: \u0003ר' ישמעאל\u0004 שבתחילת משנתנו \u0003ור' חנינא סגן הכהנים\u0004 שבסוף משנתנו שניהם \u0003אמרו דבר אחד.\u0004 שר' ישמעאל סבור כר' חנינא סגן הכהנים בדרך הקצירה בשבת, ור' חנינא סבור כר' ישמעאל במספר הסאים מהן בא העומר בשבת. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' חנינא סגן הכהנים אומר:\u0004 אם חל ששה עשר בניסן (יום הקרבת העומר) \u0003ב\u0004יום ה\u0003שבת\u0004 היה העומר \u0003נקצר\u0004 \u0003ב\u0004ידי אדם \u0003יחיד,\u0004 ו\u0003במגל אחד\u0004 לקצירה, \u0003ו\u0004השיבולים הקצורות ניתנות \u0003ב\u0004תוך \u0003קופה אחת.\u0004 \u0003ו\u0004אילו כאשר חל \u0003ב\u0004יום \u0003חול\u0004 — העומר היה נקצר \u0003ב\u0004ידי \u0003שלשה\u0004 קוצרים, והשיבולים הקצורות ניתנות \u0003ב\u0004תוך \u0003שלש קופות ו\u0004היו קוצרים \u0003בשלש מגלות. וחכמים\u0004 חולקים על כך ו\u0003אומרים\u0004 כי \u0003אחד\u0004 (בין) \u0003ב\u0004\u0003שבת ואחד\u0004 (ובין) ב\u0003חול\u0004 — השיבולים הקצורות ניתנות \u0003ב\u0004תוך \u0003שלש קופות ו\u0004נקצרות \u0003בשלש מגלות.\u0004","ומסבירים כיצד משתווה דעת ר' חנינא סגן הכהנים לדעת ר' ישמעאל, \u0003מי לא קאמר\u0004 \u0005[האם לא אמר]\u0006 \u0003ר' חנינא סגן הכהנים התם\u0004 \u0005[שם]\u0006 שקוצרים בשבת באדם אחד ולא בשלושה, שמ \u0003כיון\u0004 ש\u0003אפשר\u0004 לקצור באדם אחד — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים]\u0006 שיעשו את הקצירה כמה אנשים. ומכאן נסיק, \u0005כי\u0006 \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בשאלה בכמה סאים בא העומר בשבת, \u0005גם כן]\u0006 יש \u0003לומר כי\u0004 \u0003כיון\u0004 ש\u0003אפשר\u0004 להביא עשרון קמח לעומר משלוש סאים — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים],\u0006 מתירים להוסיף מלאכה בשבת ולהביא את העומר מחמש סאים, שיש בדבר ריבוי מלאכות, וכר' ישמעאל.","ודוחים את ההשוואה: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 לנו שמשתווים בדעותיהם ר' ישמעאל ור' חנינא סגן הכהנים? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל\u0004 את דינו \u0003הכא\u0004 \u0005[כאן,\u0006 בענין מספר הסאים בהבאת העומר בשבת\u0005],\u0006 שאין מרבים במלאכה, \u0003אלא\u0004 רק משום \u0003דליכא פרסומי מילתא\u0004 \u0005[שאין כאן,\u0006 בהבאה מחמש סאים, \u0005פרסום הדבר\u0006 יותר מאשר בהבאה משלוש סאים\u0005],\u0006 \u0003אבל התם, דאיכא פרסומי מילתא\u0004 \u0005[שם,\u0006 בדרך הקצירה, \u0005שיש פרסום דבר]\u0006 כאשר העומר נקצר בשבת בשלושה יותר מכאשר הוא נקצר באחד — \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' חנינא סגן הכהנים \u0003סבירא ליה\u0004 \u0005[סבור הוא].\u0006","ומקשים עוד על ההשוואה אף מצד שני, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נקשה: מנין לנו שסבור ר' חנינא סגן הכהנים כר' ישמעאל, שמא \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' חנינא סגן הכהנים\u0004 את דינו שקוצרים באחד ולא בשלושה, שאין מרבים במלאכה, אלא דווקא \u0003התם\u0004 \u0005[שם,\u0006 בדרך הקצירה בשבת\u0005],\u0006 וטעמו: משום \u0003דאי בחד\u0004 \u0005[שאם,\u0006 בין \u0005באחד]\u0006 הקוצר, \u0003אי\u0004 \u0005[אם,\u0006 בין\u0005]\u0006 \u0003בשלשה\u0004 הקוצרים — \u0003צורך גבוה\u0004 (הנדרש לעבודת הקודש) \u0003מיתעביד\u0004 \u0005[נעשה]\u0006 \u0003כהלכתו,\u0004 ולכך אין מרבים במלאכה בשבת, ואין קוצר אלא אחד. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 לגבי מספר הסאים\u0005],\u0006 ש\u0003לא איתעביד\u0004 \u0005[לא נעשה]\u0006 \u0003כהלכתו צורך גבוה,\u0004 שהרי עשרון משובח ניטל מחמש סאים — \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' ישמעאל \u0003סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ואפשר ששיטת ר' חנינא היא שמביאים מחמש סאים בשבת!","\u0003אלא אמר רב אשי\u0004 באופן שונה: \u0003ר' ישמעאל\u0004 שבמשנתנו הסבור שאין מרבים במלאכת השבת אף במקום המותר, \u0003ור' יוסי\u0004 שדבריו יובאו להלן, שניהם \u0003אמרו דבר אחד\u0004 בענין ריבוי מלאכה בשבת. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין עדות ראיית מולד הלבנה: \u0003בין שנראה\u0004 הירח החדש \u0003בעליל\u0004 (בגלוי לכל), \u0003ובין שלא נראה בעליל\u0004 — עדים שראו אותו בחידושו \u0003מחללין עליו\u0004 לצורך עדותם \u0003את השבת. ר' יוסי אומר: אם נראה בעליל\u0004 — \u0003אין מחללין עליו את השבת,\u0004 מפני שמן הסתם ראו אותו אף הדיינים, ויכולים לקדש את החודש על פי ראייתם.","ומסבירים כיצד משתווה דעת ר' יוסי זו לדעתו של ר' ישמעאל שבמשנתנו, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' יוסי\u0004 בטעם דעתו \u0003התם\u0004 \u0005[שם,\u0006 בעדות המולד\u0005],\u0006 שמ \u0003כיון\u0004 ש\u0003אפשר\u0004 שיתקדש החודש אף בלא עדותם של אלה — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים],\u0006 מתירים להוסיף מלאכה בשבת, שיבואו העדים להעיד על ידי חילול שבת. ומכאן נסיק כי \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בשאלה מכמה סאים \u0005מביאים את העומר בשבת,\u0006 \u0005גם כן]\u0006 יש לומר כדעת ר' יוסי, כי \u0003כיון\u0004 ש\u0003אפשר\u0004 להביא עשרון משלוש סאים — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים],\u0006 מתירים להוסיף מלאכה בשבת ולהביא מחמש סאים.","ודוחים את ההשוואה: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 לנו שמשתווים ר' ישמעאל ור' יוסי בדעותיהם? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו \u0003כי\u0004 \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל\u0004 את דינו אלא \u0003הכא\u0004 \u0005[כאן,\u0006 במספר הסאים שמהן מביאים את העומר בשבת\u0005]\u0006 בלבד, שאין מתירים להוסיף בחילול שבת, \u0003אלא\u0004 משום \u0003דליכא\u0004 \u0005[שאין כאן]\u0006 לחשוש שאם לא נתיר להם להביא מחמש סאים, יבואו לומר כי אין מביאים את העומר בשבת, ו\u0003נמצאת\u0004 שבכך \u0003אתה\u0004 גורם ו\u0003מכשילן לעתיד לבא\u0004 שלא יביאוהו, שהרי בפועל הביאו עומר בשבת, \u0003אבל התם\u0004 \u0005[שם,\u0006 בעדות החודש\u0005]\u0006 יש לחשוש, שאם לא נתיר לעדים לחלל שבת כדי להעיד על מולד הלבנה, \u0003נמצאת\u0004 שבכך \u0003אתה מכשילן לעתיד לבא,\u0004 שלא ילכו להעיד על מולד הלבנה שראו, ונמצא איפוא שנגרם קלקול בכך — \u0003אימא\u0004 \u0005[אמור]\u0006 כי ר' ישמעאל \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' יוסי \u0003סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ואף דעתו בדין עדות החודש היא שמחללים את השבת, אף כשנראתה הלבנה בעליל.","ומקשים על ההשוואה מהצד השני, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נקשה: מנין לנו שסבור ר' יוסי כר' ישמעאל, שמא \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי\u0004 אלא \u0003התם\u0004 \u0005[שם]\u0006 בלבד, שאין מתירים לחלל שבת לעדים, ואין זה \u0003אלא\u0004 משום \u0003דליכא\u0004 \u0005[שאין כאן]\u0006 \u0003צורך גבוה,\u0004 שהרי אין זה מכלל עבודות המקדש והקרבנות, \u0003ולא ניתנה שבת לדחות\u0004 בעדות החודש, אלא אם כן יש צורך בכך. \u0003אבל הכא, דאיכא\u0004 \u0005[כאן,\u0006 בהבאת העומר, \u0005שיש כאן]\u0006 משום \u0003צורך גבוה, וניתנה שבת לדחות\u0004 בהבאת העומר משלוש סאים — \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' ישמעאל \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ר' יוסי, שמכיון שנדחית השבת בשל העומר תידחה אף לענין שיביאוהו מחמש סאים!","ועוד בענין ריבוי מלאכות בשבת בדבר שהותר בשבת, \u0003איתמר\u0004 \u0005[נאמר]:\u0006 מי שעבר ו\u0003שחט\u0004 בשבת \u0003שתי חטאות של ציבור,\u0004 כגון שעירי רגלים (שדוחים את השבת, כשאר קרבנות ציבור שקבוע להם זמן), \u0003ו\u0004אף ש\u0003אינו צריך\u0004 לשחוט \u0003אלא\u0004 חטאת \u0003אחת\u0004 בלבד. והיה זה מתוך שסבר בטעות שכיון שחטאת ציבור דוחה את השבת, יכול הוא להוסיף ולשחוט חטאת ציבור אחרת שאין זמנה קבוע. \u0003אמר רבה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אמי:\u0004 \u0003חייב\u0004 קרבן חטאת \u0003על\u0004 שחיטתה של חטאת הציבור \u0003השניה,\u0004 שנשחטה שלא כדין, \u0003ופטור\u0004 מקרבן \u0003על\u0004 שחיטת חטאת הציבור \u0003הראשונה.\u0004 \u0003ו\u0004חייב על שחיטת השניה, \u0003אפילו\u0004 אם בסופו של דבר \u0003נתכפר לו\u0004 לציבור \u0003ב\u0004חטאת ה\u0003שניה\u0004 ולא בראשונה (וכגון שנשפך דמה של החטאת הראשונה). ואף שהיה מקום לומר שלא יתחייב על שחיטת השניה, שהרי התכפר בה הציבור. \u0003ו\u0004עוד, חייב על שחיטת השניה, \u0003אפילו\u0004 אם \u0003נמצאת\u0004 לפני שחיטת החטאת השניה, כי החטאת ה\u0003ראשונה\u0004 הינה \u0003כחושה\u0004 ואינה ראויה לבא לקרבן, ושואלים:","\u0003ומי\u0004 \u0005[והאם]\u0006 אמנם \u0003אמר רבה הכי\u0004 \u0005[כך],\u0006 שחייב על שחיטת השניה אפילו כאשר התברר כי הראשונה שנשחטה הינה כחושה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה: היו\u0004 עומדות \u0003לפניו\u0004 לשחיטה, בשבת, \u0003שתי חטאות\u0004 ציבור, \u0003אחת\u0004 מהן \u0003שמינה\u0004 הראויה יותר להיקרב, \u0003ואחת\u0004 מהן \u0003כחושה,\u0004 וטעה ו\u0003שחט\u0004 את ה\u0003שמינה\u0004 כדין, \u0003ואחר כך\u0004 עמד ו\u0003שחט\u0004 אף את השניה ה\u0003כחושה\u0004 — הרי זה \u0003חייב\u0004 על שחיטת השניה הכחושה, שלא היה לו לשוחטה. ואולם אם שחט בתחילה את ה\u0003כחושה, ואחר כך\u0004 עמד ושחט את ה\u0003שמינה\u0004 — הריהו \u0003פטור\u0004 על השחיטה השניה, לפי שנהג כראוי. \u0003ולא עוד\u0004 \u0003אלא ש\u0004אף בית דין מורים \u0003ו\u0004\u0003אומרים לו\u0004 במקרה שכזה: \u0003הבא\u0004 את החטאת ה\u0003שמינה לכתחלה, ושחוט\u0004 אותה!","ומתרצים את הסתירה בדברי רבה: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי אכן סבור רבה כפי ששנינו בשמו בברייתא השניה, \u0003ו\u0004\u0003סמי\u0004 \u0005[מחק]\u0006 את מה שנאמר בדין השוחט את השמנה כשנמצאה הראשונה \u0003כחושה מקמייתא\u0004 \u0005[מ\u0006המאמר \u0005הראשון]\u0006 של רבה, שלא אמר כן רבה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת: אין לפנינו סתירה בדברי רבה, שכן ההלכה \u0003ההיא\u0004 האומרת \u0005שחייב על שחיטת השניה אף כאשר נמצאה הראשונה כחושה,\u0006 \u0003ר' אמי\u0004 הוא ש\u0003אמרה\u0004 ולא רבה.","שנינו למעלה שמי שהיו לפניו שתי חטאות, ושחט את שתיהן בשבת, הריהו פטור על שחיטת השניה אם נמצאה הראשונה כחושה. ובעקבות דברים אלה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 את הבעיה הבאה: אם אמנם \u0003נמצאת הראשונה כחושה,\u0004 אלא שהדבר התגלה רק \u0003ב\u0004בדיקת \u0003בני מעיין\u0004 לאחר שנשחטה, \u0003מהו\u0004 הדין? ומציג רבינא את צדדי הבעיה: האם \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003מחשבתו אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003ו\u0004הרי \u0003גברא\u0004 \u0005[האיש]\u0006 ששחט את השניה לאחר שנשחטה הראשונה, לא ידע בשעה ששחט את השניה שהראשונה היא כחושה, ו\u0003ל\u0004מעשה \u0003של\u0004 \u0003איסורא קא מיכוין\u0004 \u0005[איסור הוא התכוון],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003מעשיו,\u0004 מה שבפועל נעשה על ידו, \u0003אזלינן\u0004 \u0005[אנו הולכים],\u0006 והרי עתה התברר שנהג \u0005כראוי כששחט את השניה?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרבינא בפתרון בעייתו: \u0003לאו היינו\u0004 \u0005[האם אין זה]\u0006 דבר הנלמד ממשמעות מחלוקת \u0003רבה ורבא\u0004 בענין אחר. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 בדינו של אדם ש\u0003שמע שטבע תינוק בים,\u0004 ועמד אותו אדם \u0003ופרש\u0004 ביום השבת \u0003מצודה\u0004 (מלכודת דגים) באותו מקום על מנת \u0003להעלות\u0004 (לדוג) במצודה זו \u0003דגים\u0004 (ולא כדי להציל את התינוק), \u0003ו\u0004אכן \u0003העלה\u0004 בה \u0003דגים\u0004 — הרי זה \u0003חייב\u0004 משום איסור צידה בשבת. אבל אם התכוון בפרישת המצודה על מנת \u0003להעלות\u0004 בה \u0003דגים, ו\u0004אולם \u0003העלה\u0004 בה גם \u0003דגים ו\u0004גם את ה\u0003תינוק\u0004 שטבע, מה דינו? \u0003רבא אמר: חייב,\u0004 שהרי התכוון להעלות דגים ואף העלה אותם. \u0003ו\u0004אילו \u0003רבה אמר: פטר,\u0004 שהרי בפועל עשה דבר בהיתר, משום שהוא מציל נפש.","ומעתה נאמר, לשיטת רבא המחייב על פרישת המצודה, אף שבפועל הציל את התינוק, משום שאחר מחשבתו אנו הולכים, \u0003ו\u0004אף לשיטת רבה הפוטר בפרישת המצודה, יש לומר כי \u0003עד כאן רבה לא קא פטר\u0004 \u0005[אינו פוטר]\u0006 \u0003אלא\u0004 מן הטעם \u0003ש\u0004\u0003כיון\u0004 שאותו אדם \u0003שמע\u0004 שטבע תינוק, ועמד ופרש מצודת דגים, \u0003אמרינן נמי\u0004 \u0005[אומרים אנו]\u0006 שהיתה \u0003דעתיה\u0004 \u0005[דעתו,\u0006 כוונתו\u0005]\u0006 בפרישת המצודה גם על מנת להעלות בה את ה\u0003תינוק\u0004 \u0005שטבע באותו מקום בים, וכיון שהעלה במצודה את התינוק, לכך פטר רבה.\u0006 \u0003אבל\u0004 אם \u0003לא שמע\u0004 אותו אדם שטבע תינוק בים, ופרש מצודה על מנת להעלות בה דגים, אף שבפועל העלה בה גם את התינוק — \u0003לא\u0004 פטור. אף שבפועל הועיל מעשה פרישת המצודה להעלאת התינוק, כיון שאחר מחשבתו אנו הולכים. ונמצאנו למדים כי הכל סבורים שאחר מחשבתו אנו הולכים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שבאופן זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרבינא בפתרון בעייתו: \u0003היינו פלוגתייהו\u0004 \u0005[זהו\u0006 כ\u0005מחלוקתם]\u0006 של \u0003רבה ורבא. דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003שמע שטבע תינוק בים,\u0004 \u0003ופרש מצודה להעלות\u0004 בה \u0003דגים, ו\u0004אכן \u0003העלה\u0004 בה \u0003דגים\u0004 — \u0003חייב.\u0004 אבל במקרה שאמנם פרש את המצודה \u0003להעלות\u0004 בה \u0003דגים ו\u0004אולם \u0003העלה\u0004 בה \u0003תינוק ודגים,\u0004 חלוקות הדעות, ש\u0003רבה אמר:\u0004 הריהו \u0003פטור\u0004 על פרישת המצודה, \u0003ו\u0004אילו \u0003רבא אמר\u0004 ש\u0003חייב\u0004 על פרישת המצודה. ומסבירים את דעותיהם: \u0003רבה אמר\u0004 ש\u0003פטור\u0004 על פרישת המצודה — כי \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003מעשיו,\u0004 והרי נמצא שבמעשהו זה העלה את התינוק, ולכך הריהו פטור. \u0003ו\u0004אילו \u0003רבא אמר\u0004 ש\u0003חייב\u0004 על פרישת המצודה — כי \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003מחשבתו,\u0004 ומחשבתו היתה על מנת להעלות דגים, ולכך הריהו חייב. ונמצא איפוא שבעייתו של רבינא תלויה במחלוקת זו שבין רבה ורבא.","ועוד בענין ריבוי מלאכה בשבת, בדבר שהותר לעשות בשבת, \u0003אמר רבה: חולה\u0004 שיש בו פיקוח נפש, \u0003שאמדוהו\u0004 (שהעריכו) הרופאים שלצורך רפואתו הוא זקוק \u0003לגרוגרת\u0004 (תאנה) \u0003אחת,\u0004 וקמו \u0003ורצו עשרה בני אדם\u0004 ביום השבת, וקטפו \u0003והביאו עשרה גרוגרות בבת אחת\u0004 — אף שלא נצרך החולה אלא לגרוגרת אחת, כולם \u0003פטורין,\u0004 מפני שכולם עשו בהיתר. ו\u0003אפילו\u0004 קטפו את התאנים לא באותו זמן, אלא \u0003בזה אחר זה\u0004 — הריהם פטורים. ולא עוד אלא \u0003אפילו קדם והבריא\u0004 החולה מיד לאחר שאכל את הגרוגרת ה\u0003ראשונה\u0004 — כולם פטורים.","ובעקבות הדברים הללו, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 את הבעיה הבאה: \u0003חולה שאמדוהו\u0004 הרופאים שצריך לרפואתו \u0003ל\u0004אכול \u0003שתי גרוגרות. ויש\u0004 לפנינו עץ תאנה שיש עליו אמנם \u0003שתי גרוגרות\u0004 התלויות \u0003בשתי עוקצין,\u0004 ונדרש הקוטף לעשות שני מעשי קטיפה. \u0003ו\u0004אילו בענף אחר יש \u0003שלש\u0004 גרוגרות התלויות \u0003בעוקץ אחת,\u0004 ואין הקוטף נדרש אלא לקטיפה אחת. ומעתה הבעיה היא: \u0003הי מינייהו מייתינן\u0004 \u0005[איזו מהן אנו מביאים]?\u0006 ומסביר רבא את צדדי הבעיה: האם מהענף שיש בו \u0003שתים\u0004 גרוגרות בשני עוקצים \u0003מייתינן\u0004 \u0005[אנו\u0006 קוטפים ו\u0005מביאים],\u0006 וטעם הדבר: משום \u0003דחזו ליה\u0004 \u0005[ש\u0006הן ה\u0005ראויות לו]\u0006 ולא שלוש. \u0003או דלמא\u0004 \u0005[שמא]\u0006 מהענף שיש בו \u0003שלש\u0004 גרוגרות על עוקץ אחד \u0003מייתינן\u0004 \u0005[אנו מביאים],\u0006 וטעם \u0003הדבר: משום\u0004 \u0003דקא ממעטא\u0004 \u0005[ש\u0006בכך \u0005מתמעטת]\u0006 מלאכת ה\u0003קצירה\u0004 שיש בקטיפת פרי מהעץ, שהרי הוא קוטף פעם אחת בלבד?","ומשיבים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדין במקרה זה שמהענף שיש בו עוקץ אחד ובו \u0003שלש\u0004 גרוגרות \u0003מייתינן\u0004 \u0005[מביאים אנו],\u0006"],["ובכך אף ר' ישמעאל (הסבור שמביאים את העומר ביום השבת משלוש סאים, ולא מחמש סאים כביום חול, משום שאין להרבות במלאכות בשבת אף בדבר המותר), יודה שיש לקטוף את שלוש הגרוגרות, הגם שיש בדבר ריבוי מלאכה. שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' ישמעאל התם\u0004 \u0005[שם,\u0006 במשנתנו\u0005],\u0006 \u0003אלא דכי\u0004 \u0005[שכאשר]\u0006 הוא \u0003ממעט באכילה\u0004 (בדבר הנקצר, בשלוש סאים ולא בחמש) — \u0003קא\u0004 \u0005[הריהו]\u0006 \u0003ממעט\u0004 גם במעשה ה\u0003קצירה,\u0004 ונמצא שמיעט בחילול השבת. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בקטיפת הגרוגרות\u0005],\u0006 \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003קא ממעט באכילה\u0004 (בדבר הנקטף, שיקטוף שתי גרוגרות ולא שלוש) \u0003—\u0004 \u0003קא מפשא\u0004 \u0005[מרבה]\u0006 במעשה ה\u0003קצירה,\u0004 שכן נצרך לקטוף פעמיים במקום פעם אחת (אילו היה קוטף את שלוש הגרוגרות), במקרה כזה \u0003ודאי\u0004 הוא כי את ה\u0003שלש מייתינן\u0004 \u0005[מביאים אנו].\u0006","\u0003מצות העומר\u0004 לכתחילה, ראוי \u0003להביא\u0004 את השעורים הנקצרות לצורך העומר \u0003מן\u0004 המקום \u0003הקרוב\u0004 לירושלים. ואולם אם בזמן קציר העומר עדיין \u0003לא ביכר\u0004 (הבשיל) שדה שעורים \u0003ה\u0004נמצא \u0003קרוב לירושלים\u0004 — \u0003מביאין אותו\u0004 את העומר \u0003מכל מקום\u0004 בארץ ישראל. ומוסרים כי פעם אירע \u0003מעשה ש\u0004לא נמצא שדה שעורים שביכר בסמוך לירושלים, ו\u0003בא העומר מ\u0004המקום הנקרא \u0003גגות צריפין\u0004 המרוחק מירושלים. \u0003ו\u0004כן שאירע שאת התבואה הנקצרת לצורך קרבן \u0003שתי הלחם\u0004 הבא בעצרת, הביאו \u0003מבקעת עין סוכר\u0004 המרוחקת מירושלים.","שנינו במשנתנו כי לכתחילה יש להביא את העומר ממקום הסמוך לירושלים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומסבירים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהטעם \u0003משום\u0004 שנאמר \"ואם תקריב מנחת בכורים לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (ויקרא ב, יד). ומובנה של המלה \u0003כרמל\u0004 — רך ונמלל, שתהיה התבואה טריה שהיא רכה ונמללת ביד. ולכך ראוי שתיקצר במקום קרוב לירושלים, כדי שלא תתייבש ותתקשה בדרך.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003משום\u0004 ש\u0003אין מעבירין על המצו‍ת,\u0004 שכיון שיש תבואה בסמוך לירושלים — אין זה נכון, לעבור על פניה, ולבקש תבואה ממקום אחר.","במשנתנו נמסר כי פעם אירע \u0003מעשה שבא העומר מגגות צריפין\u0004 ושתי הלחם מבקעת עין סוכר, ומביאים ברייתא המפרטת מתי וכיצד היה דבר זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשצרו\u0004 האחים הורקנוס ואריסטובלוס, \u0003מלכי בית חשמונאי, זה על זה, והיה הורקנוס\u0004 מטיל מצור על ירושלים \u0003מבחוץ\u0004 לה, \u0003ואריסטובלוס\u0004 היה \u0003מבפנים,\u0004 בירושלים הנצורה. \u0003בכל יום ויום היו משלשלין להן\u0004 הנצורים מבעד לחומת ירושלים \u0003דינרין ב\u0004תוך \u0003קופה\u0004 (סל), \u0003ו\u0004היו הצרים \u0003מעלין להן\u0004 בתמורה לדינרים באותו סל כבשים \u0003להקרבתם כקרבנות\u0004 \u0003תמידין,\u0004 הקרבים תמיד בכל יום, בבוקר ובין הערבים.","\u0003היה שם\u0004 בירושלים \u0003זקן אחד שהיה מכיר בחכמת יוונית, לעז להם\u0004 לצרים, לאנשי הורקנוס, ברמז \u0003בחכמת יוונית, אמר להן:\u0004 דעו \u0003כל זמן שעסוקין\u0004 ישראל \u0003בעבודה\u0004 במקדש — \u0003אין\u0004 הם \u0003נמסרין בידכם.\u0004 קבלו הצרים את דבריו ו\u0003למחר\u0004 כאשר \u0003שלשלו להן\u0004 הנצורים \u0003דינרין בקופה,\u0004 חזרו \u0003והעלו להן\u0004 הצרים מבחוץ במקום הכבשים לקרבן, \u0003חזיר.\u0004 ומסופר, כי \u0003כיון\u0004 (בעת) \u0003שהגיע\u0004 החזיר תוך הנפת הקופה למעלה \u0003לחצי\u0004 גובה ה\u0003חומה, נעץ צפרניו\u0004 (טלפיו), \u0003בחומה, ונזדעזעה\u0004 \u0003ארץ ישראל\u0004 במרחב ששטחו \u0003ארבע מאות פרסה על ארבע מאות פרסה,\u0004 מחמת גודל הבזיון.","\u0003באותה שעה אמרו\u0004 חכמים בגזירה חמורה: \u0003ארור\u0004 מי \u0003שיגדל חזיר, וארור\u0004 מי \u0003שילמד\u0004 את \u0003בנו חכמת יוונית. ועל אותה שעה\u0004 של מצור, שלא היו תבואות בכל המקומות הסמוכים לירושלים, \u0003שנינו\u0004 במשנתנו כי אירע \u0003מעשה שבא\u0004 ה\u0003עומר מגגות צריפין, ו\u0004באו \u0003שתי הלחם מבקעת עין סוכר.\u0004","ומוסרים עוד אודות אותם פעמים שהובא העומר מגגות צריפין ושתי הלחם מבקעת בית סוכר: \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 זמן הבאת ה\u0003עומר, לא הוו ידעי\u0004 \u0005[לא היו יודעים]\u0006 החכמים שבאותו הדור \u0003מהיכא אייתי\u0004 \u0005[מהיכן,\u0006 \u0005להביא]\u0006 את ה\u0003עומר,\u0004 שכן שממו כל השדות שבסמוך לירושלים. עמדו \u0003ו\u0004\u0003אכרזו\u0004 \u0005[הכריזו]\u0006 שמחפשים הם מקום שיש בו שעורים לקצירת העומר. \u0003אתא ההוא חרשא\u0004 \u0005[בא\u0006 אדם \u0005אחד חרש,\u0006 אילם השומע ואינו מדבר\u0005]\u0006 שידע היכן יש מקום מתאים לקצירת העומר לפני חכמים. וכיון שלא יכול היה לדבר, רמז להם בתנועות היכן הוא אותו המקום. וכך עשה: \u0003אותיב חדא ידא אאיגרא\u0004 \u0005[הניח יד אחת על הגג],\u0006 \u0003וחדא ידיה אצריפא\u0004 \u0005[ויד אחת על צריף\u0006], כרומז להם על שמו של אותו המקום. \u0003אמר להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]\u0006 \u0003מרדכי\u0004 (היהודי, שבימי אחשורוש): \u0003מי איכא דוכתא דשמה\u0004 \u0005[האם יש מקום ששמו]\u0006 הוא \u0003\"גגות צריפין\" או \"צריפין גגות\"?\u0004 ומסופר כי אכן \u0003בדקו\u0004 החכמים אם יש מקום הנקרא \"גגות צריפין\", \u0003ואשכחוה\u0004 \u0005[ומצאוהו]\u0006 שהיה באותו מקום שדה שעורים, וקצרו מהן לעומר.","כיוצא בזה אירע באותה עת, \u0003כי בעי לאתוי\u0004 \u0005[כאשר היו צריכים להביא]\u0006 את \u0003שתי הלחם\u0004 בעצרת, ו\u0003לא הוו ידעי מהיכא לאתויי\u0004 \u0005[ולא היו יודעים מהיכן להביא]\u0006 מן החיטים, עמדו ו\u0003אכרזו\u0004 \u0005[הכריזו]\u0006 שמחפשים הם אחר שדה חיטים שממנה אפשר להביא לצורך שתי הלחם. \u0003אתא ההוא גברא חרשא\u0004 \u0005[בא אדם אחד חרש,\u0006 אילם השומע ואינו מדבר\u0005],\u0006 \u0003אותיב ידיה אעיניה וחדא ידא אסיכרא\u0004 \u0005[הניח ידו\u0006 האחת \u0005על עיניו ויד אחת על מקום סגירת הדלת],\u0006 \u0003אמר להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]\u0006 \u0003מרדכי: ומי איכא דוכתא דשמה\u0004 \u0005[והאם יש מקום ששמו]\u0006 \u0003\"עין סוכר\" או \"סוכר עין\"?\u0004 ומסופר כי אכן \u0003בדקו\u0004 החכמים \u0003ואשכחו\u0004 \u0005[ומצאו]\u0006 מקום הנקרא \"עין סוכר\", והיה בו שדה חיטים, וקצרו מהן לשתי הלחם.","ועוד מסופר על חכמת \u0003מרדכי, מעשה היה ב\u0004\u0003הנהו\u0004 \u0005[אותן]\u0006 \u0003שלש נשים, דאייתו\u0004 \u0005[שהביאו]\u0006 למקדש \u0003שלש קינין,\u0004 שלושה זוגות של קרבנות עוף למקדש. \u0003חדא\u0004 \u0005[אחת]\u0006 מהן \u0003אמרה:\u0004 \"קן זה הוא \u0003לזיבתי\", וחדא\u0004 \u0005[ואחת]\u0006 מהן \u0003אמרה:\u0004 \"קן זה הוא \u0003לימתי\", וחדא\u0004 \u0005[ואחת]\u0006 מהן \u0003אמרה:\u0004 \u0003\"קן זה הוא\u0004 \u0003לעונתי\".\u0004","ונמסר כי \u0003סבור\u0004 \u0005[חשבו]\u0006 חכמים ששמעו את דבריהן אלה, כי \u0003מינה\u0004 \u0005[ממנה,\u0006 מתוך\u0005]\u0006 שאמרה \u0003\"זיבתי\"\u0004 משמע שהיתה \u0003זבה ממש,\u0004 והיא מביאה קן עופות, כדין הזבה, הבאה להיטהר, שחייבת להביא זוג עופות, אחד לקרבן חטאת ואחד לקרבן עולה. וכן זו שאמרה \u0003\"לימתי\"\u0004 — כוונתה לטהרת זיבה, והתכוונה לומר \u0003לימתי\u0004 (שהיתה שופעת כים) \u0003ממש.\u0004 וזו שאמרה \u0003\"לעונתי\"\u0004 — כוונתה לטהרת זבה, שבאה \u0003לעונתה,\u0004 עונת הקרבת הקרבן ביום השמיני לטהרתה. ונמצא \u0003דכולהו\u0004 \u0005[שכולן]\u0006 נצרכות להביא קרבן זבה המיטהרת, שיהיה \u0003חדא\u0004 \u0005[אחד]\u0006 העופות לקרבן \u0003חטאת וחדא\u0004 \u0005[ואחד]\u0006 לקרבן \u0003עולה,\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003מרדכי: שמא\u0004 זו שאמרה \"לזיבתי\" — התכוונה לומר כי \u0003ב\u0004היותה במצב \u0003של\u0004 \u0003זוב, סיכנה\u0004 את חייה, וניצלה. ואין הקן הזה שהביאה קן הנטהרת, אלא קרבן נדבה, להודות על הצלתה. וכן זו שאמרה \"לימתי\" — \u0003שמא\u0004 התכוונה לומר כי בהיותה \u0003בים סיכנה\u0004 עצמה, וניצלה, ומביאה קרבן הודאה. וכן זו שאמרה \"לעונתי\" — \u0003שמא\u0004 התכוונה לומר \"לעיני\", ואפשר ש\u0003בעינה סיכנה\u0004 (הסתכנה) וניצלה, ובאה להודות על כך, בקן זה? וההבדל למעשה הוא \u0003דכולהו\u0004 \u0005[שכולן,\u0006 ששני העופות שבקן\u0005]\u0006 קרבנות \u0003עולות נינהו\u0004 \u0005[הן],\u0006 ומסופר, כי אכן \u0003בדוק ואשכח\u0004 \u0005[בדקו ומצאו]\u0006 כדבריו."],["\u0003והיינו דתנן\u0004 \u0005[וזהו ששנינו]\u0006 במשנה במסכת שקלים, ברשימת שמותיהם של הממונים בבית המקדש, ובתוכם נמנה \u0003פתחיה\u0004 שהיה ממונה \u0003על\u0004 קבלת המעות לצורך \u0003הקינין\u0004 והבאתם. והסבירו שם במשנה כי פתחיה — \u0003זה\u0004 הוא \u0003מרדכי\u0004 היהודי שבשושן הבירה, ו\u0003למה נקרא שמו \"פתחיה\"?\u0004 — לפי \u0003ש\u0004היה \u0003פותח\u0004 (מפרש) \u0003דברים\u0004 סתומים \u0003ודורשן\u0004 (ומסבירם), \u0003ו\u0004היה \u0003יודע בשבעים לשון.\u0004","ותוהים: מה החידוש שבכך, הלא \u0003כולהו\u0004 \u0005[כל]\u0006 היושבים ב\u0003סנהדרין נמי ידעי\u0004 \u0005[גם כן יודעים]\u0006 \u0003שבעים לשון!\u0004 שכן \u0003אמר ר' יוחנן: אין מושיבים\u0004 (ממנים) דיינים \u0003בסנהדרין אלא\u0004 אנשים שהם \u0003בעלי חכמה, בעלי מראה\u0004 (שמראיהם), \u0003בעלי קומה\u0004 (שקומתם נותנת להם כבוד), \u0003בעלי זקנה, בעלי כשפים\u0004 היודעים בכשפים השונים, \u0003ויודעים שבעים לשון.\u0004 והטעם שצריכים לדעת שבעים לשון — כדי \u0003שלא תהא\u0004 ה\u0003סנהדרין שומעת\u0004 את עדותם של העדים המדברים באחת משבעים הלשונות הללו \u0003מפי התורגמן,\u0004 אלא ישירות מפי העדים עצמם. משמע שכל היושבים בסנהדרין ידעו שבעים לשונות!","ומתרצים: מרדכי היה מיוחד לא במה שידע שבעים לשונות, \u0003אלא\u0004 \u0003דהוה בייל לישני ודריש\u0004 \u0005[שהיה בולל לשונות\u0006 אחדות \u0005ודורש],\u0006 שהיה מבין לא רק בשפות עצמן אלא גם בצירופי לשונות, \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 \u0003ב\u0004רשימת השבים לירושלים מגולת בבל לאחר הכרזת כורש מלך פרס \"אשר באו עם זרובבל... \u0003מרדכי בלשן\"\u0004 (עזרא ב, ב. נחמיה ז, ז). שנקרא כן על שהיה יודע להסביר אף בליל לשונות (=\"בלשן\").","ומפרטים את דרך קציר העומר: \u0003כיצד הן עושין\u0004 בקציר העומר? בתחילה \u0003שלוחי בית דין יוצאין מערב יום טוב\u0004 של פסח אל השדה בה תיקצר התבואה לעומר, \u0003ו\u0004שם היו \u0003עושין אותן\u0004 את שבלי השעורים \u0003כריכות\u0004 (אגודות) הקשורות אלו לאלו, כמלוא כפו של הקוצר, \u0003ב\u0004עת שהשבלים עדיין \u0003מחובר לקרקע, כדי שיהא נוח\u0004 יותר \u0003לקצור\u0004 אותן. ו\u0003כל\u0004 בני \u0003העיירות הסמוכות לשם\u0004 למקום הקצירה היו \u0003מתכנסות לשם,\u0004 בזמן הקציר, וטעם הדבר: \u0003כדי שיהא נקצר בעסק\u0004 (בהמולה ובעשייה) \u0003גדול.\u0004","ובמוצאי החג, \u0003כיון\u0004 (מיד) כ\u0003שהחשיכה\u0004 השמש, היו הכל נמצאים בשדה הקצירה המיועד. והיה קוצר העומר \u0003אומר\u0004 בקול \u0003להן\u0004 לכל הנמצאים: האם כבר \u0003בא\u0004 (שקעה) \u0003השמש,\u0004 ועתה הוא ליל ט\"ז בניסן? וכל הקהל הנאסף היה \u0003אומר\u0004 לו בתשובה: \u0003הין\u0004 (כן). ושוב היה הקוצר שואל: האם כבר \u0003בא השמש?\u0004 והקהל \u0003אומר\u0004 לו: \u0003הין,\u0004 וכן בפעם שלישית, כך היה שואל וכך הם משיבים לו. ועוד היה הקוצר שואל את הקהל: האם אקצור ב\u0003מגל זו?\u0004 והקהל היה \u0003אומר\u0004 לו: \u0003הין.\u0004 והקוצר חוזר ושואל: האם אקצור ב\u0003מגל זו?\u0004 ושוב הקהל \u0003אומר\u0004 לו: \u0003הין,\u0004 וכן בפעם שלישית, הוא שואל והם משיבים לו. ועוד היה שואל הקוצר: האם אכניס את התבואה הנקצרת בתוך \u0003קופה זו?\u0004 והקהל \u0003אומר\u0004 לו בתשובה: \u0003הין.\u0004 ושב ושואל: האם אכניס את התבואה הנקצרת בתוך \u0003קופה זו?\u0004 והקהל \u0003אומר\u0004 לו בתשובה: \u0003הין,\u0004 ושוב היה שואל כך בפעם השלישית, והקהל משיב לו: הין.","ואם ט\"ז בניסן חל \u0003ב\u0004יום ה\u0003שבת,\u0004 היה הקוצר מוסיף בשאלותיו ו\u0003אמר להן:\u0004 האם אקצור ב\u0003שבת זו\u0004 (שכן קציר העומר דוחה את השבת)? והקהל \u0003אמר\u0004 בתשובה: \u0003הין,\u0004 ושוב היה שואל: האם לקצור ב\u0003שבת זו?\u0004 והקהל \u0003אמר\u0004 לו: \u0003הין,\u0004 וכך בפעם שלישית. ולבסוף, היה ה\u0003קוצר פונה אל הנאספים ושואל: האם\u0004 \u0003אקצור\u0004 עתה? \u0003והם אומרים לו: קצור.\u0004 ושוב היה שואל: האם \u0003אקצור\u0004 עתה? \u0003והם אומרים לו: קצור.\u0004 וכן פעם שלישית.","שכך היה הסדר, שכל אחד מהקוצרים היה שואל \u0003שלש פעמים על כל דבר ודבר, והן\u0004 הנאספים \u0003היו\u0004 \u0003אומרים לו\u0004 בתשובה שלוש פעמים: \u0003הין, הין, הין.\u0004 ומסבירים: \u0003כל כך למה לי,\u0004 מדוע התקינו חכמים שיהיו עושים כך, בפרסום כה רב? \u0003מפני הבייתוסים\u0004 (בני כת שכפרו בתורה שבעל פה), \u0003שהיו\u0004 הבייתוסים \u0003אומרים\u0004 ש\u0003אין קצירת העומר\u0004 נעשית \u0003במוצאי יום טוב\u0004 של פסח, אלא במוצאי יום השבת שלאחר יום טוב ראשון של פסח. ולהוציא מדעתם של הבייתוסים, התקינו לקצור בפרסום רב, לפרסם שהוא זמן הקציר הנכון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במגילת תענית: \u0003אלין יומיא\u0004 \u0005[אלה\u0006 הם \u0005הימים]\u0006 שנחשבים ימי שמחה לישראל בשל אירועים טובים שאירעו לישראל באותם ימים במהלך הדורות, \u0003דלא להתענאה בהון\u0004 \u0005[שאין להתענות בהם],\u0006 \u0003ומקצתהון\u0004 \u0005[ומקצתם]\u0006 אף שמחים יותר \u0003דלא למספד בהון\u0004 \u0005[שאין להספיד בהם]\u0006 את הנפטרים. ומונים: \u0003מריש ירחא\u0004 \u0005[מראש חודש]\u0006 \u0003ניסן ועד תמניא ביה\u0004 \u0005[שמונה בו]\u0006 — שב ו\u0003איתוקם תמידא\u0004 \u0005[הועמד\u0006 על מכונו, קרבן \u0003ה\u0004\u0005תמיד]\u0006 במקדש, ומשום כך נקבע \u0003דלא למספד\u0004 \u0005[שאין להספיד]\u0006 בימים אלה. \u0003ומתמניא ביה\u0004 \u0005[ומשמונה בו,\u0006 בניסן\u0005]\u0006 \u0003ועד סוף מועדא\u0004 \u0005[המועד,\u0006 חג הפסח\u0005]\u0006 — \u0003איתותב חגא דשבועיא\u0004 \u0005[הושב\u0006 לזמנו הראוי \u0005חג השבועות],\u0006 ולכך נקבע \u0003דלא למספד\u0004 \u0005[שאין להספיד]\u0006 בימים אלה.","ומסבירים: \u0003מריש ירחא\u0004 \u0005[מראש חודש]\u0006 \u0003ניסן ועד תמניא ביה\u0004 \u0005[שמונה בו]\u0006 \u0003איתוקם תמידא\u0004 \u0005[הועמד התמיד]\u0006 ולכך נקבע \u0003דלא למספד\u0004 \u0005[שאין להספיד]\u0006 בימים אלה — \u0003ש\u0004כן \u0003היו\u0004 ה\u0003צדוקים\u0004 (בני כת שכפרה במסורת חכמים) \u0003אומרים\u0004 שאדם \u0003יחיד\u0004 מישראל \u0003מתנדב ומביא\u0004 את קרבן ה\u0003תמיד,\u0004 ושלא כהלכה המסורה שהתמיד קרב רק משל ציבור. ומסבירים: \u0003מאי דרוש\u0004 \u0005[מה דרשו\u0006 הצדוקים\u0005]\u0006 כדי להוכיח את דבריהם? — שנאמר בקרבן התמיד \u0003\"את הכבש האחד תעשה בבקר ואת הכבש השני תעשה בין הערבים\"\u0004 (במדבר כח, ד) — בלשון יחיד אמורים הדברים, ומכאן שבא התמיד משל יחיד.","ומסבירים עוד, \u0003מאי אהדרו\u0004 \u0005[מה החזירו,\u0006 השיבו להם\u0005]\u0006 חכמים לצדוקים על טענתם זו? — שנאמר לפני פסוק זה, בתחילת פרשת קרבן התמיד: \"צו את בני ישראל ואמרת אליהם \u0003את קרבני לחמי לאשי\u0004 ריח ניחוחי \u0003תשמרו\u0004 להקריב לי במועדו. ואמרת אליהם זה האשה אשר תקריבו לה' כבשים בני שנה תמימים שנים ליום עולה תמיד\" (שם ב— ג) — שנאמרו הדברים לרבים, ללמד \u0003שיהיו כולן באין מ\u0004השקלים הניתנים על ידי הבאים למקדש כ\u0003תרומת הלשכה\u0004 במקדש. וגברה ידם של חכמים על הצדוקים בימים אלה שבין ראש חודש ניסן ועד לח' בניסן, והועמד התמיד כהלכתו, שלא יהיה קרב אלא משל ציבור, ולכך קבעו אותם ימים כימי שמחה.","ומסבירים עוד: \u0003מתמניא ביה\u0004 \u0005[משמונה בו,\u0006 בניסן\u0005]\u0006 \u0003ועד סוף מועדא\u0004 \u0005[המועד]\u0006 \u0003איתותב חגא דשבועיא\u0004 \u0005[הושב חג השבועות\u0006 לזמנו הראוי\u0003],\u0004 ולכך נקבע \u0003דלא למספד\u0004 \u0005[שאין להספיד]\u0006 בימים אלה — \u0003ש\u0004כן \u0003היו\u0004 ה\u0003בייתוסין אומרים: עצרת\u0004 (חג השבועות) הריהו חל תמיד \u0003אחר\u0004 יום \u0003השבת,\u0004 כלומר, ביום ראשון בשבוע.","ומסופר כי \u0003ניטפל להם\u0004 (פגש אותם) \u0003רבן יוחנן בן זכאי, ואמר להם: שוטים, מנין לכם\u0004 ראיה לדבר זה? \u0003ולא היה\u0004 בתוכם אף לא \u0003אדם אחד שהיה משיבו\u0004 על שאלתו זו, \u0003חוץ מזקן אחד\u0004 שהיה שם בין הבייתוסים, \u0003שהיה מפטפט כנגדו, ואמר\u0004 לו כך: \u0003משה רבינו אוהב ישראל היה, ויודע\u0004 היה \u0003שעצרת\u0004 שלא כשאר הרגלים אינה אלא \u0003יום אחד הוא.\u0004 ולכך \u0003עמד ותקנה\u0004 את העצרת שתחול תמיד ביום של \u0003אחר שבת, כדי שיהו ישראל מתענגין שני ימים,\u0004 ביום השבת ולמחרתו ביום ראשון שהוא חג השבועות. \u0003קרא\u0004 רבן יוחנן בן זכאי \u0003עליו\u0004 (כנגד אותו זקן) \u0003מקרא זה,\u0004 שאמר משה רבינו בתחילת ספר דברים: \u0003\"אחד עשר יום מחורב דרך הר שעיר\u0004 עד קדש ברנע\" (דברים א, ב),"],["\u0003ו\u0004כך אמר לו: \u0003אם\u0004 כדבריך ש\u0003משה רבינו אוהב ישראל היה,\u0004 ובשל כך דאג לרווחתם, \u0003למה איחרן\u0004 (עיכב אותם) \u0003במדבר ארבעים שנה,\u0004 למרות שיכלו להגיע אל הארץ בימים ספורים? \u0003אמר לו\u0004 אותו זקן בייתוסי לרבן יוחנן בן זכאי: \u0003רבי, בכך,\u0004 בדחיה זו בלבד, \u0003אתה פוטרני\u0004 מתשובה על ראייתי? \u0003אמר לו: שוטה\u0004 שכמותך, \u0003ולא תהא תורה שלמה שלנו,\u0004 כלומר, הכתוב שממנו ראיה לכך שאין עצרת חייבת לחול דווקא ביום ראשון בשבוע, \u0003כשיחה בטילה\u0004 (כדברים סתמיים של בני אדם), שאפשר לדחותם בטענות הבל אלה \u0003שלכם!\u0004 ומסבירים מהי הראיה מן הכתוב שאין עצרת חייבת לחול דווקא ביום ראשון בשבוע: נאמר בדין ספירת העומר \"וספרתם לכם ממחרת השבת מיום הביאכם את עומר התנופה שבע שבתות תמימות תהיינה. עד ממחרת השבת השביעית תספרו חמשים יום...","\" (ויקרא כג, טו— טז), ולכאורה יש כעין סתירה בין שני הפסוקים הללו, שהרי \u0003כתוב אחד\u0004 (הפסוק הראשון) \u0003אומר: \"תספרו חמשים יום\"\u0004 — הרי שאין הספירה אלא של ימים בלבד, שהסכום הכולל של הימים צריך להיות חמישים, ומובנה איפוא שהספירה יכולה להתחיל בכל יום בשבוע. \u0003ו\u0004אולם \u0003כתוב אחד\u0004 (הפסוק השני) \u0003אומר: \"שבע שבתות תמימת תהיינה\"\u0004 — שאין הספירה אלא של שבועות בלבד, וצריכים אלה להיות שבעה שבועות מלאים, ומכאן יש ללמוד שהספירה מתחילה ביום ראשון בשבוע.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את הסתירה שבין שני המקראות האלה? \u0003כאן,\u0004 שאמר הכתוב שספירת העומר היא לשבועות — מדבר הכתוב \u0003ביום טוב\u0004 (חג הפסח) \u0003שחל להיות ב\u0004יום ה\u0003שבת,\u0004 ומתחילים לספור ביום ראשון, ותימצא הספירה שבעה שבועות מלאים. ויחול חג השבועות ביום ראשון בשבוע. ואילו \u0003כאן\u0004 שאמר הכתוב שספירת העומר היא לימים — מדבר הכתוב \u0003ביום טוב\u0004 (פסח) \u0003שחל להיות באמצע שבת\u0004 (שבוע), ומתחילים לספור למחרת אותו יום, באמצע השבוע, ויחול חג השבועות אף הוא באמצע השבוע.","לאחר שהובאה ראיה לכך שספירת העומר מתחילה למחרת יום ראשון של חג הפסח, ולא למחרת יום השבת. ומכאן שאף חג השבועות אינו חל בדווקא ביום ראשון בשבוע, מביאים סדרת ראיות נוספת להלכה זו, שהביאו תנאים שונים. וכדי לזכור כל תנא ותנא וראייתו, נתנו חכמים סימן לדבר: בראייתו \u0003של ר' אליעזר\u0004 יוזכר עניינו של ה\u0003סופר\u0004 את ספירת העומר. ובראייתו של \u0003ר' יהושע\u0004 יוזכר עניינו של ה\u0003מונה\u0004 את הימים לעצרת. ובראייתו של \u0003ר' ישמעאל\u0004 יובא עניינו של ה\u0003מעמר\u0004 (המביא את העומר), ובראייתו של \u0003ר' יהודה\u0004 תוזכר המלה \u0003\"למטה\".\u0004 והרי זה \u0003סימן\u0004 לזכרון נכון של שמועות הבאות ולעיקרון שבהם.","ומפרטים, \u0003ר' אליעזר אומר: אינו צריך\u0004 לראיה המובאת למעלה, שכן \u0003הרי הוא,\u0004 הכתוב, \u0003אומר\u0004 במצות ספירת העומר \"שבעה שבועות \u0003תספר לך\u0004 מהחל חרמש בקמה תחל לספור שבעה שבועות\" (דברים טז, ט). ומן האמור \"תספור לך\" למדים אנו כי \u0003ספירה תלויה בבית דין.\u0004 וטעם הדבר: \u0003ש\u0004כן \u0003הם\u0004 ה\u0003יודעים לחדש\u0004 חודשים, ועל פיהם בלבד נקבע מתי מתחיל החודש, ולפיכך רק על פיהם נקבע באיזה יום בשבוע יחול חג הפסח, ואיזה יום בשבוע הוא איפוא היום שלמחרתו. ולכך מובנו של הכתוב הנאמר בספירת העומר \u0003\"ממחרת השבת\"\u0004 — אינו אלא מ\u0003מחרת יום טוב.\u0004 ולמדנו כי \u0003יצאת\u0004 (יצאה) מכלל משמעות הפסוק \"ממחרת השבת\" \u0003שבת בראשית\u0004 (יום שבת עצמו) — \u0003ש\u0004כן \u0003ספירתה\u0004 היא דבר התלוי \u0003בכל אדם\u0004 ולא בבית דין, שהרי הכל יודעים מתי הוא יום ראשון שלאחר השבת.","\u0003ר' יהושע אומר\u0004 ראיה שונה בדרך היקש, \u0003אמרה תורה\u0004 במצות קידוש החודש: \u0003מנה\u0004 עשרים ותשעה \u0003ימים\u0004 בחודש מזמן מולד הלבנה, \u0003ו\u0004לאחר מכן, ביום השלושים למנין הימים \u0003קדש\u0004 את ראש ה\u0003חדש\u0004 הבא. וכמו כן אמרה תורה במצות ספירת העומר וחג השבועות: \u0003מנה\u0004 ארבעים ותשעה \u0003ימים, ו\u0004לאחר מכן ביום שלאחריהם \u0003קדש\u0004 את ה\u0003עצרת.\u0004 ומעתה נסיק מן ההשוואה: \u0003מה\u0004 יומו של ראש \u0003חדש סמוך לביאתו ניכר\u0004 (ברור) שהוא עומד להתקדש, שכן לאחר שחלפו עשרים ותשעה ימים מזמן מולד הלבנה של החודש הקודם, ברור שעומד להתקדש ראש החודש, \u0003אף\u0004 קידוש ה\u0003עצרת סמוך לביאתו ניכרת.\u0004 ולכן, אם סופרים את ארבעים ותשעה הימים מהיום שלמחרת יום טוב ראשון של פסח, ברור ממתי מתחילה הספירה — בט\"ז בניסן, וברור הוא אימתי תחול העצרת.","\u0003ו\u0004אולם \u0003אם תאמר\u0004 כי \u0003עצרת לעולם\u0004 היא \u0003אחר השבת,\u0004 וספירת העומר מתחילה תמיד לאחר השבת, \u0003היאך תהא ניכרת\u0004 הספירה \u0003משלפניה,\u0004 שהרי אין היא חלה בתאריך קבוע.","\u0003ר' ישמעאל אומר\u0004 ראיה אחרת, ואף היא בדרך היקש, \u0003אמרה תורה\u0004 במצות העומר: \u0003הבא עומר ב\u0004חג ה\u0003פסח, ו\u0004כן אמרה שיש להביא \u0003שתי הלחם בעצרת.\u0004 ומעתה נלמד מן ההשוואה: \u0003מה\u0004 במצוה הנידונה \u0003להלן\u0004 (הלאה), בשתי הלחם — זמן המצוה הוא ב\u0003רגל, ו\u0004ב\u0003תחלת רגל\u0004 (שהרי אין חג השבועות אלא יום אחד בלבד). \u0003אף כאן\u0004 במצות הבאת העומר) — זמנה הוא ב\u0003רגל, ו\u0004ב\u0003תחלת\u0004 ה\u0003רגל.\u0004 והרי זה שלא כבייתוסים הסבורים שזמנה הוא לאחר יום השבת, שלשיטתם עשוי העומר לבוא בסוף הרגל (אם חל יום ראשון של הפסח בתחילת השבוע), ואף שלא ברגל כלל (כגון שחל יום ראשון של פסח ביום ראשון).","ואילו \u0003ר' יהודה בן בתירא אומר\u0004 ראיה אחרת, שאף היא מבוססת על היקש ספירת העומר וחג השבועות, \u0003נאמר\u0004 הלשון \"ממחרת ה\u0003שבת\" למעלה\u0004 (\"וספרתם לכם ממחרת השבת\". ויקרא כג, טו) \u0003ו\u0004כמו כן \u0003נאמר\u0004 הלשון \"ממחרת ה\u0003שבת\" למטה\u0004 (בדין חג השבועות \"עד ממחרת השבת השביעית תספרו חמשים יום והקרבתם מנחה חדשה לה' \". שם פסוק טז). ומעתה נסיק מן ההשוואה: \u0003מה\u0004 \"ממחרת השבת\" האמורה \u0003להלן\u0004 בפסוק ט\"ז — הכוונה היא ל\u0003רגל,\u0004 העצרת, \u0003ותחלת\u0004 ה\u0003רגל סמוך לה\u0004 ל\"שבת\" (שהרי הוא בא למחרתה). \u0003אף כאן\u0004 בספירת העומר — הכוונה ב\"שבת\" ל\u0003רגל, ותחלת רגל\u0004 (יום שני של פסח) הריהו \u0003סמוך לה.\u0004","ומביאים ראיות נוספות מדברי תנאים שזמן תחילת ספירת העומר הריהו למחרת יום ראשון של חג הפסח, ולא למחרת יום השבת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר במצוות ספירת העומר \u0003\"וספרתם לכם\"\u0004 בא ללמדנו שאין זו מצוה המוטלת על הציבור ככלל, אלא על היחיד, \u0003שתהא\u0004 מצות ה\u0003ספירה ל\u0004חובת \u0003כל אחד ואחד\u0004 מישראל.","ועוד מה שנאמר בכתוב \u0003\"ממחרת השבת\"\u0004 — הכוונה \u0003ממחרת יום טוב\u0004 ראשון של פסח. ואם ישאל אדם: \u0003או אינו אלא\u0004 כוונת הפסוק \u0003למחרת שבת בראשית? ר' יוסי בר יהודה אומר:\u0004 אין לומר כן, ש\u0003הרי הוא,\u0004 הכתוב, \u0003אומר \"תספרו חמשים יום\",\u0004 והכוונה היא ש\u0003כל ספירות שאתה סופר לא יהו\u0004 בכללם \u0003אלא\u0004 אותם \u0003חמשים יום,\u0004 הנפתחים בזמן קבוע בכל שנה ומסתיימים בזמן קבוע. כפי שהוא תמיד כשמתחילים לספור בט\"ז בניסן.","\u0003ו\u0004אולם \u0003אם תאמר\u0004 שהספירה מתחילה \u0003ממחרת שבת בראשית\u0004 — נמצא ש\u0003פעמים שאתה מוצא\u0004 בכלל הימים שעברו מט\"ז בניסן \u0003חמשים ואחד\u0004 ימים (כגון שחל ט\"ז בניסן ביום ששי בשבוע). ואם בשנה שעברה חל ט\"ז בניסן ביום ראשון בשבוע — נמצא שחמישים הימים של הספירה שבשנה זו מסתיימים בתאריך שבו בשנה שעברה מלאו חמישים ואחד ימים. \u0003ו\u0004כיוצא בדבר \u0003פעמים שאתה מוצא\u0004 שיש בה בספירה זו \u0003חמשים ושנים\u0004 ימים, \u0003חמשים ושלשה\u0004 ימים, \u0003חמשים וארבעה\u0004 ימים, \u0003חמשים וחמשה\u0004 ימים, ואף \u0003חמשים וששה\u0004 ימים מט\"ז בניסן. אלא ודאי הספירה היא תמיד של חמישים יום מאותו יום שחל בו.","ואילו \u0003ר' יהודה בן בתירא אומר: אינו צריך\u0004 להוכחה זו,"],["שכן יש להביא ראיה כי ספירת העומר מתחילה למחרת יום טוב \u0003ראשון של פסח, מן הנאמר בתורה במצות ספירת העומר. ש\u0004\u0003הרי הוא,\u0004 הכתוב, \u0003אומר\u0004 \"שבעה שבועות \u0003תספר לך\"\u0004 (דברים טז, ט) — להשמיענו כי \u0003ה\u0004\u0003ספירה תלויה בבית דין,\u0004 שהם הקובעים אימתי תתחיל. שכן בית דין הם הקובעים מתי יחול ראש חודש ניסן, ועל ידי כך נקבע גם מתי יחול יום טוב ראשון של פסח, שלמחרתו יש להתחיל לספור. \u0003יצתה\u0004 (יצאה) מכלל זה \u0003שבת בראשית,\u0004 \u0003ש\u0004אין ספירה זו תלויה בבית דין, שהרי יום השבת קבוע ועומד, ונמצא \u0003שספירתה\u0004 תלויה \u0003בכל אדם\u0004 ולא בבית דין.","\u0003ר' יוסי אומר\u0004 הוכחה אחרת: נאמר במצות ספירת העומר \"וספרתם לכם \u0003ממחרת השבת\"\u0004 (ויקרא כג, טו) וכוונת הביטוי \"ממחרת השבת\" הוא: \u0003ממחרת יום טוב. אתה אומר\u0004 שהכוונה היא \u0003ממחרת יום טוב, או אינו אלא\u0004 הכוונה היא: \u0003ממחרת שבת בראשית,\u0004 וכטענת הבייתוסים? \u0003אמרת\u0004 (אמור) בדחיית טענה זו: \u0003וכי נאמר\u0004 בכתוב \u0003\"ממחרת השבת שבתוך הפסח\"? והלא לא נאמר\u0004 בכתוב \u0003אלא\u0004 סתם \u0003\"ממחרת השבת\",\u0004 ומנין אני יודע באיזה יום שבת המדובר, שכן \u0003כל השנה כולה\u0004 הריהי \u0003מלאה\u0004 בימי \u0003שבתות,\u0004 אם כן, \u0003צא ובדוק איזו שבת\u0004 היא זו, ולא תדע שהרי סתם הכתוב ולא פירש. והרי זו איפוא ראיה שלא כשיטת הבייתוסים.","\u0003ועוד\u0004 הביא ר' יוסי ראיה שכוונת \"ממחרת השבת\" היא ממחרת יום טוב ולא ממחרת שבת בראשית, מן ההיקש: \u0003נאמרה\u0004 הלשון \"ממחרת ה\u0003שבת\" למטה\u0004 (מקודם, בפסוק טו), \u0003ו\u0004כמו כן \u0003נאמרה\u0004 הלשון \"ממחרת ה\u0003שבת\" למעלה\u0004 (אחר כך, בפסוק טז, בדין חג השבועות \"עד ממחרת השבת השביעית תספרו חמשים יום והקרבתם מנחה חדשה לה' \"). ומעתה נסיק מן ההשוואה: \u0003מה\u0004 \"ממחרת השבת\" האמורה \u0003להלן\u0004 — הכוונה היא ל\u0003רגל,\u0004 חג השבועות, \u0003ותחילת\u0004 ה\u0003רגל\u0004 סמוך לה, ל\"שבת\" \u0003(שהרי הוא בא למחרתה).\u0004 \u0003אף כאן\u0004 בספירת העומר — הכוונה ב\"שבת\" ל\u0003רגל, ותחילת רגל\u0004 (יום שני של פסח) הריהו סמוך לה. ואילו לשיטת הבייתוסים, שספירת העומר מתחילה ביום ראשון בשבוע שלאחר יום טוב ראשון של פסח, פעמים ש\"ממחרת השבת\" הוא לאחר הרגל, וכגון שחל יום טוב ראשון של פסח ביום ראשון, ושביעי של פסח חל איפוא ביום שבת.","\u0003ר' שמעון בן אלעזר אומר\u0004 הוכחה אחרת כי ספירת העומר מתחילה למחרת יום טוב ראשון של פסח, ולא למחרת יום השבת (כטענת הבייתוסים), ומתוך שני מקראות בענין חג הפסח הנראים כסותרים זה את זה, שהרי \u0003כתוב אחד אומר: \"ששת ימים תאכל מצות\"\u0004 (דברים שם ח), \u0003ו\u0004אילו \u0003כתוב אחד אומר: \"שבעת ימים מצות תאכלו\"\u0004 (שמות יב, טו), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יש ליישב סתירה זו שבין הפסוקים? הכתוב המזכיר אכילת מצה שבעה ימים בפסח עוסק במצה שנעשתה מקמח תבואה ישנה, ואילו הפסוק המזכיר אכילת מצה ששה ימים עוסק ב\u0003מצה שאי\u0004 (שאין) \u0003אתה יכול לאוכלה\u0004 כל \u0003שבעה\u0004 ימים של פסח, משום שהיא נעשתה \u0003מן\u0004 התבואה שנקצרה עתה, שהריהי אסורה באיסור \u0003\"חדש\"\u0004 (המותר באכילה על ידי הנפת העומר). שמצה הנעשית מתבואה זו \u0003אתה יכול לאוכלה\u0004 רק \u0003ששה\u0004 ימים מהקרבת העומר \u0003מן החדש,\u0004 למחרת יום טוב ראשון של פסח. והרי זו איפוא ראיה שהבאת העומר נעשית למחרת יום טוב ראשון של פסח ולא למחרת יום השבת שלאחריו. ועוד מפרש ר' שמעון בן אלעזר שני מקראות שבספירת העומר.","ממה שנאמר בכתוב \"וספרתם לכם ממחרת השבת \u0003מיום הביאכם\u0004 את עומר התנופה שבע שבתות תמימות תהיינה. עד ממחרת השבת השביעית \u0003תספרו\u0004 חמשים יום...\" (ויקרא שם טו—טז), \u0003יכול\u0004 הייתי לומר כי מעת שהגיע המועד \"ממחרת השבת\", שהוא \"יום הביאכם\", ניתן להתחיל לספור את ספירת העומר, ואולם אין זו חובה להתחיל את הספירה דווקא ביום זה. ומעתה \u0003יקצור ויביא\u0004 את העומר בזמנו, \u0003ו\u0004אילו ביחס למצות הספירה, \u0003אימתי שירצה\u0004 יתחיל ו\u0003יספור?\u0004","לכך \u0003תלמוד לומר\u0004 בכתוב אחר במצות ספירת העומר \"שבעה שבועות תספור לך \u0003מהחל חרמש בקמה תחל לספר\u0004 שבעה שבועות\" (דברים יז, ט) — לומר שתחילת הספירה משעת קצירת העומר דווקא. ומצד אחר, \u0003אי\u0004 \u0005[אם]\u0006 מן הכתוב \u0003\"מהחל חרמש\u0004 בקמה \u0003תחל לספר\"\u0004 — \u0003יכול\u0004 היית לומר כי הספירה תלויה בזמן קציר העומר ולא בזמן הבאתו, ואין זמן הבאת העומר תלוי בזמן קצירתו. ומעתה, \u0003יקצור ויספור\u0004 למחרת יום טוב ראשון של פסח, \u0003ו\u0004אולם ביחס להבאת העומר, \u0003אימתי שירצה יביא?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"וספרתם לכם ממחרת השבת \u0003מיום הביאכם\u0004 את עומר התנופה\", ללמדנו שהספירה מתחילה אף מיום ההבאה, וזמן הקצירה וזמן ההבאה הינם אותו יום.","ומצד אחר, \u0003אי\u0004 \u0005[אם]\u0006 מן הכתוב \u0003\"מיום הביאכם\"\u0004 — \u0003יכול\u0004 היית לומר כי אכן שלוש הפעולות הללו, קצירה, הבאה, וספירה נעשות ביום אחד, ואולם \u0003יקצור ויספור ויביא ביום\u0004 ט\"ז בניסן, ולא בלילו? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"שבע שבתות תמימת תהיינה\"\u0004 — שתהא הספירה שבעה שבועות מלאים ושלמים (\"תמימות\"). ו\u0003אימתי אתה מוצא\u0004 בספירה שמתקיים בה \u0003\"שבע שבתות תמימת\"?\u0004 — \u0003בזמן שאתה מתחיל לימנות מבערב,\u0004 ולא ביום.","ומן הצד האחר, \u0003יכול\u0004 היית לומר כי \u0003יקצור ויביא ויספור בלילה,\u0004 שיעשה את שלוש הפעולות הללו כאחד? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"מיום הביאכם\", הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יעשה? ה\u0003קצירה ו\u0004ה\u0003ספירה\u0004 מצוותן \u0003בלילה, והבאה\u0004 מצוותה \u0003ביום.\u0004","לאחר שהובאו שתי ברייתות, ובהן עשר ראיות מדברי התנאים המוכיחות שלא כדעתם של הבייתוסים בענין \"ממחרת השבת\", \u0003אמר רבא\u0004 על הראיות הללו: ל\u0003כולהו אית להו פירכא\u0004 \u0005[כולן יש להן פירכה,\u0006 שבירה\u0005],\u0006 \u0003בר מתרתי תנאי בתראי\u0004 \u0005[חוץ מ\u0006הראיות של \u0005שני התנאים האחרונים],\u0006 \u0003בין במתניתא קמייתא\u0004 \u0005[בברייתא הראשונה],\u0006 \u0003בין במתניתא בתרייתא\u0004 \u0005[בברייתא האחרונה]\u0006 \u0003דלית להו פירכא\u0004 \u0005[שאין להן פירכה].\u0006","ומפרט מהי הפירכה שבכל אחת מהראיות הללו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ראייתו של \u0003רבן יוחנן בן זכאי\u0004 שעיקרה סתירת המקראות \"תספרו חמשים יום... שבע שבתות תמימות תהיינה\" — יש לפרוך: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש ליישב את הסתירה באופן שונה, ו\u0003כ\u0004שיטתו של \u0003אביי,\u0004 שכן \u0003אמר אביי: מצוה למימני יומי\u0004 \u0005[למנות ימים]\u0006 בספירת העומר, \u0003ומצוה למימני שבועי\u0004 \u0005[למנות שבועות],\u0006 שהכתוב \"תספרו חמשים יום\" עניינו ספירת הימים, והכתוב \"שבע שבתות\" עניינו ספירת שבועות.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ראייתם של \u0003ר' אליעזר\u0004 הדורש ממשמעות הכתוב שהספירה תלויה בבית דין, ולא בכל אדם, \u0003ו\u0004כן ראייתו של \u0003ר' יהושע\u0004 הלומד מהיקש עניינים לקידוש החודש שתהא הספירה ניכרת, ביום קבוע — יש לפרוך: \u0003ממאי\u0004 \u0005[מנין]\u0006 לך ש\u0003ביום טוב ראשון\u0004 של פסח \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 הכתוב? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ביום טוב אחרון\u0004 של פסח \u0003קאי\u0004 \u0005[הוא עומד]\u0006 ומשם צריך להתחיל!","ואולם ראיותיהם של \u0003ר' ישמעאל\u0004 הלומד מהיקש בין הבאת העומר והבאת שתי הלחם \u0003ו\u0004של \u0003ר' יהודה בן בתירא\u0004 הלומד מהיקש \"שבת\" \"שבת\" בעומר ובעצרת — \u0003לית להו פירכא\u0004 \u0005[אין להן\u0006 כל \u0005פירכה].\u0006","ובברייתא האחרת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ראייתו של \u0003ר' יוסי בר' יהודה\u0004 שלמד כן ממשמעות הכתובים \"תספרו חמשים יום\", שיהיו אלה חמישים ימים מזמן קבוע — יש לפרוך: \u0003הוה אמינא\u0004 \u0005[הייתי אומר,\u0006 יש עדיין מקום לומר\u0005]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 משמעות הכתוב היא, שיש לספור \u0003חמשין\u0004 \u0005[חמישים]\u0006 ימים \u0003לבר מהני\u0004 \u0005[חוץ מאלה]\u0006 הימים שבין ט\"ו בניסן ועד לתחילת הספירה למחרת יום השבת (כשיטתם של הבייתוסים), שהם (כנזכר למעלה) עשויים להיות \u0003שיתא\u0004 \u0005[ששה]\u0006 ימים (אם חל יום טוב ראשון של פסח ביום שני בשבוע, והספירה תתחיל רק ביום ראשון שלאחריו) או פחות מששה ימים (ובהתאם ליום בשבוע בו חל ראשון של פסח, וכדרך שהתבאר למעלה).","\u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004ראייתו של \u0003ר' יהודה בן בתירא\u0004 — יש לפרוך: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה יודע ש\u0003ביום טוב ראשון\u0004 של פסח הכתוב \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ביום טוב אחרון\u0004 של פסח הכתוב \u0003קאי\u0004 \u0005[עומד]\u0006 ומשם צריך להתחיל!","ראייתו הראשונה של \u0003ר' יוסי נמי\u0004 \u0005[גם\u0006 \u0003כן]\u0004 יש בה פירכה, שהרי ר' יוסי עצמו \u0003חזי ליה פירכא\u0004 \u0005[ראה בה פירכה],\u0006 \u0003והיינו דקאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003\"ועוד\",\u0004 והביא ראיה נוספת. אכן, שתי הראיות האחרונות שבברייתא השניה, של ר' יוסי ושל ר' שמעון בן אלעזר, אין בהן כל פירכה.","למעלה, הוזכרה בתוך דברי רבא שיטתו של אביי במצות ספירת העומר, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה].\u0006 שכך \u0003אמר אביי: מצוה למימני יומי\u0004 \u0005[למנות ימים]\u0006 \u0003ומצוה למימני שבועי\u0004 \u0005[למנות שבועות].\u0006 ונמסר כי אכן \u0003רבנן דבי\u0004 \u0005[החכמים בבית\u0006 המדרש\u0005]\u0006 של \u0003רב אשי מנו\u0004 בספירת העומר \u0003יומי\u0004 \u0005[ימים]\u0006 \u0003\"ומנו\u0004 גם \u0003שבועי\u0004 \u0005[שבועות],\u0006 וכשיטת אביי. ואילו \u0003אמימר מני יומי\u0004 \u0005[היה מונה ימים]\u0006 בלבד, \u0003ולא מני שבועי\u0004 \u0005[ולא היה מונה שבועות],\u0006 ובטעם הנהגתו זו \u0003אמר\u0004 אמימר: בימינו, שאין בית המקדש קיים ואין מביאים את העומר, ספירת העומר רק \u0003זכר למקדש הוא,\u0004 ולכך די בספירה לא מושלמת, של ימים בלבד, ולא של שבועות.","וממשיכים בתיאור סדר הבאת העומר: לאחר ש\u0003קצרוהו\u0004 את שלוש הסאים של שעורים הנועדים להבאת העומר \u0003ונתנוהו בקופות\u0004 במקום בו נקצר, \u0003הביאוהו לעזרה\u0004 שבמקדש. \u0003ו\u0004שם \u0003היו מהבהבין\u0004 (חורכים) \u0003אותו,\u0004 את גרעיני שעורי העומר בעודם בשיבולים, \u0003באור\u0004 (באש), \u0003כדי לקיים בו מצות קלי\u0004 כנאמר במנחת העומר: \"ואם תקריב מנחת בכורים לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (ויקרא ב, יד), אלו \u0003דברי ר' מאיר. ו\u0004אילו \u0003חכמים אומרים:\u0004 לא כך היו עושים, אלא בתחילה היו מוציאים את גרגרי השעורה מהשיבולים \u0003בקנים\u0004 רכים ולחים \u0003ובקולחות\u0004 (קלחי כרוב) שבהם היו \u0003חובטין אותו.\u0004 ומדוע היו חובטים אותם דווקא באלה? \u0003כדי שלא יתמעך\u0004 גרעין השעורה (שעדיין לח הוא) בחבטה במקל כפי שעושים כרגיל בתבואה יבשה.","ולאחר מכן \u0003נתנוהו ל\u0004תוך \u0003אבוב\u0004 (כלי חלול), \u0003ואבוב\u0004 זה \u0003היה מנוקב\u0004 (היו בו חורים), \u0003כדי שיהא האור שולט בכולו\u0004 (מגיע לכל הנמצא בתוכו), ולאחר שקלו את העומר \u0003שטחוהו בעזרה, והרוח\u0004 היתה \u0003מנשבת בו\u0004 ומקררת את גרגרי השעורה מחום הקלייה, ומייבשת את הלחות שעליהם שנוצרה מתוך הקלייה. ואחר כך \u0003נתנוהו ל\u0004אותן שלוש סאים בתוך \u0003ריחים של גרוסות\u0004 (גריסים), בטחינה עבה ולא דקה, באופן שנועד למנוע תערובת הסובין (שבקליפת הגרגרים) בקמח. \u0003ו\u0004בטחינה זו של שלוש הסאים \u0003הוציאו ממנו\u0004 לבסוף \u0003עשרון\u0004 סולת, אחר \u0003שהוא מנופה בשלש עשרה נפה. והשאר\u0004 (הקמח הנשאר לאחר הוצאת העשרון לעומר) \u0003נפדה\u0004 מן ההקדש ויוצא בכך לחולין, \u0003ו\u0004מעתה הריהו \u0003נאכל\u0004 (מותר באכילה) \u0003לכל אדם, וחייב\u0004 קמח זה \u0003ב\u0004הפרשת \u0003חלה\u0004 מן העיסה הנעשית ממנו, שכן חיוב חלה חל בשעת גלגול העיסה, ודבר זה נעשה לאחר שכבר נפדה הקמח, והריהו חולין. \u0003ו\u0004קמח זה \u0003פטור מן המעשר,\u0004 שכן חיוב \u0003המעשרות הוא בזמן מירוח הכרי, כאשר עורמים את גרגרי התבואה לאחר הוצאת המוץ מהם ומיישרים את פני הערימה. ומירוח גרגרי השעורה הללו היה בזמן שהיו ברשות הקדש, ולא התחייבו במעשרות, שאין מירוח הקדש מחייב במעשרות.\u0004 \u0003ר' עקיבא מחייב\u0004 קמח זה הן \u0003ב\u0004הפרשת \u0003חלה ו\u0004הן \u0003ב\u0004הפרשת ה\u0003מעשרות,\u0004 שכן מתחילה לא היה ברשות ההקדש אלא הקמח הנועד לעשרון, ולא שאר הקמח.","שנינו במשנתנו שנחלקו ר' מאיר וחכמים אם היו מהבהבים בתחילה את גרעיני העומר בעודם בשיבולים באש (כדעת ר' מאיר), או שרק לאחר שחבטו את השיבולים היו מכניסים אותן לאבוב וקולים אותן שם. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"ואם תקריב מנחת בכורים לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\". ו\u0003\"אביב\"\u0004 האמור — הרי \u0003זה אביב\u0004 (ראשית הנקצר), ללמדנו שבא העומר מתבואת השעורים הנקצרת ראשונה. והאמור \u0003\"קלוי באש\"\u0004 — הרי זה \u0003מלמד שהיו ישראל מהבהבין אותו באש,\u0004 קודם לטחינתו וניפויו, \u0003כדי לקיים בו מצות קלי,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003חכמים אומרים:\u0004"],["\u0003אין\u0004 החריכה הישירה ב\u0003אור\u0004 (באש), כשיטת ר' מאיר, בכלל \u0003לשון קלי\u0004 האמורה בתורה (\"קלוי באש\"), \u0003אלא\u0004 הקלוי באש הריהו הנתון בתוך \u0003דבר אחר,\u0004 בכלי. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתקיים \"קלוי באש\"? כדרך שיתבארו הדברים. \u0003אין לשון קלי אלא דבר אחר קליל\u0004 (הנעשה בכלי נחושת קלל). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 היו עושים? כלי \u0003אבוב\u0004 של נחושת, כזה \u0003של קליות\u0004 (מוכרי גרעיני תבואה קלויים בשוק) \u0003היה שם\u0004 בעזרה שבמקדש, \u0003והיה מנוקב\u0004 (מלא בנקבים) \u0003ככברה\u0004 (נפה), \u0003כדי שתהא האור שולטת בכולו\u0004 ובו היו קולים את גרעיני העומר.","עוד שנינו בברייתא: ממה שנאמר \u0003\"אביב קלוי\u0004 באש \u0003גרש\u0004 כרמל\" \u0003איני יודע אם\u0004 המלה \"קלוי\" מוסבת על המלה \"אביב\", שיש לקרוא בכתוב \u0003\"אביב קלוי\",\u0004 לומר שלפני טחינת גרגרי השעורה, כשהם עדיין שלמים יש לקלותם. או \u0003אם\u0004 המלה \"קלוי\" מוסבת על \"גרש\", ויש לקרוא בכתוב \"קלוי באש גרש\" — להשמיענו שיהא ה\u0003גרש קלוי,\u0004 שבתחילה יש לטחון את \u0003גרגרי התבואה, ולאחר מכן קולים את קמח הגריסים. ואולם\u0004 \u0003כשהוא\u0004 (הכתוב) \u0003אומר \"באש\"\u0004 בין המלה \"קלוי\" לבין המלה \"גרש\" — \u0003הפסיק\u0004 את \u0003הענין,\u0004 ואין המלה \"קלוי\" מתייחסת ל\"גרש\" אלא ל\"אביב\". והשמיענו שיש לקלותם קודם טחינה ולא לאחריה.","עוד נאמר בכתוב זה \u0003\"כרמל\",\u0004 ודורשים את המלה כמורכבת מכמה מילים (כמין ראשי תיבות, נוטריקון): \u0003רך ומל,\u0004 שיהו גרגרי התבואה רכים ונמללים ביד. \u0003וכן הוא,\u0004 הכתוב, \u0003אומר\u0004 בנביא אלישע \u0003\"ואיש בא מבעל שלשה ויבא לאיש האלהים לחם בכורים ועשרים לחם שערים וכרמל בצקלנו ויאמר תן לעם ויאכלו\"\u0004 (מלכים ב ד, מב). שאף בו נזכרת המלה \"כרמל\", ואף האמור בו \"בצקלונו\" נדרש בנוטריקון, כרומז למלים: \u0003בא ויצק לנו ואכלנו, ונוה\u0004 (יפה) \u0003היה\u0004 (\"בצקלונו\" — בא ויצק לנו ואכלנו ונו ה).","\u0003ו\u0004כן נדרש הכתוב ה\u0003אומר\u0004 בדברי האשה המפתה לזנות: \"לכה נרוה דודים עד הבוקר \u0003נתעלסה באהבים\"\u0004 (משלי ז, יח), ונדרשת המלה \"נתעלסה\" בדרך נוטריקון: \u0003נשא ונתן\u0004 (נשוחח) בינינו, \u0003ו\u0004לאחר \u0003מכן\u0004 \u0003נעלה\u0004 למיטה, \u0003ונשמח ונתחטא\u0004 (ונתפנק) \u0003באהבים,\u0004 שכך נדרשת המלה \u0003\"נתעלסה\" —\u0004 נ שא ונת ן, נעל ה ונש מח (בחילוף האותיות המצוי \u0003ש'—\u0004 ס') ונתח טא (בחילוף האותיות המצוי ח'— ה'\u0003).\u0004","\u0003ו\u0004כן נדרש הכתוב ה\u0003אומר\u0004 מלה דומה בתיאור העוף הגדול (הנקרא בלשון חכמים \"בר יוכני\") \u0003\"כנף רננים נעלסה\"\u0004 (איוב לט, יג), שנדרשת המלה \"נעלסה\" כראשי תיבות בדרך דומה: \u0003נושא\u0004 את ביצתו \u0003עולה\u0004 עמה למעלה אל הקן המיוחד לו, \u0003ו\u0004שם הוא \u0003נתחטא\u0004 (מוריד) ומניח את ביצתו (\"נעלסה\" — נ ושא, ע ולה ונתח טא).","\u0003ו\u0004כן נדרש הכתוב ה\u0003אומר\u0004 בדברי המלאך לבלעם על האתון \u0003\"כי ירט הדרך לנגדי\"\u0004 (במדבר כב, לב), ונדרשת המלה \"ירט\": \u0003יראתה\u0004 (מורא) \u0003ראתה\u0004 האתון במלאך הניצב לקראתה, ולכך \u0003נטתה\u0004 מן הדרך (\"ירט\" — י ראתה ר אתה נט תה).","ושבים לענין ה\"כרמל\" ואומרים כי החכם \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 בדרשת המלה \u0003\"כרמל\"\u0004 בדרך הנוטריקון — \u0003כר מלא,\u0004 שתהא קליפת הגרעין (\"כר\") מלאה בגרעין הבשל כל צורכו הנתון בה.","ועוד שנינו במשנתנו כי שאר הקמח (לאחר הוצאת העשרון לעומר) חייב \u0003בהפרשת חלה לכשיגולגל כעיסה, אך פטור מהפרשת מעשרות,\u0004 \u0003ו\u0004אילו \u0003ר' עקיבא\u0004 \u0003מחייב\u0004 הן \u0003ב\u0004הפרשת \u0003חלה ו\u0004הן \u0003ב\u0004הפרשת \u0003מעשרות.\u0004 ובפירוש שיטת ר' עקיבא \u0003אמר רב כהנא\u0004 כי \u0003אומר\u0004 (סבור) \u0003היה ר' עקיבא\u0004 ש\u0003מירוח\u0004 (צבירת גרגרי התבואה לכלל ערימה, גורן, ויישורה של \u0003ערימה זו, שהיא הפעולה המחילה את חיוב המעשרות) הנעשה בתבואה שברשות\u0004 \u0003הקדש\u0004 — \u0003אינו פוטר\u0004 את התבואה מחיוב הפרשת המעשרות.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו בדינו של \u0003מותר\u0004 (הקמח הנשאר) מ\u0003שלש סאין הללו\u0004 של שעורים שהובאו לצורך העומר, לאחר שהופרש מהן עשרון הקמח ממנו יבוא העומר, \u0003מה היו עושין בו?\u0004 — הריהו \u0003נפדה\u0004 מן ההקדש במעות ויוצא בכך לחולין, \u0003ו\u0004מעתה הריהו \u0003נאכל\u0004 (מותר באכילה) \u0003לכל אדם, וחייב ב\u0004הפרשת \u0003חלה, ו\u0004אולם הריהו \u0003פטור מן\u0004 הפרשת \u0003המעשרות.\u0004 זו דעת חכמים, ואילו \u0003ר' עקיבא מחייב\u0004 הן \u0003ב\u0004הפרשת \u0003חלה ו\u0004הן \u0003ב\u0004הפרשת \u0003מעשרות\u0004 ממותר זה. \u0003אמרו לו\u0004 חכמים לר' עקיבא: דינה \u0003של\u0004 התבואה שגדלה, נקצרה והתמרחה ברשות ההקדש, ובא אדם ו\u0003פודה\u0004 אותה \u0003מיד גזבר\u0004 ההקדש הממונה על פדיון הקדשים, \u0003יוכיח\u0004 שלא כדבריך. \u0003ש\u0004כן הריהו \u0003חייב ב\u0004הפרשת \u0003חלה ופטור מן\u0004 הפרשת \u0003המעשרות\u0004 בתבואה זו.","\u0003ו\u0004מעתה יש לשאול: \u0003אם\u0004 אמנם \u0003איתא\u0004 \u0005[יש]\u0006 מקום לומר כדברי רב כהנא, ששיטת ר' עקיבא היא ש\u0003מירוח הקדש אינו פוטר\u0004 את התבואה מחיוב מעשרות שבה, \u0003מאי קאמרי ליה\u0004 \u0005[מה הם,\u0006 חכמים, \u0005אומרים לו],\u0006 לר' עקיבא כראיה\u0005,\u0006 והלא \u0003היא היא,\u0004 כדרך שההלכה במותר הקמח בשלוש הסאים שנטחנו לעומר שלדעת ר' עקיבא חייבים במעשר, משום שמירוח הקדש אינו פוטר. אף כן הלכה לדעת ר' עקיבא בתבואה שנתמרחה ברשות הקדש שחייבת במעשר, משום שמירוח הקדש אינו פוטר. ומכאן שאף ר' עקיבא סבור שמירוח הקדש פוטר, ושלא כהסברו של כהנא, מחייב ר' עקיבא את מותר הקמח בהפרשת מעשרות מטעם אחר.","\u0003ועוד איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב כהנא בר תחליפא לרב כהנא (בר מתתיה)\u0004 על הסבר רב כהנא בשיטת ר' עקיבא (שמירוח הקדש אינו פוטר), ממה ששנינו בדין שאר הקמח משלוש הסאים שנטחנו לצורך העומר: \u0003ר' עקיבא מחייב בחלה ובמעשרות, לפי שלא ניתנו מעות\u0004 ההקדש בקניית שלוש הסאים הללו מאת בעל השדה הנקצרת, \u0003אלא לצורך להן\u0004 להבאת העומר, כלומר, לצורך עשרון קמח אחד בלבד. והוא בלבד התקדש, ושאר הקמח לא היה ברשות ההקדש, ולכך גם לא התמרח ברשות ההקדש, וחייב איפוא במעשרות.","\u0003אלא\u0004 יש לומר בהסבר שיטת ר' עקיבא כדרך ש\u0003אמר ר' יוחנן, תלמוד ערוך\u0004 (דין ברור וקבוע) \u0003הוא בפיו של ר' עקיבא\u0004 בטעם חיוב שאר הקמח במעשרות — משום \u0003שלא ניתנו מעות אלא לצורך להן\u0004 בלבד.","ועוד בענין מירוח הקדש, \u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 ש\u0003מירוח הקדש פוטר\u0004 את תבואת העומר \u0003מהפרשת מעשרות.\u0004 \u0003ואפילו ר' עקיבא\u0004 המחייב בהפרשת מעשרות את שאר הקמח (מלבד עשרון העומר) הנשאר משלוש הסאים שנקצרו לעומר, \u0003לא קא\u0004 \u0005[אין הוא]\u0006 \u0003מחייב התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 רק משום \u0003שלא ניתנו\u0004 בתחילה \u0003מעות\u0004 ההקדש לבעל השדה בו נקצרו שלוש סאים אלה, \u0003אלא ל\u0004דבר ש\u0003צורך להן\u0004 בו, לעשרון שבהם. והוא בלבד שהתקדש, ושאר הקמח לא התקדש. \u0003אבל מירוח הקדש בעלמא\u0004 \u0005[סתם],\u0006 בתבואה שגדלה ברשות הקדש — \u0003פוטר\u0004 מן המעשר, לכל הדעות, ואף לשיטת ר' עקיבא.","והוסיף רבא ואמר, כי כמו כן פשוט לי בדין \u0003מירוח\u0004 התבואה הנעשה על ידי \u0003הגוי,\u0004 בתבואה שברשותו כי מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003תורמין\u0004 (מפרישים תרומות ומעשרות) \u0003מ\u0004תבואה \u0003של ישראל על\u0004 תבואה \u0003של ישראל, ו\u0004כן \u0003מ\u0004תבואה \u0003של גוים על\u0004 תבואה \u0003של גוים, ו\u0004כן \u0003מ\u0004תבואה \u0003של כותיים על\u0004 תבואה \u0003של כותיים, ו\u0004כן \u0003מ\u0004תבואתם \u0003של כל\u0004 אחד מאלה הנזכרים (ישראלים, גוים, כותים) \u0003על של כל\u0004 אחד מאלה הנזכרים. אלו \u0003דברי ר' מאיר ור' יהודה.\u0004 הרי שלר' מאיר ור' יהודה מירוח הגוי אינו פוטר את התבואה מתרומות ומעשרות.","ואילו \u0003ר' יוסי ור' שמעון אומרים: תורמין מ\u0004תבואה \u0003של ישראל על\u0004 תבואה \u0003של ישראל, ו\u0004כן \u0003מ\u0004תבואה \u0003של גוים על\u0004 תבואה \u0003של כותיים, ו\u0004כן \u0003מ\u0004תבואה \u0003של כותיים על\u0004 תבואה \u0003של גוים. אבל לא\u0004 תורמים \u0003מ\u0004תבואה \u0003של ישראל על\u0004 תבואה \u0003של גוים ושל כותיים, ו\u0004כן \u0003לא\u0004 תורמים \u0003מ\u0004תבואה \u0003של גוים ושל כותיים על\u0004 תבואה \u0003של ישראל.\u0004 והרי שלר' יוסי ור' שמעון מירוח הגוי (וכן הכותי בכלל) פוטר את התבואה ממעשרות."],["\u0003גלגול\u0004 הבצק (הלישה שהיא המחייבת את העיסה בהפרשת חלה) כאשר הוא נעשה ברשות \u0003ה\u0004\u0003הקדש\u0004 — \u0003פוטר\u0004 את העיסה מחיוב הפרשת חלה ממנה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת חלה: \u0003הקדישה\u0004 האשה את \u0003עיסתה,\u0004 \u0003עד שלא\u0004 (בטרם) \u0003גלגלה\u0004 אותה, וחזרה \u0003ופדאתה\u0004 את העיסה מן ההקדש בכסף, וגלגלה אותה — הרי היא \u0003חייבת\u0004 בחלה, שהרי בשעת הגלגול היתה העיסה ברשות ההדיוט. וכן אם הקדישה האשה את העיסה \u0003מש\u0004 כבר \u0003גלגלה\u0004 אותה ואחר כך חזרה \u0003ופדאתה\u0004 מן ההקדש — הרי העיסה \u0003חייבת\u0004 בהפרשת חלה, שכן בשעת הגלגול היתה ברשות ההדיוט, וכבר התחייבה בהפרשת חלה. אבל אם \u0003הקדישה\u0004 את העיסה \u0003עד שלא\u0004 \u0003גלגלה\u0004 אותה, ועמד \u0003וגלגלה הגזבר\u0004 של ההקדש, \u0003ואחר כך\u0004 חזרה האשה ו\u0003פדאתה\u0004 את העיסה מידי ההקדש — \u0003פטורה\u0004 העיסה מהפרשת חלה, משום \u0003שבשעת חובתה\u0004 (החלת החיוב), שהוא זמן הגלגול, \u0003היתה\u0004 העיסה \u0003פטורה.\u0004","עד כאן היה פשוט לרבא, ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: גלגול\u0004 עיסה שברשות \u0003גוי מאי\u0004 \u0005[מה]\u0006 הדין לענין חיוב הפרשת חלה. ומסביר רבא את בעייתו זו, הלא \u0003מיתנא תנן\u0004 \u0005[שנינו]:\u0006 \u0003גר שנתגייר והיתה לו\u0004 ברשותו \u0003עיסה,\u0004 אם הבצק \u0003נעשה עד שלא נתגייר\u0004 — הרי שבשעת חיוב חלה היתה העיסה ברשות גוי, ולכך הריהו \u0003פטור\u0004 מהפרשת חלה. ואם נעשה הבצק \u0003מש\u0004 כבר \u0003נתגייר\u0004 — \u0003חייב\u0004 בהפרשת חלה, שהרי בשעת החיוב היתה העיסה ברשות ישראל. ואם הוא \u0003ספק\u0004 מתי התגלגלה העיסה, אם לפני שהתגייר או לאחר שהתגייר — \u0003חייב\u0004 להפריש חלה מספק.","ויש לדון במה ששנינו במשנה זו שגלגול הגוי פוטר את העיסה מהפרשת חלה: משנה \u0003הא\u0004 \u0005[זו],\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 מבין התנאים שנחלקו בדין מירוח הגוי לענין חיוב התבואה במעשרות, \u0003קתני לה\u0004 \u0005[שנה אותה]?\u0006 — כ\u0003דברי הכל היא. ואפילו ר' מאיר ור' יהודה דקמחייבי התם\u0004 \u0005[שהם מחייבים שם\u0006 בהפרשת מעשרות במירוח הגוי\u0005],\u0006 \u0003פטרי הכא\u0004 \u0005[פוטרים כאן\u0006 בהפרשת חלה בגלגול הגוי\u0005],\u0006 וטעם הדבר: דווקא","\u0003התם\u0004 \u0005[שם,\u0006 בהפרשת מעשרות במירוח הגוי\u0005]\u0006 הדין \u0003הוא,\u0004 לדעתם, שמעשה החיוב הנעשה ברשות הגוי מחייב, משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בחיוב הפרשת מעשרות המלה \u0003\"דגנך\"\u0004 (\"לא תוכל לאכול בשעריך מעשר דגנך ותירושך ויצהרך\". דברים יב, יז), הרי זו לשון מיעוט: דווקא דגנך הוא המתחייב במעשרות, ולא דגן אחר. ושוב חזרה \u0003ונאמרה המלה\u0004 \u0003\"דגנך\"\u0004 במצות אכילת המעשרות בירושלים (\"ואכלת לפני ה' אלהיך במקום אשר יבחר לשכן שמו שם מעשר דגנך תירושך ויצהרך...\". שם יד, כג), ועוד \u0003נאמרה המלה \"דגנך\" בחיוב הנתינה לכהן (\"ראשית דגנך תירושך ויצהרך... תתן לו\". שם יח, ד), שמלה\u0004","\u0003יתירא\u0004 \u0005[יתירה]\u0006 היא, \u0003הוי\u0004 \u0005[הריהו]\u0006 איפוא לשון \u0003מיעוט אחר\u0004 לשון \u0003מיעוט, ו\u0004כלל הוא ש\u0003אין מיעוט אחר מיעוט אלא לרבות\u0004 — \u0003אפילו\u0004 את התבואה שנעשה בה מירוח ברשות ה\u0003גוים.\u0004","\u0003אבל הכא\u0004 \u0005[כאן,\u0006 בדין הפרשת חלה\u0005],\u0006 \u0003תרי זימני\u0004 \u0005[שתי פעמים]\u0006 המלה \u0003\"ערסתיכם\" כתיב\u0004 \u0005[נאמרה],\u0006 בדין הפרשת חלה (\"ראשית עריסותיכם חלה תרימו תרומה כתרומת גורן כן תרימו אותה. מראשית עריסותיכם תתנו לה' תרומה לדורותיכם\", במדבר טו, כ— כא). ואין המלה \"עריסותיכם\" מקרא יתר, שכן כתוב \u0003חד\u0004 \u0005[אחד]\u0006 \u0003\"ערסתיכם\"\u0004 בא ללמדנו כי חיוב הפרשת חלה הוא בעיסה ששיעורה הוא \u0003כדי\u0004 (כשיעור) \u0003עיסתכם\u0004 הנהוגה במדבר סיני (עומר), כשנאמרה מצוה זו. \u0003ו\u0004כתוב \u0003חד\u0004 \u0005[אחד]\u0006 נוסף האומר \u0003\"ערסתיכם\"\u0004 בא ללמד כי דווקא עיסת ישראל חייבת בחלה, \u0003ולא עיסת גוים ולא עיסת הקדש.\u0004 זו אפשרות אחת להבנת הדברים.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי דברי המשנה הפוטרת את העיסה שהתגלגלה ברשות הגוי מהפרשת חלה \u0003ר' יוסי ור' שמעון קתני לה, דקא פטרי\u0004 \u0005[הם השונים אותה, ש\u0006כן \u0005הם פוטרים]\u0006 את התבואה ממעשרות על ידי מירוח גויים, \u0003אבל ר' מאיר ור' יהודה\u0004 הסבורים שמירוח גוי אינו פוטר ממעשרות, \u0003גמרי\u0004 \u0005[לומדים]\u0006 דינה של העיסה שגולגלה על ידי גוי שחייבת בהפרשת חלה, בגזירה שווה של המלים \u0003\"ראשית\"\u0004 (\"ראשית עריסותיכם...\" האמורה בחלה), \u0003\"ראשית\"\u0004 (\"ראשית דגנך\" האמורה במעשרות) \u0003מהתם\u0004 \u0005[משם,\u0006 ממעשרות\u0005],\u0006 שכשם שחייבת התבואה שהתמרחה בידי גוי במעשרות, כן חייבת העיסה שגולגלה בידי גוי בהפרשת חלה.","\u0003אמר רבא: יהא רעוא דאחזיה בחילמא\u0004 \u0005[יהי רצון ש\u0006אזכה ו\u0005אראה\u0006 את הפתרון לשאלה זו \u0005בחלום].\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא\u0004 בפתרון בעייתו: \u0003מאן דאמר\u0004 \u0005[מי\u0006 מבין התנאים \u0005שאומר]\u0006 כי \u0003מירוח הגוי פוטר\u0004 את התבואה מחיוב מעשרות, הוא גם זה האומר \u0003כי\u0004 \u0003גלגול הגוי\u0004 את העיסה \u0003פוטר\u0004 אותה מחיוב הפרשת חלה. ואילו \u0003מאן דאמר\u0004 \u0005[מי\u0006 מבין התנאים \u0005שאומר]\u0006 כי \u0003מירוח הגוי אינו פוטר\u0004 את התבואה מהפרשת מעשרות, הוא גם האומר כי \u0003גלגול הגוי\u0004 את העיסה \u0003אינו פוטר\u0004 אותה מהפרשת חלה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב פפא לרבא\u0004 על דבריו אלה, ממה ששנינו בברייתא: \u0003גוי שהפריש\u0004 שה לפדות בו \u0003פטר חמור\u0004 שנולד לו מאתון מבכירה, \u0003ו\u0004כן גוי שהפריש מעיסתו \u0003חלה\u0004 — \u0003מודיעים אותו שהוא פטור\u0004 מפדיון פטר חמור ומהפרשת חלה, ואין קדושה חלה על אלה, \u0003ו\u0004לכך \u0003חלתו נאכלת\u0004 אף \u0003לזרים\u0004 (שאינם כהנים), \u0003ו\u0004אין איסור הנאה ב\u0003פטר\u0004 ה\u0003חמור,\u0004 והריהו \u0003גוזז\u0004 את \u0003שערו,\u0004 \u0003ועובד בו.\u0004","ויש לדייק בדברי הברייתא: דווקא בדברים אלה אין קדושה, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד ש\u0003תרומתו\u0004 של גוי \u0003אסורה,\u0004 שסבור התנא של ברייתא זו, שמירוח הגוי אינו פוטר את התבואה מחיובה במעשרות, \u0003והא\u0004 \u0005[והרי]\u0006 נמצא איפוא כי \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 הוא ש\u0003אמר\u0004 כי \u0003מירוח הגוי אינו פוטר\u0004 את התבואה מהפרשת מעשרות, \u0003ו\u0004הוא שאמר \u0003כי\u0004 \u0003גלגול גוי פוטר\u0004 את העיסה מהפרשת חלה!","\u0003ועוד\u0004 כיוצא בזה \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 ממה ששנינו בברייתא אחרת, כי \u0003חלת גוי\u0004 שהפריש מעיסתו שנילושה מקמח תבואה שגדלה ברשותו \u0003בארץ, ו\u0004כן \u0003תרומתו\u0004 של גוי שהפרישה מתבואה שגדלה ברשותו \u0003בחוצה לארץ\u0004 — \u0003מודיעין אותו שהוא פטור\u0004 מלהפריש חלה ותרומה, ואין במה שהפריש קדושה, ולכך \u0003חלתו נאכלת\u0004 אף \u0003לזרים, ותרומתו\u0004 אם התערבה בתבואת חולין \u0003אינה מדמעת\u0004 (אוסרת באכילה לישראל את התערובת). ויש לדייק בדברי הברייתא: דווקא בתבואה של הגוי שגדלה ברשותו בחוצה לארץ אין כל קדושה (שהרי אף בישראל, אין חיוב התרומה בחוץ לארץ אלא מדברי חכמים), \u0003הא\u0004 \u0005[הרי]\u0006 מכאן כי \u0003תרומתו\u0004 של גוי שתרם מתבואה שגדלה ברשותו \u0003בארץ אסורה\u0004 באכילה לישראל, \u0003ומדמעת\u0004 את תערובת החולין שנפלה לתוכה. ואולם שנינו באותה ברייתא כי חלתו של גוי בארץ אין בה כל קדושה.","\u0003והא\u0004 \u0005[והרי]\u0006 למדנו כי \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 ש\u0003אמר\u0004 כי \u0003מירוח הגוי אינו פוטר,\u0004 הוא גם זה שאמר כי \u0003גלגול הגוי פוטר!\u0004 ומתרצים: בעיקרו של דבר, התנא הסבור כי גלגול הגוי פוטר את העיסה מחלה הוא גם זה הסבור שמירוח הגוי פוטר את התבואה ממעשרות.","ואולם דין זה שמירוחו אינו פוטר את התבואה, אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שגזרו בו כן, כ\u0003גזירה משום בעלי כיסים\u0004 (אנשים עשירים) שיבואו להערים על הפרשת מעשרותיהם, וימכרו לגוי את תבואותיהם, על מנת שימרחן הגוי, ויפטרן בכך מחיוב מעשרות."],["ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שהטעם שאין מירוח הגוי פוטר את התבואה הוא גזירת חכמים משום בעלי כיסים, \u0003אפילו\u0004 ב\u0003חלה נמי\u0004 \u0005[גם כן]\u0006 יגזרו חכמים שגלגול הגוי אינו פוטר מהפרשת חלה, ומשום בעלי כיסים! ומשיבים: אין מקום לגזור כן בהפרשת חלה, שכן כל הרוצה להשתמט ממצות הפרשת חלה, אינו נזקק לשם כך למכור את עיסתו לגוי, אלא \u0003אפשר\u0004 לו להיפטר מחיוב הפרשת חלה באופן פשוט יותר, \u0003דאפי לה\u0004 \u0005[שיאפה אותה,\u0006 את העיסה\u0005]\u0006 בפחות משיעור הבצק המחייב בהפרשת חלה, שהוא \u0003פחות מחמשת רבעים קמח ועוד,\u0004 ואז לא יתחייב.","ומקשים עוד: והרי ב\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר\u0004 לו לרוצה להערים ולהשתמט מהפרשת תרומה מתבואתו לעשות כן אף בלא למוכרה לגוי שהוא ימרחנה, ובאופן \u0003דעביד לה\u0004 \u0005[שיעשה בה]\u0006 כמו שאמר \u0003ר' אושעיא.\u0004 שכך \u0003אמר ר' אושעיא:\u0004 כיון שראיית פני הבית לאחר זריית התבואה ומירוחה היא המחייבת את התבואה בתרומה ומעשרות, \u0003מערים אדם על תבואתו\u0004 כדי שלא להפריש ממנה מעשרות, \u0003ומכניסה\u0004 לתוך הבית עוד לפני שזרו את התבואה, בעודה עדיין \u0003במוץ שלה, כדי ש\u0004בכך \u0003תהא בהמתו אוכלת\u0004 מן התבואה הזו \u0003ופטורה\u0004 \u0003מן המעשר. אי נמי\u0004 \u0005[או גם כן]\u0006 באופן אחר, \u0003דעייל לה\u0004 \u0005[שמכניס\u0006 הוא \u0005אותה]\u0006 אל ביתו, לא דרך שער הבית, אלא \u0003דרך גגות ודרך קרפיפות,\u0004 ובאופן זה אין התבואה מתחייבת. ומדוע נזקקו חכמים לגזור על תבואת ישראל שנתמרחה על ידי הגוי שתהא חייבת במעשרות?!","ומשיבים: אין הדברים דומים, שכן \u0003התם\u0004 \u0005[שם,\u0006 בתבואה\u0005]\u0006 יש מקום לגזור משום בעלי כיסים שיעמדו וימכרו את תבואותיהם לגוי, מפני שאין זה נוח להם לפטור את תבואותיהם בהכנסתה לביתם בעודה במוץ, או דרך גגות וקרפיפות, שכן הריהם דברים הנעשים \u0003בפרהסיא\u0004 (בפומבי), הנראית לכל, ו\u0003זילא ביה מילתא\u0004 \u0005[מזולזל בו הדבר],\u0006 שלא ירצה להתבזות על ידי אנשים שיראו שהוא מערים על המעשרות. וכדי להפטר מחובת המעשרות עלול הוא למכור את תבואותיו לגוי שימרחם, ויש מקום לגזור בו. ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 בהפרשת חלה\u0005]\u0006 שנעשה הדבר \u0003בצינעא,\u0004 שאין בני אדם רואים בו שהוא עושה את עיסתו בשיעור פחות מכדי חיוב חלה, ו\u0003לא זילא ביה מילתא\u0004 \u0005[אין הדבר מזלזל בו],\u0006 אין מקום לגזור שמא יבוא למכור את עיסתו לגוי לפוטרה מן \u0005החלה.\u0006","וממשיכים בתיאור סדר הבאת העומר. לאחר שנופה עשרון הקמח המיועד לעומר, לאחר שהאיר כבר יום ט\"ז בניסן \u0003בא לו לעשרון,\u0004 ו\u0003נתן עליו\u0004 מקצת מ\u0003שמנו\u0004 (מלוג השמן) בכלי שבידו, ונתן עליו את הסולת, \u0003ו\u0004הניח את \u0003לבונתו\u0004 מן הצד בכלי. ו\u0003יצק\u0004 מהשמן שבלוג גם על הסולת, \u0003ובלל\u0004 אותם כאחד, את הסולת והשמן. וחזר ויצק פעם נוספת מהשמן על הסולת הבלולה (שכן כל המנחות טעונות שלוש נתינות שמן). ולאחר מכן \u0003הניף\u0004 מעלה את מנחת העומר, \u0003והגיש\u0004 אותה אל כנגד חודה של הקרן הדרומית מערבית של המזבח. ולאחר מכן \u0003קמץ\u0004 ממנה את הקומץ, \u0003ו\u0004לאחר שמלח את הקומץ, \u0003הקטיר\u0004 את הקומץ ואת הלבונה על המזבח. \u0003והשאר\u0004 (שאר העומר) \u0003נאכל\u0004 (ניתן לאכילה בעזרה) \u0003לכהנים.\u0004","\u0003משקרב\u0004 (מיד לאחר שקרב) \u0003העומר\u0004 ביום ט\"ז בניסן, \u0003יוצאין\u0004 אנשים מביתם \u0003ו\u0004כבר \u0003מוצאין\u0004 את \u0003שוק ירושלים שהוא מלא קמח קלי\u0004 הבא מהתבואה החדשה, שהותרה לאכילה על ידי הנפת העומר. ודבר זה היה נעשה \u0003שלא ברצון חכמים,\u0004 שאנשים הקדימו וקצרו וטחנו מן התבואה החדשה לפני הבאת העומר המתיר את החדש, ויש לחשוש שיבואו לאכול מן החדש קודם הנפת העומר, אלו \u0003דברי ר' מאיר,\u0004 ואילו \u0003ר' יהודה אומר\u0004 כי \u0003ברצון חכמים היו עושין,\u0004 שלא חששו לכך.","שנינו בסוף משנתנו בענין שווקי ירושלים שהיו מלאים בקמח קלי מיד לאחר הנפת העומר, ושהיה זה שלא ברצון חכמים, ולדעת ר' יהודה היה זה ברצון חכמים, שלא חששו שיבואו אנשים לאכול מן התבואה החדשה לפני הנפת העומר. ושואלים: \u0003ו\u0004האם \u0003לא גזר ר' יהודה דלמא אתי למיכל מיניה\u0004 \u0005[שמא יבואו לאכול ממנו],\u0006 מן החדש, תוך כדי העיסוק בו?","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדבריו אלה ממה ששנינו בדין בדיקת חמץ, ש\u0003ר' יהודה אומר\u0004 כי יתכן שיהיו \u0003בודקין\u0004 את החמץ בערב פסח שלוש פעמים: מלכתחילה הריהו בודק \u0003אור\u0004 (בליל) \u0003ארבעה עשר\u0004 בניסן. \u0003ו\u0004אם לא בדק בליל י\"ד בניסן, הריהו בודק \u0003ב\u0004יום \u0003ארבעה עשר\u0004 ב\u0003שחרית, ו\u0004אם לא בדק בשחרית, הריהו בודק \u0003בשעת הביעור\u0004 (שריפת החמץ, בתחילת השעה הששית). ואולם מכאן והלאה, לאחר שכבר חל איסור אכילת חמץ, לא יבדוק. שחשש ר' יהודה שמתוך שמתעסק בדבר האסור, עלול הוא להיכשל ולאוכלו. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 שאם \u0003לא בדק\u0004 בליל י\"ד, יבדוק ביום י\"ד בשחרית, ואם לא בדק אז — יבדוק לאחר מכן, ואף לאחר שחל איסור אכילת חמץ, ואפילו בתוך הפסח עצמו. הרי שר' יהודה חושש שמא בתוך עיסוקו של אדם בדבר, עלול הוא להיכשל באכילתו, ושלא כדבריו במשנתנו!","\u0003אמר רבה\u0004 בתירוץ הסתירה: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא עניינו של איסור \u0003חדש\u0004 מאיסור חמץ בפסח, שכן באיסור חדש חשש ר' יהודה שיבוא אדם לאוכלו,"],["וטעם הדבר, שכן \u0003מתוך שלא היתרתה לו\u0004 לאדם לקצור במגל את התבואה לפני הנפת העומר \u0003אלא על ידי קיטוף\u0004 (קטיפה) ביד בלבד, \u0003זכור הוא\u0004 מתוך כך שלא לאכול מתבואה זו קודם הנפת העומר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003תינח\u0004 \u0005[נוח]\u0006 הסבר זה לענין ה\u0003קצירה,\u0004 שכיון שקצרו על ידי שינוי אין לחשוש שמא יבוא לאוכלם קודם הנפת העומר, ואולם בענין מלאכות ה\u0003טחינה ו\u0004ה\u0003הרקדה\u0004 (ניפוי) שעשו אנשים בתבואה החדשה קודם להנפת העומר בדרך הרגילה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע אין ר' יהודה חושש שיבוא לאכול מן התבואה החדשה, כדרך שהוא חושש לכך בבדיקת חמץ?","ומשיבים: אף \u0003הא\u0004 \u0005[זה]\u0006 \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן גם המלאכות הללו נ \u0005עשו בשינוי, ועל ידי כך היו עושי המלאכות הללו זכורים שלא לאכול מהתבואה החדשה. ומסבירים מה היה השינוי בדרך מלאכתן של אלה: ב\u0006\u0003טחינה\u0004 — שהיו טוחנים \u0003בריחיא דידא\u0004 \u0005[בריחיים של יד],\u0006 ולא בריחיים גדולים כרגיל. \u0003וב\u0004\u0003הרקדה\u0004 — שהיו מנפים לא בתוך הנפה, כדרך הרגילה, אלא \u0003על גבי\u0004 ה\u0003נפה,\u0004 כלומר, שהופכים את הנפה ומנפים מהצד השני.","ומוסיפים ושואלים עוד על שיטת ר' יהודה ממה ששנינו במשנה בדין קציר שדה \u0003בית השלחין\u0004 (שדה המושקית בידי בני אדם) \u0003דשריא\u0004 \u0005[שמותרת]\u0006 בה \u0003קצירה\u0004 אף לפני העומר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בפרקנו (להלן מנחות עא,א). \u0003קוצרין\u0004 שדות \u0003בית השלחין ש\u0004נמצאות \u0003בעמקים,\u0004 \u0003אבל לא גודשין\u0004 (עורמים לערימה) אותו קציר לפני הנפת העומר. ולפי דברי ר' יהודה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 והלא יש לחשוש שמא כשהוא קוצרה, יבוא לאכול ממנה שלא כדין, ואין היכר בקצירתן של תבואות אלה המזכיר לקוצר שאין לאכול מהן!","\u0003אלא אמר אביי\u0004 הסבר אחר מדוע ר' יהודה אינו חושש בזמן עשיית המלאכות בתבואה החדשה בזמן איסור החדש, ואילו בבדיקת חמץ בזמן איסור חמץ הריהו חושש: שכן, שונה הוא איסור חדש מאיסור חמץ, שאיסור \u0003חדש\u0004 — אדם \u0003בדיל מיניה\u0004 \u0005[נבדל,\u0006 פרוש \u0005ממנו],\u0006 שהרי לא הותרה אכילתו אלא משיונף העומר ביום ט\"ז בניסן. אבל \u0003חמץ\u0004 — \u0003לא בדיל מיניה\u0004 \u0005[אין\u0006 אדם \u0005נבדל ממנו]\u0006 שהרי כל הזמן הוא אוכל חמץ. ולכך, באיסור אכילת חמץ יש לחשוש שיבוא אדם לאכול ממנו תוך כדי עיסוקו בו, מה שאין כן באיסור אכילת חדש.","\u0003אמר רבא\u0004 בדחיית דברי אביי אלה: וכי רק מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה קשיא\u0004 \u0005[קשה],\u0006 ומתורצת הסתירה כהצעת אביי, \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[\u0006\u0005מדברי חכמים על דברי חכמים לא\u0006 \u0005קשה]?\u0006 והרי גם בדבריהם נראית סתירה, שכן באיסור חדש הריהם חוששים שיבוא אדם לאכול מהתבואה החדשה מתוך עיסוקו בה, ואילו באיסור חמץ אין הם חוששים לכך, ומתירים את בדיקת החמץ אף בתוך זמן איסור חמץ. ומה איפוא יש לתרץ בסתירה זו שבדברי חכמים?","\u0003אלא אמר רבא:\u0004 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן יש ליישב את הסתירה \u0003כדשנינן\u0004 \u0005[כמו שתירצנו]\u0006 בהצעת אביי. ואף הסתירה \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[מדברי חכמים על דברי חכמים אינה קשה],\u0006 שכן באיסור חמץ אין אנו חוששים שמא יבוא לאוכלו, שהרי כיון ש\u0003הוא עצמו מחזר עליו\u0004 (מחפש אחריו) על מנת \u0003לשורפו,\u0004 וכי יש לחשוש ש\u0003מיכל אכיל מיניה\u0004 \u0005[יאכל ממנו]?!\u0006","\u0003רב אשי אמר\u0004 תירוץ אחר: הסתירה מדברי \u0003ר' יהודה\u0004 בדין איסור חדש על דברי \u0003ר' יהודה\u0004 בדין בדיקת חמץ \u0003לא קשיא\u0004 \u0005[אינה קשה],\u0006 שאף שר' יהודה חושש שיבוא אדם לאכול מהדבר האסור בו הוא מתעסק (כבדין החמץ), הוא מתיר חדש, שהרי ב\u0003קמח קלי תנן\u0004 \u0005[שנינו]\u0006 במשנה, שאינו ראוי לאכילה.","ומעירים על תירוצו זה של רב אשי: \u0003והא\u0004 \u0005[ו\u0006תירוץ \u0005זה]\u0006 שאמר \u0003רב אשי ברותא\u0004 \u0005[טעות]\u0006 \u0003היא.\u0004 ומסבירים: \u0003תינח\u0004 \u0005[נניח]\u0006 כי \u0003מ\u0004זמן שעושה אותם קמח ו\u0003קלי ואילך\u0004 (והלאה), אין הם ראויים לאכילה, ואולם מזמן הקצירה והטחינה ו\u0003עד\u0004 שעושה אותם \u0003קלי,\u0004 שראויים הם לאכילה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 ומדוע התיר ר' יהודה לעסוק בהם?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בהסבר הדברים, כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אין חוששים, כיון שיש בקצירתם היכר המזכיר לאדם שהדבר אסור באכילה, שמותרים להיקצר רק \u0003על ידי קיטוף, ו\u0004כמו שאמר \u0003רבה\u0004 בהסברו למעלה, ואולם ממה ששנינו בתבואת \u0003בית השלחין\u0004 שבעמקים \u0003דשריא\u0004 \u0005[שמותרת]\u0006 בה ה\u0003קצירה\u0004 אף בכלי, ובה אין היכר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אלא\u0004 יש לסכם כי אמירה \u0003הא\u0004 \u0005[זו]\u0006 של \u0003רב אשי ברותא\u0004 \u0005[טעות]\u0006 \u0003היא.\u0004","\u0003משקרב העומר\u0004 ביום ט\"ז בניסן — \u0003הותר\u0004 לאכילה יבול התבואה ה\u0003חדש מיד.\u0004 ואלו המצויים במקומות \u0003הרחוקים\u0004 מירושלים, שאינם יודעים אם כבר קרב העומר — \u0003מותרין\u0004 באכילת החדש \u0003מ\u0004זמן \u0003חצות היום\u0004 בירושלים \u0003ולהלן\u0004 (והלאה). כך היה בזמן שבית המקדש היה קיים. ואולם \u0003משחרב\u0004 \u0003בית המקדש, התקין רבן יוחנן בן זכאי שיהא יום הנף\u0004 (הנפת) העומר, הוא יום ט\"ז בניסן, \u0003כולו אסור,\u0004 ויאכלו מהתבואה החדשה רק למחרתו.","\u0003אמר ר' יהודה:\u0004 לא היה צריך רבן יוחנן בן זכאי להתקין תקנה זו, \u0003והלא מן התורה\u0004 יום זה כולו \u0003הוא אסור\u0004 באכילת החדש, \u0003ש\u0004כן \u0003נאמר\u0004 בתורה \"ולחם וקלי וכרמל לא תאכלו \u0003עד עצם היום הזה\u0004 עד הביאכם את קרבן אלקיכם....\" (ויקרא כג, יד), ומובן הכתוב — עד עיצומו של יום זה, ועד בכלל, אסורה היא אכילת החדש, אלא שהנפת העומר מתירה אותה. ואולם כשאין הנפת העומר, חזר הדין וכל יום ט\"ז בניסן אסור באכילת החדש. \u0003ו\u0004\u0003מפני מה\u0004 הגרים במקומות \u0003הרחוקים\u0004 מירושלים \u0003מותרין מחצות היום ולהלן,\u0004 אף בזמן שבית המקדש היה קיים? \u0003מפני שהן יודעין שאין בית דין מתעצלין בו,\u0004 בהבאת העומר, ומזרזים את כל העוסקים בהבאתו, על מנת שיביאוהו בהקדם, ואחר חצות ודאי שכבר הקריבוהו.","שנינו במשנתנו כי לדעת ר' יהודה בזמן שאין בית המקדש קיים — כל יום ט\"ז בניסן אסור מן התורה באכילת החדש, ולכך אין צורך בתקנת רבן יוחנן בן זכאי. ובהסבר דעת החולקים עליו וסבורים שבזמן שאין בית המקדש קיים — כל יום ט\"ז בניסן מותר באכילה, מביאים, \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בזמן שבית המקדש\u0004 היה \u0003קיים\u0004 — ה\u0003עומר\u0004 היה \u0003מתיר\u0004 את אכילת החדש, ואילו \u0003בזמן שאין בית המקדש קיים\u0004 — \u0003האיר\u0004 ה\u0003מזרח,\u0004 כלומר, מיד בהנץ החמה של יום שישה עשר בניסן — הרי הוא \u0003מתיר\u0004 את אכילת החדש.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר, מה מקור הדברים\u0005]?\u0006 שכן \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות\u0006 סותרים \u0005נאמרו]\u0006 בדין איסור אכילת החדש: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד \u0003\"עד יום הביאכם\",\u0004 שמשמעו שאיסור זה נוהג עד שעת הבאת העומר ביום ט\"ז בניסן, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק גם \u0005:\u0006 \u0003\"עד עצם היום הזה\",\u0004 שמשמעו עד הופעתו של יום ט\"ז בניסן (שכן לדעתם, משמע המלה \"עד\" — ולא עד בכלל), והרי זה כעין סתירה, שכן הבאתו יכולה להיות בתוך היום, או בבוקר או יותר מאוחר! ומעתה יש לשאול: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב סתירה זו?","אלא \u0003כאן\u0004 שאמר הכתוב שזמן ההיתר הוא שעת הבאת העומר — הרי זה אמור \u0003בזמן שבית המקדש קיים.\u0004 ואילו \u0003כאן\u0004 שאמר הכתוב שזמן ההיתר הוא עם הופעתו של יום ט\"ז בניסן — הרי זה אמור \u0003בזמן שאין בית המקדש קיים.\u0004","ואילו \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 הצעת הלכה שונה משל רב ושמואל, ולדעתם \u0003אפילו בזמן שבית המקדש קיים\u0004 — הזמן בו \u0003האיר\u0004 ה\u0003מזרח,\u0004 כלומר הופעת יום ט\"ז בניסן, הוא ה\u0003מתיר\u0004 את התבואה החדשה. ומקשים על כך: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"עד הביאכם\"\u0004 שמשמע ממנו כי הנפת העומר היא המתירה את החדש, ואם הונפה יותר מאוחר אין החדש מותר עד לאותה שעה! ומשיבים: דבר זה הוא \u0003למצוה,\u0004 שאכן ראוי להמתין מאכילת החדש עד הנפת העומר, אף שהחדש כבר הותר, ואולם כל שאכל לפני כן — לא עבר על איסור תורה.","ומקשים עוד: והרי שנינו במשנתנו כי \u0003משקרב העומר\u0004 — \u0003הותר\u0004 ה\u0003חדש מיד,\u0004 הרי משמע שהנפת העומר היא המתירה, וקודם לכן היה החדש אסור באכילה! ומשיבים: גם דברי משנתנו אלה אינם אלא \u0003למצוה,\u0004 שכך הוא הראוי לעשות, ואולם החדש כבר הותר לאכילה כאשר האיר היום.","ומקשים עוד: והרי שנינו במשנה (בעמוד הבא) כי \u0003העומר היה מתיר\u0004 את אכילת החדש \u0003במדינה,\u0004 כלומר, בכל מקום, \u0003ושתי הלחם\u0004 הקרבים בחג השבועות היו מתירים את ההקרבה של המנחות \u0003במקדש\u0004 מהתבואה החדשה. הרי משמע שהעומר הוא המתיר את אכילת החדש! ומשיבים באותו אופן: אף דברי משנה זו לא נאמרו אלא \u0003ל\u0004ענין ה\u0003מצוה\u0004 שכך ראוי לעשות, ואולם לעיקרו של דין, הותר כבר החדש באכילה משהאיר היום."],["\u0003משחרב בית המקדש,\u0004 עמד ו\u0003התקין רבן יוחנן בן זכאי שיהא יום הנף\u0004 (הנפת העומר) \u0003כולו אסור\u0004 באכילת התבואה החדשה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — אם יתרגלו אנשים לאכול מן החדש ביום ט\"ז בניסן (\"יום הנף\") כבר כשהאיר היום, הרי אנו מצפים כי ב\u0003מהרה\u0004 יחזור ו\u0003יבנה בית המקדש, ו\u0004יש לחשוש \u0003ש\u0004\u0003יאמרו אשתקד\u0004 (בשנה שעברה) \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אכלנו\u0004 מן החדש כבר \u0003בהאיר\u0004 ה\u0003מזרח\u0004 ביום ט\"ז בניסן? \u0003השתא נמי ניכול\u0004 \u0005[עכשיו גם כן נאכל]\u0006 משעה זו.","\u0003ולא ידעי\u0004 \u0005[ואינם יודעים]\u0006 ש\u0003אשתקד לא הוה\u0004 \u0005[לא היה]\u0006 הנף ה\u0003עומר,\u0004 ולכן \u0003האיר מזרח\u0004 הוא שהיה ה\u0003מתיר, ו\u0004אולם \u0003השתא דאיכא\u0004 \u0005[עכשיו ש\u0006נבנה בית המקדש ו\u0005יש]\u0006 הנף ה\u0003עומר\u0004 — הנף ה\u0003עומר\u0004 הוא ה\u0003מתיר,\u0004 ואין לאכול מן החדש לפני כן. ולכך גזר רבן יוחנן בן זכאי איסור אכילת החדש בכל היום כולו. ויש לשאול: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שכוונת הכתוב \"עד הביאכם\" (ויקרא כג, יד), שאף בזמן שבית המקדש היה קיים, ההמתנה מלאכול מן החדש לפני ההנפה היא \u0003למצוה\u0004 בלבד, הרי זה תמוה: וכי \u0003משום\u0004 החשש שיבואו אנשים ויבטלו \u0003מצוה\u0004 כשיבנה המקדש, \u0003ליקום וליגזור\u0004 \u0005[יעמוד ויגזור]\u0006 רבן יוחנן איסור אכילה בימינו על כל היום \u0005כולו?\u0006","\u0003אמר רב נחמן בר יצחק\u0004 בתשובה: \u0003רבן יוחנן בן זכאי בשיטת ר' יהודה\u0004 השנויה במשנתנו, \u0003אמרה\u0004 לשיטתו. שכך \u0003אמר:\u0004 כאשר אין מניפים את העומר, \u0003מן התורה\u0004 החדש \u0003אסור\u0004 באכילה כל אותו יום. \u0003שנאמר\u0004 \"ולחם וקלי וכרמל לא תאכלו \u0003עד עצם היום הזה\"\u0004 (שם), ופירושו","\u0003—\u0004 \u0003עד עיצומו\u0004 (עצמו) \u0003של\u0004 ה\u0003יום\u0004 (כל היום כולו). \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 רבן יוחנן בן זכאי ששימוש המלה \u0003\"עד\"\u0004 הנזכרת בכתוב הריהו: עד אותו היום, \u0003ו\u0004אף \u0003עד\u0004 הוא \u0003בכלל,\u0004 שכל יום זה אף הוא בכלל איסור אכילה.","ושואלים על תשובה זו: \u0003ומי סבר לה כוותיה\u0004 \u0005[והאם סבור הוא\u0006 ר' יהודה \u0005כמותו,\u0006 כשיטת רבן יוחנן בן זכאי\u0005]?\u0006 \u0003והא מיפלג פליג עליה\u0004 \u0005[והרי חולק הוא עליו]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003משחרב בית המקדש, התקין רבן יוחנן בן זכאי שיהא יום הנף כולו אסור. אמר ר' יהודה: והלא מן התורה הוא אסור, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עד עצם היום הזה\",\u0004 ואין צורך בתקנה! משמע שר' יהודה חולק על רבן יוחנן בן זכאי!","ומשיבים: \u0003ר' יהודה הוא דקא טעי\u0004 \u0005[שטעה],\u0006 שכן \u0003הוא סבר\u0004 כי \u0003רבן יוחנן בן זכאי מדרבנן קאמר\u0004 \u0005[מדברי סופרים אמר]\u0006 את דבריו, שהתקין רבן יוחנן בן זכאי תקנה חדשה. \u0003ו\u0004אולם \u0003לא\u0004 \u0003היא,\u0004 שכן \u0003מדאורייתא קאמר\u0004 \u0005[מדין תורה הוא,\u0006 רבן יוחנן בן זכאי \u0005אמר]\u0006 את דבריו. ותוהים על הסבר זה: כיצד ניתן לומר שדברי רבן יוחנן בן זכאי הם דין תורה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"התקין\u0004 רבן יוחנן בן זכאי\" \u0003קתני\u0004 \u0005[שנינו]\u0006 במשנה, ולשון זו מורה שהריהי תקנת חכמים, ולא דין תורה. ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"התקין\"?\u0004 — ש\u0003דרש\u0004 רבן יוחנן בן זכאי את המקראות הללו לפני הרבים, והודיע הלכה לכל, ועמד \u0003והתקין\u0004 (תיקן) פירצה וקלקול שהיה.","בעקבות הדברים בזמן בו מותרת אכילת החדש בארץ ישראל, מביאים כיצד נהגו חכמים בזמן אכילת החדש בחוץ לארץ (בבבל). \u0003רב פפא ו\u0004כן \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אכלי\u0004 \u0005[היו אוכלים]\u0006 מן ה\u0003חדש\u0004 כבר \u0003באורתא דשיתסר נגהי שבסר\u0004 \u0005[בלילה,\u0006 בסוף היום \u0005של ששה עשר\u0006 בניסן, \u0005אור\u0006 ל\u0005שבעה\u0006 \u0003עשר\u0004 בניסן\u0005].\u0006 וטעמם: \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 כי איסור אכילת ה\u0003חדש בחוצה לארץ\u0004 אינו מן התורה, אלא רק מ\u0003דרבנן\u0004 \u0005[דברי סופרים],\u0006 \u0003ו\u0004כמו כן הריהם סבורים כי \u0003לספיקא\u0004 \u0005[לספק]\u0006 שמא אין זה יום ט\"ז בניסן אלא \u0003ט\"ו בניסן האסור באכילת החדש (משום הספק אם החודש שעבר, חודש אדר, היה מלא או חסר)\u0004 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006 ומשום כך, לאחר שעבר יום ט\"ז בניסן, יכלו לאכול כבר מן החדש.","\u0003ו\u0004אילו \u0003רבנן דבי\u0004 \u0005[החכמים שבבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי אכלו\u0004 מן התבואה החדשה רק \u0003בצפרא דשבסר\u0004 \u0005[בבוקר של שבעה עשר\u0006 בניסן\u0005],\u0006 וטעמם: \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 כי ה\u0003חדש בחוצה לארץ\u0004 אסור באכילה מ\u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכך בחוץ לארץ יש לחשוש אף לספק אם היום הוא \u0003ט\"ז בניסן או ט\"ו בניסן, ומשום כך אין לאכול בליל ט\"ז בניסן.\u0004","\u0003ו\u0004אולם הריהם סבורים כי \u0003רבן יוחנן בן זכאי\u0004 שאסר את יום ט\"ו כולו \u0003מדרבנן קאמר\u0004 \u0005[מדברי סופרים הוא אמר\u0006 כן\u0005],\u0006 אבל מן התורה מותרת אכילת החדש בזמן שאין בית המקדש קיים החל משהאיר המזרח, \u0003ו\u0004כן סבורים הם: \u0003כי תקין\u0004 \u0005[כאשר תיקן]\u0006 רבן יוחנן בן זכאי איסור זה — הרי זה דווקא ב\u0003יום הנף\u0004 עצמו (ביום ט\"ו בניסן), אבל \u0003ל\u0004ענין איסורו של יום ט\"ז בניסן משום \u0003ספיקא\u0004 \u0005[ספק]\u0006 (שמא הוא יום הנף, יום ט\"ו בניסן), בזה \u0003לא תקין\u0004 \u0005[לא תיקן]\u0006 רבן יוחנן. ומשום כך, לא אכלו עד בוקר יום י\"ז (מפני שספק היום נוגע לדין תורה, שאולי הוא יום ט\"ו בניסן האסור מן התורה), ואולם לאחר שכבר האיר פני מזרח של יום י\"ז בניסן, שאין ספק היום נוגע אלא לאיסור מדרבנן (תקנת רבן יוחנן בן זכאי) — הריהו מותר באכילה.","ובענין זה \u0003אמר רבינא,\u0004 כך \u0003אמרה לי אם\u0004 (אימי): \u0003אבוך לא הוה אכיל\u0004 \u0005[אביך לא היה אוכל]\u0006 מן ה\u0003חדש אלא באורתא דשבסר נגהי תמניסר\u0004 \u0005[בלילה של\u0006 יום \u0005שבעה עשר\u0006 בניסן, \u0005אור\u0006 ליום \u0005שמונה עשר\u0006 בניסן\u0005],\u0006 וטעם הדבר: משום \u0003דסבר לה\u0004 \u0005[שסבור היה]\u0006 שהלכה \u0003כר' יהודה\u0004 האומר שבזמן שאין בית המקדש קיים כל יום ט\"ז בניסן אסור מן התורה באכילת החדש, \u0003ו\u0004משום כך \u0003חייש לספיקא\u0004 \u0005[חושש לספק]\u0006 היום, שמא יום \u0003ט\"ז בניסן הריהו למעשה ט\"ו בניסן, ולכך לא אכל מן החדש אלא לאחר יום ט\"ז בניסן.\u0004","בזמן בית המקדש הנף \u0003העומר\u0004 במקדש, ביום ט\"ז בניסן, \u0003היה מתיר\u0004 את אכילת התבואה החדשה \u0003במדינה\u0004 (בכל המקומות שמחוץ למקדש). \u0003ו\u0004רק הקרבתם של \u0003שתי הלחם\u0004 בחג השבועות היא שהתירה את הקרבתן \u0003במקדש\u0004 של מנחות מן התבואה החדשה. שכן נאמר בשתי הלחם \"מנחה חדשה לה' בשבועותיכם\" (במדבר כח, כו), שהריהי החדשה (הראשונה) לכל המנחות הבאות מהתבואה החדשה. ועוד בדין הבאה למקדש מהתבואה החדשה: \u0003אין מביאין מנחות, וביכורים, ומנחת\u0004 נסכים הבאה עם קרבן \u0003בהמה קודם ל\u0004הקרבת ה\u0003עומר,\u0004 ו\u0003אם\u0004 עבר ו\u0003הביא\u0004 מנחה או ביכורים מהתבואה החדשה, לפני שהוקרב העומר — הרי קרבן זה \u0003פסול,\u0004 מה שאין כן כשהביא קודם לשתי הלחם שהמנחה כשרה. וכמו כן \u0003קודם ל\u0004הקרבת \u0003שתי הלחם לא יביא\u0004 מנחה וביכורים מהתבואה החדשה, אבל \u0003אם\u0004 עבר ו\u0003הביא\u0004 את אלה מהתבואה החדשה — קרבנו \u0003כשר.\u0004","שנינו במשנתנו שאם הביא מנחה מן התבואה החדשה קודם לעומר הרי זה פסול, ואולם אם הביא ממנה קודם לשתי הלחם הרי זה כשר. ובענין זה מספרים כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' טרפון וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 \u0003מה בין\u0004 הבאה \u0003קודם לעומר\u0004 שהוא פסול, \u0003ל\u0004הבאה \u0003קודם\u0004 ל\u0003שתי הלחם,\u0004 שהוא כשר?","\u0003אמר לפניו יהודה בר נחמיה: לא,\u0004 אין מקום לשאלה זו. שכן \u0003אם אמרת\u0004 במנחה שהובאה מן החדש \u0003קודם לעומר\u0004 שהיא פסולה — \u0003שכן לא הותר\u0004 איסור חדש \u0003מכללו\u0004 אפילו \u0003אצל הדיוט. תאמר\u0004 לפסול את המנחה שהובאה מהחדש \u0003קודם לשתי הלחם, שהותר מכללו אצל הדיוט?\u0004 שהרי מותרת כבר אכילת החדש לאדם מישראל.","\u0003שתק ר' טרפון,\u0004 שלא מצא דרך לדחות את דבריו. \u0003צהבו\u0004 (האירו) \u0003פניו של ר' יהודה בן נחמיה,\u0004 שהצליח להביא הוכחה שר' טרפון לא ידע. \u0003אמר לו ר' עקיבא: יהודה, צהבו פניך שהשבת את זקן, תמהני אם תאריך ימים. אמר ר' יהודה בר' אלעאי: אותו הפרק\u0004 (זמן) שבו אירע הדבר, \u0003פרס\u0004 (מחצית החודש, שבועיים טרם) \u0003הפסח היה. כשעליתי לעצרת\u0004 (חג השבועות) שוב ללמוד בישיבה \u0003שאלתי אחריו: יהודה בן נחמיה היכן הוא? ואמרו לי: נפטר והלך לו,\u0004 שנתקיימו בו דבריו של ר' עקיבא.","ובעקבות דברי יהודה בן נחמיה \u0003אמר רב נחמן בר יצחק: לדברי יהודה בן נחמיה,\u0004 המסביר שאין לפסול את המנחות הבאות מן החדש לאחר שהוקרב העומר, משום שכבר הותרו מכללן אצל הדיוט, יש לומר שאף \u0003נסכים ביכורים\u0004 (נסכי יין הבאים מן החדש) \u0003שהקריבם קודם ל\u0004הבאת ה\u0003עומר\u0004 — הריהם \u0003כשירין\u0004 שכן לא נאסר לאכילת הדיוט מן החדש קודם לעומר אלא התבואה, ואילו היין לא נאסר להדיוט אלא אסור למקדש בלבד (עד להבאת שתי הלחם). ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, ומה צורך להשמיענו זאת?!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי היה מקום לומר כי חמור דין נסכי היין הבאים מן החדש לאחר \u0005הבאת העומר ממנחת תבואה הבאה מהחדש לאחר הבאת העומר, שכן דווקא\u0006 \u0003התם\u0004 \u0005[שם,\u0006 במנחת תבואה הבאה מהחדש לאחר הבאת העומר\u0005]\u0006 — \u0003הוא\u0004 שיש מקום להכשיר, משום ש\u0003הותר מכללו אצל הדיוט\u0004 דבר שהיה אסור לפני כן. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בנסכי יין הבאים מן החדש לאחר הבאת העומר\u0005]\u0006 ש\u0003לא הותר\u0004 הדבר האסור \u0003מכללו,\u0004 שהרי עדיין אסור היין למקדש — \u0003לא\u0004 יהיה כשר. על כן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 רב נחמן בר יצחק, \u0005משמיע לנו]\u0006 ש\u0003כל שכן הכא\u0004 \u0005[כאן,\u0006 בנסכי יין\u0005]\u0006 שהם כשרים, וטעם הדבר: \u0003שהרי\u0004 \u0003לא איתסר\u0004 \u0005[לא נאסר]\u0006 \u0003כלל\u0004 להדיוט.","ומביאים עתה את המלים הבאות: \u0003סדר. הנצא. גלי. פיל.\u0004 כ\u0003סימן\u0004 זכרון לארבע בעיות שתידונה להלן (\"סדר\" — האם היתר החדש למקדש על ידי שתי הלחם הריהו דווקא כשבאו כסדרם. \"הנצה\" — האם הנצת פרי האילן קודם להבאת שתי הלחם היא המתירתו או שמא חנטתו. \"גלי\" — האם ניתן להביא מנחות מחיטים שהיו בגללי בקר וחזרו והצמיחו מהן חיטים חדשות. \"פיל\" — מה דינו של סל שבלעו פיל וחזר והקיאו). שנינו במשנתנו איסור הבאת המנחות מן התבואה החדשה לפני הבאת העומר ולפני הבאת שתי הלחם. ובענין זה מביאים מה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: שתי הלחם מהו\u0004 דינם לענין \u0003שיתירו\u0004 תבואה חדשה למקדש כ\u0003שלא\u0004 היה היתר החדש (להדיוט) על ידי העומר והיתר החדש (למקדש) על ידי שתי הלחם \u0003כסדרן\u0004 הראוי, אלא שקדם היתר החדש שעל ידי שתי הלחם להיתר החדש שעל ידי העומר.","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 — \u0003כגון דזרעינהו\u0004 \u0005[שזרע אותם,\u0006 את החיטים מהן מובאת המנחה\u0005]\u0006 בזמן ש\u0003בין\u0004 הבאת \u0003העומר ל\u0004בין הבאת \u0003שתי הלחם, ו\u0004באופן זה נמצא ש\u0003חליף עלייהו\u0004 \u0005[חלף עליהן]\u0006 זמן היתר החדש שעל ידי \u0003שתי הלחם\u0004 בעצרת בשנה זו, \u0003ו\u0004לאחר מכן חלף עליהם זמן היתר החדש שעל ידי ה\u0003עומר\u0004 בפסח בשנה הבאה. ומעתה השאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינם של חיטים אלה להקרבה לאחר הבאת העומר בשנה הבאה (ולפני הבאת שתי הלחם). וצדדי השאלה: האם רק כששתי הבאות אלה, של העומר ושל שתי הלחם, הינן \u0003כסדרן שריין\u0004 \u0005[מתירות]\u0006 את התבואה החדשה להקרבה, ואולם כשהן באות \u0003שלא כסדרן, לא שריין\u0004 \u0005[לא מתירות].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 אף כששתי הבאות אלה היו \u0003שלא כסדרן נמי שריין\u0004 \u0005[גם כן מתירות]\u0006 את \u0003הקרבת התבואה החדשה.\u0004","\u0003אמר רבה: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: מה שנאמר \u0003\"ואם תקריב מנחת בכורים\u0004 לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (ויקרא ב, יד) — \u0003במנחת העומר\u0004 הבאה בפסח \u0003הכתוב מדבר. מהיכן,\u0004 מאיזה מין ממיני הדגן \u0003באה\u0004 מנחה זו — \u0003מן השעורין.\u0004 ודנים בדבר: \u0003אתה אומר\u0004 שמנחת העומר באה \u0003מן השעורין, או אינו אלא\u0004 שבאה \u0003מן החיטין?\u0004","\u0003ר' אליעזר אומר:\u0004 אין לומר כך, ונלמד זאת מגזירה שווה. \u0003נאמר \"אביב\" ב\u0004מכות \u0003מצרים,\u0004 במכת ברד (\"...והשעורה נוכתה כי השעורה אביב\". שמות ט, לא). \u0003ו\u0004כן \u0003נאמר \"אביב\"\u0004 בציווי הנאמר \u0003לדורות\u0004 (בהבאת מנחת ביכורים, \"אביב קלוי באש\"). ומעתה נאמר: \u0003מה \"אביב\" האמור במצרים\u0004 — הריהו \u0003שעורין\u0004 דווקא ולא חיטים (שכן נאמר במפורש במכת ברד, בפסוק שלאחר מכן \"והחטה והכוסמת לא נוכו כי אפילות הנה\". שם לב), \u0003אף \"אביב\" האמור לדורות\u0004 — הריהו \u0003שעורין\u0004 ולא חיטים.","\u0003ור' עקיבא אומר\u0004 ראיה אחרת, שכן \u0003מצינו\u0004 (מוצאים אנו) בדינו של אדם \u0003יחיד\u0004 מישראל \u0003ש\u0004הוא \u0003מביא חובתו\u0004 למנחה (כשחטא העני בשבועת העדות או בשבועת ביטוי או בטומאת מקדש וקדשיו) \u0003מן החיטין\u0004 (ככתוב בו \"עשירית האיפה סולת\". שם ה, יא) \u0003ו\u0004הריהו מביא גם מנחה \u0003ל\u0004\u0003חובתו מן השעורין\u0004 (\"מנחת חוטא\", במנחת הסוטה, ככתוב בה \"עשירית האיפה קמח שעורים\". במדבר ה, טו).","\u0003ו\u0004כן מוצאים אנו כי \u0003ב\u0004\u0003ציבור ש\u0004הם \u0003מביאין\u0004 מנחת \u0003חובתן מן החיטין\u0004 (בשתי הלחם הקרב בעצרת, ככתוב בהם \"לחם תנופה שתים שני עשרונים סולת תהיינה\". ויקרא כג, יז). ומעתה נקיש: מה יחיד מביא מנחת חובתו מן השעורים וכן מן החיטים — אף ציבור \u0003מביאין חובתן\u0004 גם \u0003מן השעורין\u0004 וגם מן החיטים. \u0003ואם אתה אומר\u0004 שמנחת ביכורים (שהיא מנחת חובה של ציבור) \u0003בא מן החיטין,\u0004 ולא מן השעורים — אם כן \u0003לא מצינו\u0004 ב\u0003ציבור שמביא\u0004 מנחת \u0003חובתו מן השעורין!\u0004 אלא ודאי שמנחת העומר באה מהשעורים.","ועוד \u0003אמר ר' עקיבא\u0004 \u0003דבר אחר\u0004 (אופן נוסף) להוכיח כי מנחת העומר באה מהשעורים: שכן \u0003אם אתה אומר\u0004 שה\u0003עומר בא\u0004 דווקא \u0003מן החיטין\u0004 ולא מן השעורים — אם כן מעתה \u0003אין שתי הלחם\u0004 הבאים בחג השבועות מן החיטים נקראים \u0003\"בכורים\",\u0004 שהרי קדמם העומר, והרי אמרה תורה בחג השבועות \"וביום הביכורים בהקריבכם מנחה חדשה לה' בשבועותיכם\" (במדבר כח, כו), אלא ודאי הריהו בא מן השעורים.","\u0003ו\u0004מתוך דברי הברייתא הללו אומר רבה כי יש פתרון לבעייתו של רמי בר חמא: \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לסברה שאף \u0003שתי הלחם\u0004 שבאו \u0003שלא כסדרן שריין\u0004 \u0005[מתירות]\u0006 את התבואה החדשה, אפשר לפרוך את ראייתו השניה של ר' עקיבא. שלפי צד זה \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה,\u0006 אפשרות שכזו\u0005],\u0006 במקרה ש\u0003מקריב\u0004 הציבור בשנה זו בפסח \u0003עומר מהנך דאשרוש\u0004 \u0005[מאלה\u0006 החיטים \u0005שהשרישו]\u0006 בשנה שעברה \u0003קודם ל\u0004זמן הבאת \u0003שתי הלחם ובתר\u0004 \u0005[ואחר]\u0006 הבאת \u0003העומר\u0004 של \u0003אשתקד\u0004 (שנה שעברה).","ומביא הציבור עוד בשנה זו במנחת \u0003שתי הלחם מהנך דאשרוש\u0004 \u0005[מאלה\u0006 החיטים \u0005שהשרישו]\u0006 \u0003קודם לעומר דהשתא\u0004 \u0005[של השנה],\u0006 \u0003ובתר\u0004 \u0005[ואחר]\u0006 הבאת \u0003שתי הלחם\u0004 של \u0003אשתקד.\u0004 והרי באופן זה שתי הלחם הבאים בשנה זו מן החיטים של שנה זו ראויים להיקרא \"ביכורים\", אף שגם מנחת העומר הובאה מחיטים, ואולם היו אלה חיטים של שנה שעברה! ומכאן פתרון לבעיית רמי בר חמא, שאין שתי הלחם הבאים שלא כסדרן מתירים את התבואה למקדש.","ודוחים את דברי רבה: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006"],["כי מה שנאמר בתורה בחג השבועות \u0003\"בכורים\"\u0004 — \u0003ל\u0004ענין \u0003פירא קא אמרינן\u0004 \u0005[הפירות,\u0006 החיטים הבאות בשתי הלחם\u0005, אנו אומרים],\u0006 כלומר, שהחיטים הבאות בו למנחה הן החיטים הראשונות מתבואת שנה זו? אין זה כך, אלא הכוונה שיהיו ביכורים \u0003ל\u0004ענין \u0003ה\u0004\u0003מזבח קא אמרינן\u0004 \u0005[אנו אומרים],\u0006 שבחג השבועות תהיה הקרבת המנחה הראשונה הבאה מן התבואה החדשה, ולא תהא קרבה לפני כן מנחה הבאה מן התבואה החדשה, \u0003ו\u0004אילו לפי אופן זה שהציע רבה \u0003הא אכיל לה\u0004 \u0005[הרי\u0006 כבר \u0005נאכל לו,\u0006 הוקרב\u0005]\u0006 ב\u0003מזבח מפירי דהא שתא\u0004 \u0005[מפירות של שנה זו]\u0006 בהבאת החיטים בעומר. ונדחתה איפוא ראייתו של רבה, ונשארה במקומה בעייתו של רמי בר חמא.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא\u0004 שאלה בענין היתר החדש שעל ידי שתי הלחם: פירות האילן של היבול החדש משנה זו, שהם מותרים לאכילת הדיוט (שאין דין חדש להדיוט אלא בתבואת הדגן בלבד), ואולם לא הותרו למקדש אלא לאחר הבאת \u0003שתי הלחם\u0004 בעצרת. ומעתה מבררים באיזה שלב התפתחות צריך להיות האילן בשעת הבאת שתי הלחם כדי שפירותיו יהיו מותרים, האם כבר בשלב ה\u0003הנצה\u0004 שלו \u0003שריא\u0004 \u0005[מתירה]\u0006 אותו הבאת שתי הלחם, \u0003או\u0004 שמא מאוחר יותר ורק מזמן שהוא בשלב ה\u0003חנטה\u0004 שלו והלאה, \u0003שרייה\u0004 \u0005[מתירה]\u0006 אותו הבאת שתי הלחם? ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003הנצה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003חנטה? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה \u0003ל\u0004\u0003הנצה דפירא\u0004 \u0005[של הפרי]\u0006 \u0003ו\u0004ל\u0003חנטה דפירא\u0004 \u0005[של הפרי]\u0006 — אין לומר כן, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 בהיתר התבואה החדשה להקרבה במקדש שעל ידי הבאת שתי הלחם למדנו (להלן מנחות ע,א) כי כאשר התבואה היתה בזמן הבאת שתי הלחם עדיין בשלב ה\u0003השרשה\u0004 שלה, \u0003שריא\u0004 \u0005[מתירה]\u0006 הבאת שתי הלחם, ואם כן כאשר פרי האילן בזמן הבאת שתי הלחם בשלב ה\u0003הנצה ו\u0004ה\u0003חנטה\u0004 שלו \u0003מיבעיא\u0004 \u0005[נצרך]\u0006 להישאל מה דינו, והרי ברור שהוא מותר.","\u0003אלא\u0004 הכוונה היא ל\u0003הנצה\u0004 של \u0003עלה\u0004 האילן \u0003ו\u0004ל\u0003חנטה\u0004 של \u0003עלה\u0004 האילן שהם בשלב מוקדם בהרבה מהנצה וחנטת הפרי. והשאלה היא: \u0003מי הוי כי\u0004 \u0005[האם הריהם כמו]\u0006 \u0003השרשה\u0004 בתבואה, המותרת על ידי הבאת שתי הלחם \u0003או לא?\u0004 שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד שאלה בדין היתר החדש על ידי העומר \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא בר רב חנן: חטין שזרען בקרקע,\u0004 האם הבאת ה\u0003עומר מתירן\u0004 מאיסור חדש, \u0003או אין\u0004 הבאת ה\u0003עומר מתירן?\u0004 ומקשים על רבא בר רב חנן: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דאשרוש\u0004 \u0005[אם\u0006 מדובר \u0005ש\u0006כבר \u0005השרישו]\u0006 החיטים הללו באדמה לפני שהובא העומר — הרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה (להלן מנחות ע,א) שאם השרישו התבואות לפני הבאת העומר, מותר לקוצרן בעת שיבשילו, והרי פירותיהם מותרים באכילה! ו\u0003אי\u0004 \u0005[אם]\u0006 המדובר כאשר עדיין \u0003לא אשרוש\u0004 \u0005[לא השרישו]\u0006 החיטים הללו בזמן הבאת העומר — אף בזאת כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה זו שבאופן זה אין העומר מתירם.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003אם השרישו\u0004 התבואות \u0003קודם לעומר\u0004 — ה\u0003עומר מתירן, ואם לאו\u0004 \u0005[לא]\u0006 — הריהם \u0003אסורין עד שיבא\u0004 ה\u0003עומר הבא.\u0004 ונמצא איפוא שאין מקום לבעיה זו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 בעיה זו אלא באופן הבא, \u0003דחצדינהו וזרעינהו\u0004 \u0005[שקצר אותן,\u0006 את החיטים הללו, וחזר \u0005וזרע אותן\u0006 שוב\u0005]\u0006 \u0003קודם ל\u0004הבאת ה\u0003עומר, ואתא\u0004 \u0005[ובא]\u0006 ה\u0003עומר וחליף עלייהו\u0004 \u0005[וחלף עליהן],\u0006 \u0003וקא מיבעיא ליה\u0004 \u0005[והיא\u0006 השאלה \u0005שנשאלה לו]:\u0006 \u0003מהו\u0004 דינן של החיטים הללו \u0003לנקוטי ומיכל מינייהו\u0004 \u0005[לקחתן ולאכול מהן,\u0006 מהחיטים הללו שבאדמה\u0005]?\u0006 ועיקרה של השאלה: כיצד יש להתייחס לחיטים הללו המונחים עתה בקרקע. וצדדי השאלה: האם נאמר שהריהן כשאר חיטים קצורות \u0003ו\u0004\u0003כמאן דשדייא בכדא דמיא, ושרינהו\u0004 \u0005[כמי שמוטלות בכד\u0006 הן \u0005נחשבות, והתירן]\u0006 ה\u0003עומר,\u0004 כדרך שהוא מתיר את החיטים הנמצאות במקומות איחסון אחרים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי בזריעתו את החיטים הללו בקרקע הרי זה נחשב כמי ש\u0003בטיל להו לגבי ארעא\u0004 \u0005[ביטל אותן אצל הקרקע],\u0006 ואין העומר מתיר את התבואות הזרועות בקרקע.","וכיוצא בדבר, יש עוד לשאול בדינן של החיטים הללו הנתונות עתה בקרקע, שאין זה ברור אם כמטלטלין הן נחשבות או כקרקע, לענין דין אונאה בהן: האם \u0003יש להן\u0004 דין \u0003אונאה\u0004 כדברים המטלטלים (שאם המחיר שניתן בעדם היה גבוה או נמוך בשישית ממחירם — נקנה המקח, ואולם המאנה חייב להחזיר למתאנה את דמי האונאה. ואם היה המחיר שניתן בעד המקח גבוה או נמוך ביותר משישית מערכם — המקח בטל), \u0003או אין להן\u0004 דין \u0003אונאה,\u0004 כדין הקרקעות?","ומקשים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 מוכר החיטים הללו לקונה אותן: \u0003שדאי\u0004 \u0005[הטלתי,\u0006 זרעתי\u0005]\u0006 \u0003בה\u0004 בקרקע זו שבה הן מונחות עתה \u0003שיתא\u0004 \u0005[שש]\u0006 מידות מסויימות של חיטים, \u0003ואתו סהדי ואמרי\u0004 \u0005[ובאו עדים\u0006 \u0003ואמרו]\u0004 ש\u0003לא שדא\u0004 \u0005[לא הטיל]\u0006 \u0003בה אלא חמשה\u0004 מידות אלה של חיטים, והרי זו איפוא אונאה בשיעור שישית — \u0003ו\u0004אולם באופן זה \u0003האמר\u0004 \u0005[הרי\u0006 כבר \u0005אמר]\u0006 \u0003רבא: כל דבר\u0004 אונאה \u0003ש\u0004נעשתה ב\u0003מדה ושבמשקל ושבמנין\u0004 (שלא ניתנו המידה או המשקל או המנין המוסכם בין הקונה והמוכר), \u0003אפילו\u0004 אם היה ההפרש בין מה שהוסכם לבין מה שניתן \u0003פחות מכדי\u0004 דין \u0003אונאה\u0004 (שהוא שישית) \u0003חוזר\u0004 בו הצד המתאנה מן המקח!","\u0003אלא\u0004 יש לומר שכך היא הבעיה בדין אונאה בחיטים הללו: ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר את החיטים לקונה אותן: \u0003שדאי\u0004 \u0005[הטלתי,\u0006 זרעתי\u0005]\u0006 \u0003בה\u0004 בקרקע זו כמות גרעיני חיטה \u0003כדבעי\u0004 \u0005[כמו שצריך,\u0006 כראוי\u0005]\u0006 \u0003לה,\u0004 ולא נקב במידה מסויימת, \u0003ואתו סהדי ואמרי\u0004 \u0005[ובאו עדים ואמרו]\u0006 \u0003דלא שדא\u0004 \u0005[שלא הטיל]\u0006 \u0003בה כדבעי\u0004 \u0005[כמו שצריך]\u0006 \u0003לה.\u0004 וכאן יש לשאול: האם במקרה כזה \u0003יש להן אונאה,\u0004 כדברים המטלטלין, \u0003דכמאן דשדייא בכדא דמיא\u0004 \u0005[שכמו שמוטלות בכד\u0006 הן \u0005נחשבות],\u0006 \u0003ויש להן אונאה. או דלמא\u0004 \u0005[שמא],\u0006 בזריעתו אותן בקרקע, \u0003בטיל להו לגבי ארעא\u0004 \u0005[ביטל אותן אצל הקרקע],\u0006 וכקרקע הן נחשבות, ואין להם אונאה כקרקע?","כיוצא בדבר יש לשאול בדינן של החיטים הללו: האם החיטים הללו נחשבות כמטלטלין ו\u0003נשבעין עליהן,\u0004 כדרך שנשבעים על מטלטלין, \u0003או\u0004 ש\u0003אין נשבעין עליהן,\u0004 כדרך שאין נשבעים על הקרקעות. וצדדי השאלה הריהם כעין אלה שנאמרו למעלה: האם \u0003כדשדייא בכדא דמיא\u0004 \u0005[כמו שמוטלות בכד\u0006 הן \u0005נחשבות],\u0006 \u0003וכמטלטלי דמו\u0004 \u0005[וכמטלטלים\u0006 הן \u0005נחשבות],\u0006 \u0003ו\u0004משום כך אף \u0003נשבעין עליהן. או דלמא\u0004 \u0005[שמא]\u0006 בזריעתו אותן בקרקע, \u0003בטיל להו אגב ארעא\u0004 \u0005[ביטל אותן אצל הקרקע],\u0006 \u0003וכמקרקעי דמו\u0004 \u0005[וכקרקעות\u0006 הן \u0005נחשבות],\u0006 \u0003ואין נשבעין עליהן?\u0004 אף שאלות אלה לא נפתרו, ו\u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","ועוד שאלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: חטין ש\u0004נמצאים \u0003ב\u0004תוך \u0003גללי בקר\u0004 (שפלטתן הבהמה בתוך צואתה), \u0003ו\u0004כן \u0003שעורין ש\u0004נמצאים \u0003ב\u0004תוך \u0003גללי בהמה, מהו\u0004 דינם? וכיון שלא הסביר רמי בר חמא במה עוסקת בעייתו זו שואלים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין הוא שואל? ומציעים: \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששאל אם חיטים או שעורים אלה נחשבים בכלל אוכלים לענין \u0003לטמויי\u0004 \u0005[שייטמאו]\u0006 ב\u0003טומאת אוכלין\u0004 אם נגע בהן דבר המטמא אוכלים, אין מקום לבעיה זו, שהרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 בתוספתא: \u0003חטין\u0004 שנמצאות \u0003ברעי\u0004 (גללי) \u0003בקר ו\u0004כן \u0003שעורין\u0004 שנמצאות \u0003בגללי בהמה,\u0004 אם בעליהן רק \u0003חישב עליהן\u0004 להשתמש בהן \u0003לאכילה,\u0004 ועדיין לא עשה כל מעשה המבטא את מחשבתו זאת — \u0003אין מטמא טומאת אוכלין,\u0004 שאין מחשבה מספיקה כדי להוציאן מביטולן בהיותן בגללים. ואולם אם \u0003לקטן\u0004 מתוך הגללים \u0003ל\u0004צורך \u0003אכילה\u0004 — החיטים והשעורים הללו \u0003מטמא טומאת אוכלין!\u0004","\u0003אלא\u0004 אם תאמר שבעייתו של רמי בר חמא היא לענין לקיחתן של החיטים והשעורים הללו \u0003למנחות\u0004 — אף בזה אין מקום לבעיה, \u0003שהרי\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא ש\u0003לא\u0004 ניתן לעשות כן, כמו שנאמר בתוכחת הנביא מלאכי את המביאים למקדש מן הדברים המאוסים, ומבזים את שם ה': \"...לכם הכהנים בוזי שמי ואמרתם במה בזינו את שמך. מגישים על מזבחי לחם מגואל... וכי תגישו עור לזבוח אין רע וכי תגישו פסח וחולה אין רע \u0003הקריבהו נא לפחתך\u0004 \u0003הירצך או הישא פניך...\"\u0004(מלאכי א, ז—ח)!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 בעייתו של רמי בר חמא אלא באופן מסויים זה, \u0003דנקטינהו\u0004 \u0005[שאסף אותן]\u0006 בתחילה מתוך הגללים, \u0003ו\u0004לאחר מכן \u0003זרעינהו\u0004 \u0005[זרע אותן]\u0006 באדמה, ועמד וקצרן, \u0003וקא בעי לאיתויי\u0004 \u0005[ו\u0006עתה \u0005הוא רוצה להביא]\u0006 \u0003מנחות מינייהו\u0004 \u0005[מהן],\u0006 והשאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי הבעיה: האם עיקר פסולן בתחילה של החיטים והשעורים הללו שנלקטו מתוך הגללים, \u0003משום דמאיסותא\u0004 \u0005[של מאיסות]\u0006 \u0003הוא\u0004 זה, \u0003ו\u0004מעתה יש מקום לומר כי \u0003כיון דזרעינהו אזדא למאיסותייהו\u0004 \u0005[כיון שזרע אותו הלכה,\u0006 נעלמה, \u0005מאיסותן],\u0006 ותהיינה מותרות למנחה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי עיקר פסולן בתחילה \u0003משום כחישותא\u0004 \u0005[רזון]\u0006 \u0003הוא,\u0004 שבזמן שהיו במעי הבקר איבדו את מלאותן ובריאותן, \u0003ו\u0004מעתה יש מקום \u0003לומר כי אף\u0004 \u0003השתא\u0004 \u0005[עכשיו],\u0006 לאחר שעמד וזרען וצמחו מחדש, \u0003נמי\u0004 \u0005[גם כן]\u0006 התבואה הגדלה מגרגרים אלה היא \u0003כחושה,\u0004 ולכך היא פסולה למנחה. ומסכמים כי אף שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד שאלה דומה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: פיל שבלע כפיפה מצרית\u0004 (סל העשוי מנצרים) \u0003והקיאה\u0004 (פלט אותה) \u0003דרך בית הרעי\u0004 (פי הטבעת), \u0003מהו\u0004 דינה של כפיפה זו? ואף בבעיה זו מבררים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין הוא שואל?","ומציעים: \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר בכפיפה שהיתה טמאה, והשאלה היא \u0003למבטל\u0004 \u0005[ל\u0006ענין \u0005שתיבטל]\u0006 \u0003טומאתה\u0004 על ידי הבליעה שבלעה הפיל — אין מקום לשאלה זו, שהרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה: \u0003כל הכלים יורדין\u0004 (נכנסים) \u0003לידי טומאתן\u0004 (שיהיו ראויים לקבלת טומאה) אף \u0003במחשבה\u0004 שחשב עליהם הבעלים להשתמש בהם. \u0003ו\u0004אולם \u0003אין\u0004 הם \u0003עולין\u0004 (יוצאים) \u0003מטומאתן\u0004 (מקבלת טומאה) \u0003אלא בשינוי מעשה.\u0004 ואם לא היה שינוי מעשה בכפיפה זו, והכפיפה נשארה בעינה כפי שהיתה לפני שנבלעה — הריהי עדיין טמאה!","ומסבירים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 השאלה של רמי בר חמא אלא באופן שהפיל \u0003בלע הוצין\u0004 (עלים של דקל), ולא השתנו העלים הללו בתוך מעיו של הפיל, שלא לעסם. ולאחר מכן, כשהוציאם מתוך מעיו עמדו \u0003ועבדינהו\u0004 \u0005[ועשו\u0006 את \u0005אותם]\u0006 עלים ל\u0003כפיפה מצרית.\u0004 ואלו צדדי השאלה: \u0003מי\u0004 \u0005[האם]\u0006 הבליעה שבלע הפיל את העלים \u0003הוה\u0004 \u0005[הינה]\u0006 נחשבת \u0003כ\u0004\u0003עיכול\u0004 של העלים, והריהם נחשבים כגללים, ומעתה הכפיפה שנעשתה מהם \u0003הוה ליה\u0004 \u0005[הרי היא]\u0006"],["\u0003ככלי\u0004 שנעשה מ\u0003גללים\u0004 ו\u0003ככלי\u0004 הנעשה מ\u0003אדמה, ו\u0004כלים אלה \u0003אין\u0004 \u0003מקבלין טומאה.\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כלי אבנים וכלי גללים וכלי אדמה\u0004 — \u0003אין מקבלין טומאה\u0004 כלל, \u0003לא מדברי תורה ו\u0004אף \u0003לא מדברי סופרים.\u0004 ואף כפיפה זו אינה מקבלת טומאה ככלי גללים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי הבליעה שבלע הפיל את עלי הדקל, \u0003לא הוי\u0004 \u0005[לא נחשבת]\u0006 \u0003עיכול,\u0004 שהרי חזר ופלטם כשהם שלמים וראויים למלאכתם, ותהא הכפיפה שנעשתה מהם מקבלת טומאה, כשאר כלי עץ.","ומציעים: \u0003תפשוט ליה מהא\u0004 \u0005[תפתור לו,\u0006 לרמי בר חמא את בעייתו \u0005מ\u0006הלכה \u0005זו],\u0006 ש\u0003אמר עולא משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בר יהוצדק: מעשה\u0004 היה \u0003ובלעו זאבים שני תינוקות בעבר הירדן,\u0004 ולאחר מכן חזרו ופלטו אותם כשהם מתים דרך בית הרעי. \u0003ובא מעשה\u0004 זה כשאלה הלכתית \u0003לפני חכמים\u0004 מה דינם של התינוקות הללו לענין טומאת המת, האם נטמאו העוסקים בהם כעוסקים בשאר מתים. \u0003וטהרו\u0004 חכמים \u0003את הבשר\u0004 של התינוקות מלטמא בטומאת מת, שאין זה עוד כבשר אדם אלא כגללי הזאבים, שכן נחשבת בליעתם של התינוקות כעיכולם. ומכאן ראיה לענין הכפיפה, שנחשבת בליעת עלי הדקל כעיכולם!","ודוחים: אין להביא ראיה משם, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 הוא דינו של ה\u0003בשר\u0004 שנחשב כמעוכל, משום \u0003דרכיך\u0004 \u0005[שרך]\u0006 הוא. מה שאין כן עלי הדקל (שהם קשים מבשר) שנבלעו, יש מקום לומר שאין הם נחשבים בכך כמעוכלים. ומציעים עוד: \u0003ולפשוט מסיפא\u0004 \u0005[ושיפתור\u0006 את הבעיה \u0005מ\u0006מה ששנינו ב\u0005סוף]\u0006 דבריו של ר' שמעון בר יהוצדק: \u0003וטמאו\u0004 חכמים \u0003את העצמות,\u0004 שהריהם בכלל טומאת מת. הרי מכאן ראיה שאין הבליעה נחשבת כעיכול, והעצמות אינן נחשבות כגללי הזאבים, ומכאן ראיה לענין עלי הדקל שנבלעו שאף הם אינם נחשבים כמעוכלים! ודוחים: גם מכאן אין להוכיח, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 הוא דין \u0003ה\u0004\u0003עצמות, דאקושי טפי\u0004 \u0005[ש\u0006הן \u0005קשות ביותר],\u0006 ומשום כך אין הן נחשבות כמעוכלות, מה שאין כן עלי הדקל שהם רכים מן העצמות, יש מקום לומר שנחשבים הם כמעוכלים. ולא נפתרה גם בעיה זו.","וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: חיטין שירדו\u0004 לארץ \u0003בעבים\u0004 (עננים), \u0003מהו\u0004 דינם? ושואלים: \u0003למאי\u0004 \u0005[למה]?\u0006 לאיזה ענין שאל ר' זירא? ומציעים: \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהשאלה היא האם מותר \u0003ל\u0004הביא מהן \u0003מנחות\u0004 למקדש — אין זו שאלה כלל, שהרי \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יהיו חיטים אלה כשרות למנחה?! \u0003אלא\u0004 לענין ההיתר \u0003ל\u0004הביא מחיטים אלה את קרבן \u0003שתי הלחם, מאי\u0004 \u0005[מה]\u0006 הדין?","וצדדי השאלה: האם \u0003\"ממושבתיכם\"\u0004 (\"ממושבותיכם תביאו לחם תנופה שתים...\". ויקרא כג, יז) ש\u0003אמר רחמנא\u0004 \u0005[\u0006ש\u0005אמרה התורה]\u0006 בלשון המורה על מיעוט הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא\u0006 מכלל הכשרים \u0005לשתי הלחם\u0006\u0005]\u0006 את החיטים שבאו מ\u0003חוצה לארץ,\u0004 ש\u0003לא\u0004 מביאים מהן לשתי הלחם, \u0003אבל\u0004 החיטים שלא באו מחוצה לארץ, הגם שלא באו מאדמת ארץ ישראל, כגון אלה שבאו מן ה\u0003עבים\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי \u0005נחשב\u0006 הדבר\u0005].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי הכתוב \u0003\"ממושבתיכם\"\u0004 בא להורות: \u0003דווקא\u0004 (רק) מחיטים הבאים ממקומות שבארץ ישראל מביאים לשתי הלחם, ואין מביאים מחיטים אחרות, \u0003ואפילו\u0004 החיטים הבאות מן ה\u0003עבים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 מביאים מהן?","ותוהים על עצם השאלה: \u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש כדבר כזה]\u0006 שהחיטים יורדות מן העבים? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כ\u0004דרך שמסופר באדם ששמו \u0003עדי טייעא\u0004 \u0005[הערבי],\u0006 שקרה ו\u0003נחיתא ליה\u0004 \u0005[ירד לו]\u0006 מן השמים \u0003רום כיזבא חיטי בתלתא פרסי\u0004 \u0005[כגובה טפח חיטים ב\u0006מרחב של \u0005שלוש פרסאות].\u0006","וכמו כן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' שמעון בן פזי: שיבולת שהביאה\u0004 (שגדלה) כדי \u0003שליש\u0004 גידולה \u0003קודם לעומר, ועקרה\u0004 קודם להבאת העומר, והובא העומר, ולאחר מכן חזר \u0003ושתלה\u0004 שוב \u0003לאחר\u0004 הבאת \u0003העומר, והוסיפה\u0004 וגדלה השיבולת, \u0003מהו\u0004 דינה לענין שתותר אכילתה על ידי העומר שהובא. וצדדי השאלה: \u0003האם\u0004 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003עיקר אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003ו\u0004לכך אף שיבולת זו \u0003שרייה\u0004 \u0005[התיר אותה]\u0006 ה\u0003עומר.\u0004 שהרי עיקרה של השיבולת הותר על ידי הנפת העומר, ואחר עיקר זה אנו הולכים, ולא אחר התוספת שנוספה בשיבולת זו לאחר הבאת \u0003העומר.\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003תוספת אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003ו\u0004לכך תהא אסורה באכילה (משום חדש) \u0003עד שיבא\u0004 ה\u0003עומר הבא\u0004 בשנה הבאה?","ומציעים: \u0003תפשוט ליה מהא\u0004 \u0005[תפתור לו,\u0006 לר' שמעון בן פזי את בעייתו \u0005מ\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' אבהו,\u0004 \u0003אמר ר' יוחנן:\u0004 גפן \u0003ילדה\u0004 (צעירה) שעדיין היא ערלה (בשלוש השנים הראשונות לנטיעתה), ופירותיה אסורים, \u0003שסבכה\u0004 (הרכיב אותה) \u0003ב\u0004גפן \u0003זקנה\u0004 לאחר שנות ערלה שפירותיה מותרים באכילה, \u0003ו\u0004היו \u0003בה\u0004 בגפן הצעירה \u0003פירות. אפילו הוסיף\u0004 הפרי שבגפן הצעירה היונקת עתה מהגפן הישנה וגדל \u0003ב\u0004שיעור פי \u0003מאתים\u0004 ממה שהיה בה מקודם לכן (שהוא השיעור בו בטלים איסורי הערלה וכלאי הכרם בהיתר) — בכל זאת הפרי \u0003אסור,\u0004 שאין הגידולים המותרים מבטלים את העיקר האסור, שהתוספת הולכת אחר העיקר.","\u0003ו\u0004כיוצא בדבר \u0003אמר ר' שמואל בר נחמני, אמר ר' יונתן\u0004 לענין איסור כלאי הכרם: \u0003בצל ששתלו בכרם,\u0004 ונאסר משום כלאי הכרם, \u0003ו\u0004אחר כך \u0003נעקר הכרם,\u0004 וגדל הבצל בהיתר, \u0003אפילו הוסיף\u0004 הבצל וגדל בהיתר \u0003ב\u0004שיעור שיש בו פי \u0003מאתים\u0004 מהשיעור שהיה בו כשגדל באיסור — הריהו \u0003אסור.\u0004 הרי שהולכים אחר העיקר, ונפשוט איפוא את בעייתו של ר' שמעון בן פזי!","ומשיבים: \u0003היא,\u0004 הלכה זו \u0003גופה\u0004 \u0005[עצמה]\u0006 \u0003קא מיבעיא ליה\u0004 \u0005[היתה מסופקת לו,\u0006 לר' שמעון בן \u0005פזי\u0006\u0005]:\u0006 האם \u0003מפשט פשיטא להו לרבנן דבתר\u0004 \u0005[פשוט להם לחכמים שאחר]\u0006 ה\u0003עיקר אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם בעקבות קביעה זו יהיה הדין \u0003לקולא\u0004 \u0005[להקל],\u0006 \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לחומרא\u0004 \u0005[להחמיר].\u0006 ותהא אף שיבולת זו מותרת על ידי העומר. \u0003או דלמא\u0004 \u0005[שמא]\u0006 אין בידי חכמים קביעה מוחלטת בשאלה אם הולכים אחר העיקר או אחר התוספת, אלא \u0003ספוקי מספקא להו\u0004 \u0005[מסופק להם הדבר],\u0006 \u0003ו\u0004משום כך, \u0003לחומרא אמרינן\u0004 \u0005[להחמיר אומרים אנו]\u0006 שהולכים אחר העיקר, ולכך במקרים הללו של הגפן ושל הבצל, בדין הערלה וכלאי הכרם — נאסור אותם, אף שהוסיפה פי מאתיים בהיתר. ואולם לפסוק כן אף \u0003לקולא לא אמרינן\u0004 \u0005[להקל אין אנו אומרים]\u0006 שהולכים אחר העיקר, ולא תותר איפוא השעורה הזו שבבעייתו של ר' שמעון בן פזי? ומסכמים כי גם שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ובעקבות בעייתו זו של ר' שמעון בן פזי שעניינה הוא דין השיבולת שנעקרה וחזר ושתלה להיתר העומר בשנה זו, הוסיף ו\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה: לענין מעשר מאי\u0004 \u0005[מה]\u0006 דין שיבולת זו? ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003כגון\u0004"],["שקצר שיבולים רבות, ולא דש אותן, ו\u0003אמדינהו\u0004 \u0005[אמד אותן,\u0006 את כמות השיבולים שקצר\u0005],\u0006 \u0003ועשרינהו\u0004 \u0005[ועישר אותן,\u0006 הפריש מהן תרומות ומעשרות\u0005]\u0006 כשיעור הראוי, ולאחר מכן חזר \u0003ושתלינהו\u0004 \u0005[ושתל אותן],\u0006 וצמחו השיבולים \u0003והוסיפה להו\u0004 \u0005[להן],\u0006 כמות השיבולים על מה שהיתה בתחילה. ומעתה יש לשאול: האם הולכים אנו אחר העיקר, השיבולים שכבר נפטרו מתרומות ומעשרות, ואף התוספת תהיה פטורה מהן. או שהולכים אנו אחר התוספת, ויש לעשר אותה.","ויש להוסיף עוד שאלה: אף \u0003אם תמצא\u0004 מקום להכריע ו\u0003לומר\u0004 כי \u0003לא אזלינן בתר\u0004 \u0005[אין אנו הולכים אחר]\u0006 ה\u0003עיקר, ו\u0004משום כך ה\u0003תוספת בעי עשורי\u0004 \u0005[צריכה עישור],\u0006 עדיין יש לשאול: ה\u0003עיקר מאי\u0004 \u0005[מה]\u0006 דינו, האם גם אותו צריך לעשר (אף \u0005שעושר כבר), או שאין צורך לעשרו?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה בשאלה על בעייתו זו: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 מקרה זה של בעייתך \u0003מכל\u0004 מקרה רגיל של זרעי \u0003חיטי ושערי דעלמא\u0004 \u0005[חיטים ושעורים סתם],\u0006 שאף שהופרשו מאותם זרעים תרומות ומעשרות, בכל זאת כאשר חוזרים וקוצרים את התבואה שגדלה מהם, חייבת היא במעשר. ואף במקרה זה של בעייתך — מדוע תהיינה השיבולים שחזרו וצמחו מהשיבולים פטורות מן המעשר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לאביי בתשובה: באופן הזריעה הרגיל, בו זורעים גרגרי חיטה ושעורה מעושרים, שהרי זה \u0003דבר שזרעו כלה\u0004 (נרקב ומתפרק באדמה עד תום) ולאחר מכן צומח ממנו הפרי, \u0003לא מיבעיא\u0004 \u0005[לא נשאלה]\u0006 \u0003לי\u0004 שאלתי, שהרי ברור הוא שהתבואה \u0005הגדלה מהם חייבת בתרומות ומעשרות.\u0006 \u0003אלא כי קמיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלתי, הרי זה רק ב\u0003דבר שאין זרעו כלה\u0004 באדמה עם זריעתו, אלא הולך ומתפתח ומוסיף על מה שהיה בו מקודם. וכאן יש מקום לשאול \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם תהא התוספת פטורה ממעשרות ותרומה, כיון שהולכת התוספת אחר העיקר שכבר עושר, אם לאו.","ומציעים: \u0003תפשוט ליה\u0004 \u0005[תפתור לו,\u0006 לרבה\u0005]\u0006 את בעייתו \u0003מהא\u0004 \u0005[מ\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' יצחק, אמר ר' יוחנן: ליטרא\u0004 (מידת נפח ומשקל) של \u0003בצל שתיקנו\u0004 (שעישר אותו), וחזר \u0003וזרעו\u0004 אחר כך, וצמח והוסיף הבצל על מה שהיה קודם לכן — \u0003הריהו\u0004 \u0003מתעשר לפי כולו,\u0004 והרי \u0003זו ראיה שגם כאשר אין העיקר כלה לאחר שתילתו מחדש והוא עצמו מוסיף וצומח, שחייב בהפרשת תרומות ומעשרות וכאילו לא נתעשר מעולם!\u0004 ודוחים את הפתרון: אין מכאן תשובה לשאלת רבה.","שכן יש הבדל בין המקרים, שהרי \u0003התם\u0004 \u0005[שם],\u0006 במקרה של בצל שחזר ונשתל — \u0003היינו\u0004 \u0005[זהו]\u0006 אופן \u0003זריעתו\u0004 הרגיל. מה שאין כן \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003לאו היינו\u0004 \u0005[אין זה]\u0006 אופן \u0003זריעתו\u0004 הרגיל. ולא נמצא פתרון לשאלה זו, ונשארה בספק.","ובעקבות בעייתו של רבה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא בר מניומי לאביי:\u0004 דבר שגדל ב\u0003עציץ שאינו נקוב,\u0004 שאינו חייב מן התורה בהפרשת תרומות \u0003ומעשרות,\u0004 \u0003מהו\u0004 דינו להפרשת תרומות ומעשרות? ותמה על הספק: \u0003אי\u0004 \u0005[אם]\u0006 אמנם המדובר באופן זה של הפרשה מן הגדל בעציץ \u0003לא נקוב\u0004 זה על הדבר שגדל בעציץ לא נקוב אחר — אין כאן כל מקום ספק, שכן \u0003הא\u0004 \u0005[הרי]\u0006 הדבר הגדל בעציץ \u0003לא נקוב\u0004 חייב אף הוא מדברי חכמים. ומעתה כשם שהצמח הגדל בעציץ לא נקוב זה הריהו חייב מדברי חכמים, אף הצמח הגדל בעציץ לא נקוב אחר הריהו חייב מדברי חכמים, והרי זה איפוא כמפריש מן החיוב על החיוב!","והציע אביי \u0003לר' חנינא בר מניומי:\u0004 \u0003דלמא\u0004 \u0005[שמא]\u0006 למקרה אחר, שבתחילה גדל הצמח בעציץ שאינו נקוב (והרי איפוא חלק זה שגדל אינו חייב מן התורה בהפרשת תרומות ומעשרות), ולאחר מכן \u0003חזר\u0004 הבעלים \u0003ונקבו,\u0004 והוסיף הצמח וגדל (והרי איפוא חלק זה חייב בהפרשת תרומות ומעשרות מן התורה), ולענין הפרשת תרומות ומעשרות מן הצמח הזה כשלעצמו, \u0003קא אמרת\u0004 \u0005[הוא\u0006 ש\u0005אמרת,\u0006 התכוונת בשאלתך\u0005].\u0006 וצדדי הבעיה: מן הצד האחד יש לומר שהולכים אחר התוספת אף לענין זה שיהיה הצמח כולו (ובכלל זה גם עיקרו שגדל בעציץ שאינו נקוב) חייב בהפרשה מן התורה, ומפריש מן הצמח את תרומותיו ומעשרותיו ונפטר בכך. ואולם מן הצד האחר יש לומר שאין העיקר הולך אחר התוספת, ואין חיובו בתרומות ומעשרות אלא מדרבנן, ולכך אי אפשר להפריש מהצמח תרומות ומעשרות על עצמו, שהרי במה שהוא מפריש יש חלק הבא מן העיקר (הפטור מן התורה) המופרש אף על התוספת (החייבת מן התורה), ואין מפרישים מן הפטור על החייב. וממשיך אביי ואומר, שאף זו אינה בעיה, שאין היא כבעייתו של רבה (בדין השיבולים שנקצרו וחזרו ונשתלו), ואין להשוותן.","כי \u0003הכא\u0004 \u0005[כאן],\u0006 במקרה זה שבבעייתך — כפעולה \u0003חדא\u0004 \u0005[אחת]\u0006 של \u0003זריעה היא\u0004 נחשבת, שהרי לא נזרע הצמח בעציץ אלא פעם אחת בלבד, שכשניקב העציץ \u0003איחבורי\u0004 \u0005[חיבור]\u0006 \u0003הוא דקא מיחברא\u0004 \u0005[שהיא מתחברת]\u0006 אל האדמה \u0003ועולה\u0004 (וצומחת), שאף החלק שצמח בעציץ הלא נקוב מתחבר עתה אל הקרקע, ומתחייב איפוא בהפרשת תרומות ומעשרות מן התורה. ואילו \u0003התם\u0004 \u0005[שם]\u0006 בבעיתו של רבה — \u0003שתי זריעות נינהו\u0004 \u0005[הן].\u0006","ועוד בעיה דומה לבעיית רבה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבהו: שבולת שמרחה בכרי\u0004 (שהחליק את ערימת התבואה, הגורן, והתחייבה בכך בתרומות ומעשרות), ולאחר מכן חזר \u0003ושתלה\u0004 בקרקע, \u0003וקרא עליה שם\u0004 (תרומות ומעשרות, שייחדה להפרשה) \u0003ב\u0004היות הצמח עדיין \u0003מחובר\u0004 לקרקע, \u0003מהו\u0004 דינה של שיבולת זו? האם הפרשה זו חלה. וצדדי השאלה: האם \u0003כיון\u0004 שעמד בתחילה \u0003ו\u0004\u0003מרחה\u0004 בכך השיבולת \u0003טבלא לה\u0004 \u0005[נעשתה טבל\u0006 התבואה החייבת בהפרשת תרומות ומעשרות\u0005],\u0006 ומשום כך, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003קרא עליה שם\u0004 — \u0003קדשה\u0004 \u0005[התקדשה]\u0006 \u0003לה\u0004 התבואה, שחלה ההפרשה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר מן הצד האחר, כי \u0003כיון\u0004 שלאחר מכן חזר ו\u0003שתלה\u0004 — \u0003פקע ליה טבלא מינה\u0004 \u0005[פקע לו\u0006 בכך שם \u0005טבל ממנה],\u0006 ואין \u0005השיבולת הזו חייבת עדיין בתרומות ומעשרות, ולכך לא חלה קריאת השם עליה בהיותה מחוברת לקרקע?\u0006","\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לאביי:\u0004 אם נאמר (כאחד מצדדי הבעיה) שחלה התרומה על התבואה המחוברת לקרקע, \u0003אם כן מצינו\u0004 (מצאנו) איפוא \u0003תרומה ב\u0004דבר \u0003ה\u0004\u0003מחובר לקרקע, ו\u0004אולם הרי \u0003תנן\u0004 \u0005[שנינו]\u0006 כי \u0003לא מצינו תרומה במחובר לקרקע!\u0004","\u0003אמר ליה\u0004 \u0005[להם]\u0006 אביי לחכמים: אין להקשות מכאן, שכן \u0003כי תניא ההיא\u0004 \u0005[כאשר נשנתה אותה\u0006 הלכה\u0005]\u0006 הרי זה רק \u0003לענין איחיובי\u0004 \u0005[חיוב]\u0006 \u0003מיתה\u0004 בידי שמים על אכילת תרומה זו במזיד על ידי זר, \u0003ו\u0004לענין חיוב תשלומי \u0003חומש\u0004 (חמישית) נוסף לקרן, אם אכלה בשוגג. וטעם חיוב זה: משום \u0003דאי תליש ואכיל\u0004 \u0005[שאם\u0006 הוא \u0005תולש\u0006 מן המחובר לקרקע \u0005ואוכל]\u0006 — הרי זו אכילתו של \u0003דבר\u0004 \u0003תלוש הוא,\u0004 ובכגון זה ודאי שחייב. \u0003ואי גחין ואכיל\u0004 \u0005[ואם\u0006 הוא \u0005גוחן ואוכל]\u0006 מן המחובר לקרקע — אין זו נחשבת אכילה, שאין בני אדם אוכלים כך, ואף שהוא עשה כן, \u0003בטלה\u0004 (אינה נחשבת) \u0003דעתו אצל\u0004 (בהתייחס אל) \u0003כל אדם,\u0004 והריהו פטור ממיתה ומחומש על אכילה זו.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 דינו של האדם האוכל ישירות מן הדבר המחובר, שאין זו נחשבת אכילה, שכן בטלה דעתו אצל כל אדם, \u0003מדכתב אפינקסא\u0004 \u0005[מ\u0006דין זה \u0005ש\u0006נמצא \u0005כתוב על הפנקס]\u0006 של החכם \u0003אילפא\u0004 בענינן של \u0003ביצי נבלת העוף הטהור,\u0004 ובאופן שהיו \u0003מקצתן\u0004 (חלק מהביצים) נמצאות \u0003בחוץ,\u0004 מחוץ לגוף העוף, \u0003ומקצתן\u0004 נמצאות \u0003בפנים.\u0004 שהביצים שהן \u0003מבפנים\u0004 — נחשבות כגוף העוף, וכשם שנבלת עוף טהור מטמאת את האדם ואת בגדיו להצריכם כיבוס (\"מטמא בגדים\") אף הן \u0003מטמאין\u0004 את האוכלן בטומאת \u0003בגדים\u0004 כשהן \u0003אבית\u0004 (בבית) \u0003הבליעה.\u0004 ואילו אכילת הביצים ש\u0003מבחוץ\u0004 — \u0003אין מטמאין בגדים אבית הבליעה.\u0004 הרי שאף דרך אכילה לא מקובלת שכזו נחשבת כאכילה, וחייבים עליה!","ודוחים: אין \u0003הדברים דומים, שכן דבר ה\u0004\u0003תלוש\u0004 כביצים הנמצאות בתוך גוף העוף — \u0003עבידי אינשי דאכלי הכי\u0004 \u0005[עשויים אנשים שאוכלים כך],\u0006 אבל \u0003ב\u0004דבר ה\u0003מחובר,\u0004 וכגון אכילה מן הצמח המחובר לקרקע — \u0003לא עבידי אינשי דאכלי\u0004 \u0005[אין עשויים אנשים לאכול\u0006 כך\u0005].\u0006 ולא נפתרה בעיית ר' אבהו, ותעמוד במקומה.","למעלה נידון דין דבר הנזרע בעציץ שאינו נקוב לענין חובת המעשר, ועוד בדין הדבר הנזרע בעציץ שאינו נקוב, \u0003אמר רב טביומי בר קיסנא,\u0004 \u0003אמר שמואל: הזורע כלאים בעציץ שאינו נקוב\u0004 — \u0003אסור\u0004 מדברי חכמים. \u0003אמר אביי:\u0004 מה השמיענו שמואל שאמר שהדבר אסור, \u0003בשלמא אי אשמעינן\u0004 \u0005[נניח אם היה משמיע לנו]\u0006 שהעובר על כך \u0003לוקה מכת מרדות מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 — \u0003שפיר\u0004 \u0005[יפה]\u0006 לימדנו בכך, \u0003אלא\u0004 במה שאמר ש\u0003אסור\u0004 הדבר, \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]?\u0006","אם תאמר שמשמיע לנו \u0003דמדרבנן הויא\u0004 \u0005[שמדברי סופרים הריהי\u0006 נחשבת\u0005]\u0006 \u0003זריעה\u0004 — הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 זאת, שכן שנינו: אם \u0003תרם מ\u0004דבר שגדל בעציץ \u0003שאינו נקוב\u0004 (החייב בתרומה רק מדרבנן) \u0003על\u0004 דבר שגדל בעציץ \u0003הנקוב\u0004 (החייב בתרומה מן התורה) — הרי זו \u0003תרומה,\u0004 שהרי מדרבנן נחשב \u0003כתורם מן החייב על החייב.\u0004 \u0003ו\u0004אולם דינו הוא ש\u0003יחזור ויתרום,\u0004 שכן ביחס לדין תורה, הרי זה כתורם מן הפטור על החייב. והרי איפוא שנחשבת היא הזריעה בעציץ שאינו נקוב?","חמשת מיני דגן, \u0003החיטין, והשעורין, והכוסמין, והשיבולת שועל, והשיפון\u0004 — \u0003הרי\u0004 \u0003אלו חייבין ב\u0004הפרשת \u0003חלה\u0004 מן העיסה שנעשתה מהם. \u0003ומצטרפין זה עם זה\u0004 לכדי שיעור המחייב הפרשת חלה מן העיסה. \u0003ואסורים ב\u0004איסור אכילת היבול ה\u0003חדש מלפני\u0004 הבאת \u0003ה\u0004עומר \u0003ב\u0004\u0003פסח, ו\u0004כן אסור \u0003לקצור\u0004 מכל אלה \u0003מלפני\u0004 קציר \u0003העומר. אם השרישו\u0004 כל אלה \u0003קודם לעומר\u0004 — \u0003העומר מתירן, ואם לאו\u0004 \u0005[לא]\u0006 — הריהם \u0003אסורין עד שיבא העומר הבא\u0004 בשנה הבאה.","שנינו במשנתנו דינם של חמשת מיני דגן, ובעניינם של אלה עוד \u0003תנא\u0004 \u0005[שנה\u0006 בברייתא\u0005]:\u0006 ה\u0003כוסמין\u0004 — הריהם \u0003מין חיטים, שיבולת שועל ושיפון\u0004 — הריהם \u0003מין שעורין.\u0004 ומפרשים מה טיבם: \u0003כוסמין\u0004"],["קרויים בארמית \u0003גולבא, שיפון\u0004 — הצמח הנקרא בארמית \u0003דישרא, שיבולת שועל\u0004 — זו הקרויה אף בארמית \u0003שבולי תעלא\u0004 \u0005[שיבולת שועל].\u0006 שנינו במשנה כי העיסה הנעשית מחמשת המינים הללו חייבת בהפרשת חלה, ומדייקים: דווקא זו הנעשית מ\u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייבת בהפרשת חלה, אבל הנעשית מ\u0003אורז ו\u0004מ\u0003דוחן\u0004 — \u0003לא.\u0004","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין אלה הדברים,\u0006 מה מקורם\u0005]?\u0006 \u0003אמר ריש לקיש: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המלה \u0003\"לחם\"\u0004 האמורה בתורה בדין הפרשת חלה, והמלה \u0003\"לחם\" מ\u0004תוך הנאמר בתורה בדין אכילת \u0003מצה\u0004 בפסח. ומפרטים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בחלה\u0005]:\u0006 \u0003\"והיה באכלכם מלחם הארץ\u0004 תרימו תרומה לה'. ראשית עריסותיכם חלה תרימו תרומה... מראשית עריסותיכם תתנו לה' תרומה לדורותיכם\" (במדבר טו, יט— כא), \u0003וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 במצות אכילת מצה בפסח\u0005]:\u0006 \"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות \u0003לחם עני\u0004 כי בחפזון יצאת מארץ מצרים...\" (דברים טז, ג). ומתוך השוואת דין הפרשת חלה לדין אכילת מצה למדים אנו, כי כשם שאין המצה נאכלת בפסח אלא מחמשת מיני דגן אלה בלבד, אף הפרשת חלה אינה נעשית אלא מעיסה שנעשתה מחמשת מיני דגן אלה בלבד.","ושואלים: \u0003והתם גופה מנלן\u0004 \u0005[ושם\u0006 במצה \u0005עצמה מנין לנו]\u0006 שאין מצוותה אלא בחמשת מיני דגן אלה בלבד? \u0003אמר ריש לקיש, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 המדרש\u0005]\u0006 של \u0003ר' אליעזר בן יעקב: אמר קרא\u0004 \u0005[המקרא]\u0006 בדין המצה: \u0003\"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות לחם עני\"\u0004 — ומה שהוזכרו בכתוב אחד איסור אכילת חמץ ומצות אכילת מצה, הרי זה להורות כי רק ב\u0003דברים הבאים\u0004 (העלולים, שיש ביכולתם להגיע) \u0003לידי חימוץ\u0004 (שהם חמשת מיני הדגן), \u0003אדם יוצא בהן ידי חובתו בפסח. יצאו\u0004 מכלל זה \u0003אלו\u0004 (אורז ודוחן) \u0003שאין\u0004 הן \u0003באין\u0004 לעולם \u0003לידי חימוץ\u0004 אם באו במגע עם מים, \u0003אלא\u0004 רק \u0003לידי סירחון\u0004 (קלקול), שאין מקיימים בהם מצות אכילת מצה.","\u0003ו\u0004עוד שנינו במשנתנו כי חמשת מיני הדגן הללו \u0003מצטרפין זה עם זה.\u0004 ומציינים כי בענין זה עוד \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: גרגרי \u0003התבואה והקמחים\u0004 הבאים מהם לאחר טחינתם, \u0003והבציקות\u0004 הנעשות מהקמח — כל אלה \u0003מצטרפין זה עם זה\u0004 לשיעור הנדרש כדין. ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמרו הדברים?","\u0003אמר רב כהנא:\u0004 נאמרו הדברים \u0003לענין\u0004 איסור האכילה מן היבול ה\u0003חדש\u0004 לפני התרתו בפסח, שאם אכל מן החדש כשיעור כזית המורכב מגרגרי תבואה ומקמח ומבצק, הריהו לוקה על כך. \u0003רב יוסף אמר:\u0004 נאמרו הדברים \u0003לענין\u0004 איסור אכילת \u0003חמץ בפסח,\u0004 ולהשמיענו שאם אכל בפסח כזית חמץ המורכב מגרגרים ומקמח ומבצק שהוחמצו, הריהו נענש על כך ככל האוכל כזית חמץ. \u0003רב פפא אמר:\u0004 נאמרו הדברים \u0003לענין\u0004 איסור אכילת פירות \u0003מעשר שני\u0004 מחוץ לחומת ירושלים, וללמדנו \u0003דאי אכיל ליה\u0004 \u0005[שאם אוכל\u0006 את \u0005אותו]\u0006 מעשר שני בשיעור כזית המורכב מגרגרי תבואה ומקמח ומבצק של מעשר שני \u0003חוץ לחומה\u0004 של ירושלים הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך.","\u0003רבא אמר:\u0004 \u0005נאמרו הדברים\u0006 \u0003לענין\u0004 צירוף כל אלה לכלל שיעור כביצה, \u0005ולטמא ב\u0006\u0003טומאת אוכלין.\u0004 \u0003ו\u0004מסביר רבא את דבריו, כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה היא,\u0006 הברייתא \u0005משמיעה,\u0006 מחדשת \u0005לנו],\u0006 שאין גרגרי ה\u0003תבואה\u0004 (הבאים מן השעורים) \u0003ו\u0004ה\u0003קמחין\u0004 מצטרפים לשיעור המטמא אלא רק כשהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בצקות: מה התם\u0004 \u0005[שם,\u0006 הבצקות\u0005]\u0006 — הרי זה \u0003אוכלא בעיניה\u0004 \u0005[אוכל בעינו,\u0006 כשלעצמו, וללא תוספת וקליפה\u0005],\u0006 \u0003אף הכא נמי\u0004 \u0005[כאן,\u0006 בתבואה ובקמחים \u0005גם\u0006 \u0003כן]\u0004 — \u0003אוכלא בעיניה\u0004 \u0005[אוכל בעינו]!\u0006","ומוסיף רבא עוד: \u0003והתניא\u0004 \u0005[והרי\u0006 כך גם \u0005שנויה\u0006 ברייתא\u0005]:\u0006 גרגר ה\u0003חטה\u0004 הטמאה, \u0003בין\u0004 שהיא \u0003קלופה, בין שאינה קלופה\u0004 — \u0003מצטרפת\u0004 החיטה בגרגריה ובקליפתם לאוכל אחר, להשלים לשיעור כביצה לענין טומאת אוכלין, ואין הדברים אמורים אלא בחיטה, מה שאין כן ב\u0003שעורה,\u0004 שה\u0003קלופה\u0004 — \u0003מצטרפת\u0004 לאוכל אחר לכלל שיעור כביצה. \u0005ואילו זו\u0006 \u0003שאינה קלופה\u0004 — \u0003אין מצטרפת.\u0004 ואף הלכה זו אמורה בשעורה, ולכך אין מצטרפים הגרגרים והקמח אלא כשהם ללא קליפה, ובדומה לבצקות.","ותוהים: \u0003איני\u0004 \u0005[כך הוא]\u0006 הדין, שאין גרגרי השעורה מצטרפים לשיעור טומאה אלא בלא קליפתם? \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר בתורה לענין קבלת טומאה של דברי המאכל על ידי הדברים המטמאים בטומאת שרץ \"וכי יפול מנבלתם \u0003על כל זרע זרוע אשר יזרע\u0004 טהור הוא\" (ויקרא יא, לז), שכל עוד לא הוכשרו הזרעים לקבל טומאה בנפילת מים (או שאר משקים המכשירים לקבל טומאה) אינם מקבלים טומאה. ואם הוכשרו — הריהם מקבלים טומאה, כנאמר בהמשך פסוק זה \"וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (שם לח), ולמדנו מכאן שהאוכל המקבל טומאה הריהו כ\"זרע זרוע אשר יזרע\", \u0003כדרך שבני אדם מוציאין לזריעה,\u0004 ובפועל: גרגרי \u0003חטה בקליפתה ו\u0004גרגרי \u0003שעורה בקליפתה ועדשים בקליפתן,\u0004 משמע מכאן שלטומאת אוכלין נחשבות גם הקליפות של השעורים!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שקליפת השעורים מצטרפת לקבלת הטומאה — הרי זה דווקא \u0003ב\u0004שעורים \u0003לחות,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין קליפת השעורים מצטרפת לקבלת טומאה — הרי זה \u0003ב\u0004שעורים \u0003יבשות.\u0004","\u0003ו\u0004עוד נאמר במשנתנו בדינם של חמשת מיני הדגן הנזכרים, שכל אלה \u0003אסורין ב\u0004אכילה מן ה\u0003חדש מלפני הפסח,\u0004 ואין שאר מינים אסורים באכילת החדש. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה מקורם\u0005]\u0006 שאין איסור החדש אלא בחמשת המינים הללו בלבד? \u0003אמר ריש לקיש: אתיא\u0004 \u0005[נלמד הדבר]\u0006 בגזירה שווה \u0003\"לחם\" \"לחם\" ממצה,\u0004 וכדרך שהתבאר למעלה שכשם שהמצה באה מחמשת המינים הללו בלבד, אף איסור אכילת חדש נוהג בחמשת המינים הללו בלבד.","\u0003ו\u0004עוד שנינו במשנתנו בדינם של חמשת מיני דגן אלה שאסור \u0003לקצור\u0004 אותם \u0003לפני העומר.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה מקורם\u0005]?\u0006 \u0003אמר ר' יוחנן: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המלה \u0003\"ראשית\"\u0004 האמורה בדין קצירת העומר (\"...כי תבואו אל הארץ אשר אני נותן לכם וקצרתם את קצירה והבאתם את עומר ראשית קצירכם אל הכהן\". ויקרא כג, י), והמלה \u0003\"ראשית\" מ\u0004תוך הנאמר בדין הפרשת \u0003חלה\u0004 (\"ראשית עריסותיכם חלה תרימו תרומה...\". במדבר טו, כ). וכשם, שאין החלה באה אלא מעיסה העשויה מחמשת מיני הדגן הללו, אף איסור קצירה לפני העומר אינו נוהג אלא באלה.","שנינו במשנתנו שאסורים כל חמשת מיני הדגן הללו באיסור חדש קודם לעומר, \u0003ו\u0004שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הכוונה\u0005]\u0006 בלשון זו \u0003\"קודם לעומר\",\u0004 שהרי בהבאת העומר ישנם שלבים שונים, המתחילים בקצירתו בלילה, ולאחר מכן מאירים פני המזרח של יום הבאת העומר, ועד להנפתו של העומר במקדש, ולא פירשה המשנה למה כוונתה? ונחלקו חכמים בדבר, ש\u0003ר' יונה אמר\u0004 כי הכוונה היא לזמן ש\u0003קודם קצירת העומר,\u0004 כלומר, בכל הלילה, שהוא הזמן הכשר לקצירה, ובהארת פני המזרח של יום ט\"ז בניסן הותרה אכילת היבול החדש. ואילו \u0003ר' יוסי בר זבדא אמר\u0004 שהכוונה היא לזמן ש\u0003קודם הבאת העומר\u0004 במקדש, שעדיין אסורה אכילת החדש, אף משהאירו פני מזרח של יום ט\"ז בניסן, עד שיובא ממש העומר.","ודנים בשיטותיהם: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 כי חמשת המינים הללו \u0003אסורין ב\u0004אכילת היבול ה\u0003חדש לפני פסח ו\u0004כמו כן הריהם אסורים מ\u0003לקצור לפני העומר. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה באיסור אכילת החדש לזמן ש\u0003קודם הבאת העומר\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם לכך שהתנא במשנתנו \u0003לא קא עריב להו\u0004 \u0005[אין הוא מערב אותם,\u0006 את איסור אכילת החדש ואת איסור קצירתו\u0005]\u0006 \u0003ותני להו\u0004 \u0005[ושונה אותם\u0006 יחד\u0005],\u0006 שהרי אין האכילה אסורה עד הבאת העומר ביום השני של פסח, ואילו הקצירה אסורה רק עד תום זמן קצירת העומר בלילה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה באיסור אכילת החדש לזמן ש\u0003קודם קצירת העומר\u0004 — אם כן \u0003ליערבינהו וליתנינהו\u0004 \u0005[שיערב אותם וישנה אותם]\u0006 באופן זה: \u0003אסורין בחדש ולקצור לפני הפסח!\u0004","אלא יש לומר שלא נחלקו ר' יונה ור' יוסי בר זבדא בפירוש כוונת תחילת דברי משנתנו \u0003אלא אי איתמר אסיפא איתמר\u0004 \u0005[אם נאמרה\u0006 מחלוקת זו, הרי ש\u0005על\u0006 הדברים שב\u0005סוף\u0006 משנתנו \u0005נאמרה],\u0006 שכך שנינו במשנה: \u0003אם השרישו קודם לעומר\u0004 — \u0003העומר מתירן.\u0004 ובשאלה \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בביטוי \u0003\"קודם לעומר\",\u0004 ש\u0003ר' יונה אמר\u0004 שהכוונה היא לזמן ש\u0003קודם הבאת העומר,\u0004 ואילו \u0003ר' יוסי בר זבדא אומר\u0004 שהכוונה היא לזמן ש\u0003קודם קצירת העומר.\u0004","שנינו במשנתנו שהעומר מתיר את האסורים באיסור חדש אם השרישו קודם לעומר. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר\u0004"],["\u0003לר' יאשיה דדריה\u0004 \u0005[של דורו],\u0006 וככינוי המסביר שאין הכוונה לר' יאשיה התנא: \u0003לא תיתב אכרעיך\u0004 \u0005[אל תשב על רגליך]\u0006 אלא עמוד \u0003עד דמפרשת ליה להא מתניתין\u0004 \u0005[עד שאתה מפרש את הברייתא הזו,\u0006 הבאה\u0005]:\u0006 \u0003מנין לעומר שמתיר בהשרשה?\u0004","ולפני שמביאים את תשובת הברייתא, תוהים על עצם השאלה: מה מקום לשאול \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 שכן ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במנחת העומר \"ואם תקריב מנחת בכורים לה'\u0003 אביב\u0004 קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (ויקרא ב, יד), שאמרה תורה שיש להביא את העומר המתיר את התבואה החדשה דווקא מהתבואה שהיא בגדר \"אביב\" (הבשלה כל צורכה), \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 נלמד \u0003מכלל\u0004 כך \u0003דאיכא\u0004 \u0005[שיש]\u0006 תבואה \u0003דלאו\u0004 \u0005[שאינה]\u0006 בכלל \u0003\"אביב\",\u0004 שאינה מובאת כמנחת העומר, ואולם הריהי מותרת על ידו. והיא התבואה שהושרשה וטרם בשלה כדי \"אביב\", שמותרת על ידי העומר.","ודוחים: אפשר לומר שאף התבואה \u0003דלאו\u0004 \u0005[שאינה]\u0006 בכלל \u0003\"אביב\"\u0004 מותרת על ידי העומר, \u0003ו\u0004אולם \u0003לעולם\u0004 אין היתר זה אלא בתבואה \u0003דעייל\u0004 \u0005[שהביאה]\u0006 כבר \u0003שליש\u0004 גידולה בזמן העומר, שאף שאינה בכלל \"אביב\" הריהי מותרת.","\u0003אלא אמר שמואל:\u0004 היתר התבואה שהשרישה בזמן העומר נלמד ממה שנאמר \"שבעה שבועות תספור \u0003לך\u0004 \u0003מהחל חרמש\u0004 בקמה תחל לספור שבעה שבועות\" (דברים טז, ט). ומתוך שהדגיש הכתוב שקציר העומר נעשה דווקא בקמה שהיא בת קצירה בחרמש, ולא בתבואה אחרת שאינה כזו, \u0003לאו\u0004 \u0005[האם לא]\u0006 נלמד \u0003מכלל\u0004 כך, \u0003דאיכא\u0004 \u0005[שיש]\u0006 יבול תבואה אחר, \u0003דלאו\u0004 \u0005[ש\u0006עדיין \u0005אינו]\u0006 \u0003בר\u0004 קצירה ב\u0003חרמש\u0004, שאינו בא למנחת העומר, ואולם מותר על ידו. אפשר לומר שאף יבול התבואה \u0003דלאו בר\u0004 \u0005[שאינו בן]\u0006 קצירת \u0003חרמש\u0004 הריהו מותר על ידי העומר, \u0003ו\u0004אולם \u0003לעולם\u0004 אין היתר זה אלא רק לתבואה שגדלה דיה כדי לשמש כ\u0003שחת\u0004 (אוכל לבהמות).","\u0003אמר ר' יצחק:\u0004 למדים את היתר התבואה שהושרשה טרם הבאת העומר ממה שנאמר באותו כתוב \"מהחל חרמש ב\u0003קמה\",\u0004 ומתוך שהדגיש הכתוב כי קציר העומר נעשה דווקא בקמה, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 כך אתה למד שישנה תבואה אחרת, \u0003דלאו בר\u0004 \u0005[ש\u0006היא \u0005אינה בת,\u0006 בגדר\u0005]\u0006 \u0003קמה,\u0004 שאמנם אין קצירת העומר נעשית בה, ואולם העומר מתירה, והרי זו התבואה שהשרישה בזמן העומר. ודוחים: אפשר לומר שיש תבואה אחרת \u0003דלאו בר\u0004 \u0005[ש\u0006היא \u0005אינה בת]\u0006 \u0003קמה,\u0004 המותרת על ידי העומר, \u0003ולעולם\u0004 (ואולם) הוא היתר רק לתבואה שהיא בכלל \u0003אגם\u0004 (שגדלה מעט, כדי כיפוף ראשה כלפי מטה)!","\u0003אלא אמר רבא:\u0004 למדים אנו שהתבואה שהשרישה טרם לעומר הריהי מותרת על ידו מן הנאמר \"וחג הקציר בכורי מעשיך \u0003אשר תזרע\u0004 בשדה\" (שמות כג, טז), שאף שאמורים הדברים בשתי הלחם הבאים בחג השבועות (\"חג הקציר\") ומתירים את התבואה החדשה למקדש, הרי הכתוב מתייחס גם לעומר (הבא בפסח, ומתיר את התבואה להדיוט), ולמדנו איפוא מן האמור בו \"אשר תזרע\" כי כל התבואה החל \u0003משעת זריעה\u0004 שנזרעה, הריהי מותרת (להדיוט — על ידי העומר, ולמקדש — על ידי שתי הלחם). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 בשאלה: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שזה המקור להיתר התבואה שהשרישה טרם העומר על ידו, יש מקום לומר שכל מין דגן שנזרע, ו\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שעדיין \u0003לא השריש\u0004 בזמן העומר \u0003נמי\u0004 \u0005[גם כן]\u0006 נתיר אותו, שהרי בכתוב זה מדובר על הדגן משעת זריעתו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב פפא בתשובה, בדרך חיבה וכבוד: \u0003סודני\u0004 (תלמיד חכם), \"אשר תזרע \u0003בשדה\" כתיב\u0004 \u0005[נאמר]\u0006 בכתוב זה, וללמדנו שלא בכל דבר שנזרע העומר מתיר, אלא רק זה שנעשה כשדה, נזרע ונקלט ונשרש בשדה.","אף לפני העומר \u0003קוצרין\u0004 (מותר לקצור) את התבואה הגדלה בשדה \u0003בית השלחין\u0004 (מקום המושקה בידי אדם, ולא על ידי גשמים בלבד) \u0003ש\u0004נמצאים \u0003בעמקים. אבל לא גודשין\u0004 (עושים גדיש, ערימת תבואה קצורה) לפני העומר אותה תבואה לאחר שנקצרה. ובענין זה נמסר כי \u0003אנשי\u0004 העיר \u0003יריחו,\u0004 ששדות תבואותיהם היו של בית השלחין שבעמקים, היו \u0003קוצרין\u0004 את תבואות שדותיהם לפני העומר, והיה הדבר נעשה \u0003ברצון\u0004 (בהסכמת) \u0003חכמים, ו\u0004אולם אנשי יריחו היו גם \u0003גודשין\u0004 לפני העומר אותה התבואה, והיה דבר זה נעשה \u0003שלא ברצון חכמים. ו\u0004למרות שלא היה הדבר לרצונם של חכמים, \u0003לא מיחו בידם\u0004 חכמים למונעם מלעשות כן. ודין נוסף: לפני העומר \u0003קוצר\u0004 אדם את התבואה שבכל מקום (ואף בשדה בעל, שאינה בית השלחין) קודם לעומר \u0003ל\u0004צורך \u0003שחת\u0004 (מאכל בהמה), ו\u0003מאכיל\u0004 אותה \u0003לבהמה. אמר ר' יהודה: אימתי\u0004 מותר לקצור לשחת ולהאכיל בה את הבהמה? רק \u0003בזמן שמתחיל\u0004 לקצור לצורך מאכל בהמתו \u0003עד שלא\u0004 (בטרם) \u0003הביא שליש\u0004 (גודל צמח התבואה כדי שליש בישולו). שאם בתחילת קצירתו עדיין לא נגמר שליש גידולו של הצמח — מותר להמשיך ולקוצרו למאכל בהמה אף לאחר שהביא שליש. ואילו \u0003ר' שמעון אומר: יקצור ויאכיל\u0004 (רשאי אדם \u0003לקצור קודם לעומר לצורך בהמתו ולהאכילה)\u0004 \u0003אף משהביא\u0004 (לאחר שהביא) צמח התבואה \u0003שליש\u0004 בישולו.","\u0003ו\u0004עוד בדינים הנוהגים לפני העומר: \u0003קוצרין\u0004 את התבואה הגדלה בין הנטיעות, לא לצורך אכילה אלא \u0003מפני\u0004 (על מנת) שלא יגרם על ידן הפסד ל\u0003נטיעות\u0004 שבצידה. וכן מותר לקצור את התבואה לפני העומר \u0003מפני\u0004 (כדי) לפנות את מקום התבואה שישמש ל\u0003בית האבל\u0004 (מקום בו מברכים את האבלים בשובם מקבורת מתם). או \u0003מפני\u0004 שישמש אותו מקום את התלמידים הלומדים תורה, שאלמלא כן היה נגרם \u0003ביטול בית המדרש\u0004 בשל חוסר מקום. ואולם בכל האופנים שבהם הותר לקצור קודם העומר, \u0003לא יעשה אותן\u0004 לאחר קצירתן \u0003כריכות\u0004 (אלומות אגודות), \u0003אבל מניחין\u0004 אותן כ\u0003צבתים\u0004 (אלומות לא אגודות).","והלכה נוספת: האופן הראוי לקיום \u0003מצות העומר\u0004 הוא \u0003לבא מן ה\u0004שעורים בעודן \u0003קמה\u0004 (העומדת בשדה בקומתה, שטרם נקצרה). ואולם אם \u0003לא מצא\u0004 קמה לקצור ולהביאה כעומר, שכן כבר נקצר הכל — \u0003יביא\u0004 את העומר \u0003מן העמרים\u0004 (שיבולים קצורות שנאגדו באלומות). ועוד הלכה: האופן הראוי לקיום \u0003מצותו\u0004 הוא \u0003לבא מן\u0004 צמח השעורה \u0003הלח\u0004 והמלא. ואולם אם \u0003לא מצא\u0004 מן הלח — \u0003יביא\u0004 מיבול השעורים ה\u0003יבש.\u0004 ועוד, האופן הראוי לקיום \u0003מצותו\u0004 הוא \u0003לקצור\u0004 את העומר \u0003בלילה,\u0004 במוצאי יום טוב ראשון של פסח. ואולם אם לא נקצר העומר בלילה, ו\u0003נקצר ביום\u0004 — הריהו \u0003כשר. ו\u0004עוד, קציר העומר \u0003דוחה את השבת.\u0004","שנינו במשנתנו שמותר לקצור את התבואות הגדלות בבית השלחין שבעמקים לפני העומר. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' בנימין אומר\u0004 על הנאמר בתורה בדין העומר \"דבר אל בני ישראל ואמרת אליהם כי תבואו אל הארץ אשר אני נותן לכם וקצרתם את קצירה והבאתם את עומר ראשית קצירכם אל הכהן\" (ויקרא כג, י): בפסוק זה יש כעין סתירה, שהרי \u0003כתוב אחד אומר \"וקצרתם את קצירה והבאתם את עמר\"\u0004 — בתחילה \"וקצרתם\", ורק אחר כך \"והבאתם את עומר\", ולכאורה הכוונה שבתחילה קוצרים את קציר הארץ לצורככם, ולאחר מכן יש להביא את העומר, ונמצא איפוא שאין קציר העומר ראשית הקציר. \u0003ו\u0004אולם לאחר מכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 בפסוק \u0003\"ראשית קצירכם אל הכהן\"\u0004 — והרי זה מורה שהעומר הוא ראשית הקציר.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? אלא שני חלקי הפסוק עוסקים בקצירת תבואות שונות, ובאופן זה: \u0003ממקום\u0004 תבואות \u0003ש\u0004ממנו \u0003אתה מביא\u0004 (רשאי להביא) את העומר — \u0003אי\u0004 (אין) \u0003אתה קוצר\u0004 לפני העומר (ואז העומר הוא \"ראשית קצירכם\"). ואילו \u0003ממקום\u0004 תבואות \u0003שאי\u0004 (שאין) \u0003אתה מביא\u0004 ממנו את העומר — \u0003אתה קוצר\u0004 לפני העומר (ובאופן זה מתקיים האמור בכתוב \"וקצרתם... והבאתם את עומר\", שיש תבואה הנקצרת לפני העומר).","ומקשים: והרי ניתן ליישב את הסתירה שבכתובים הללו באופן אחר, ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003ממין\u0004 הדגן \u0003שאתה מביא\u0004 ממנו את העומר (כלומר, ממין השעורים) — \u0003אי\u0004 (אין) \u0003אתה קוצר\u0004 לפני העומר, ואילו \u0003ממין\u0004 הדגן \u0003שאי\u0004 (שאין) \u0003אתה מביא\u0004 ממנו את העומר (כלומר, בשאר מיני הדגן) — \u0003אתה קוצר\u0004 לפני העומר. ומעתה אם כן אין אנו יודעים שמותרת לפני העומר קצירת תבואות השעורים שבבית השלחין שבעמקים! ודוחים: האופן \u0003ההוא\u0004 של הסבר \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן\u0004 בעמוד הקודם שלימדנו מדרשת גזירה שווה \"ראשית\" \"ראשית\" האמורות בעומר ובמצות חלה, שאסורה הקצירה לפני העומר בכל סוגי התבואה, ולא רק בשעורים שמהן בא העומר.","שנינו במשנתנו כי \u0003אנשי יריחו\u0004 היו \u0003קוצרין\u0004 את תבואותיהם לפני העומר, והיה הדבר \u0003ברצון חכמים, ו\u0004היו אנשי יריחו \u0003גם\u0004 \u0003גודשין\u0004 את התבואה שנקצרה לפני העומר, ודבר זה היה \u0003שלא ברצון חכמים,\u0004 ואולם חכמים לא מיחו בידם על כך, למונעם מלעשות כן. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 התנא \u0003ש\u0004\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 בלשון של \u0003מיחו\u0004 חכמים \u0003ולא מיחו\u0004 חכמים? הלא \u0003ר' יהודה\u0004 הוא זה (שדבריו בענין זה יובאו להלן), ומכאן יש איפוא להסיק כי דברי משנתנו \u0003הריהם דברי ר' יהודה.\u0004","\u0003ו\u0004אולם על כך יש לשאול: האם \u0003סבר ר' יהודה\u0004 שה\u0003קצירה\u0004 של התבואות לפני העומר על ידי \u0003אנשי יריחו ברצון חכמים הואי\u0004 \u0005[היתה],\u0006 כנאמר במשנתנו, \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 כי \u0003ששה דברים עשו אנשי יריחו, שלשה\u0004 מהם היו \u0003ברצון חכמים, ושלשה\u0004 מהם היו \u0003שלא ברצון חכמים.\u0004","ומפרטים, \u0003ואלו\u0004 הם שלושת הדברים \u0003ש\u0004היו \u0003ברצון חכמים:\u0004 אנשי יריחו היו \u0003מרכיבין דקלים כל היום\u0004 של ערב פסח; \u0003ו\u0004היו אנשי יריחו \u0003כורכין\u0004 (אומרים במחובר, בלא הפסק בין מלה למלה) \u0003את\u0004 מלותיה של פרשת \u0003\"שמע\u0004 ישראל\"; \u0003ו\u0004היו \u0003קוצרין לפני העומר,\u0004 ואלה היו \u0003ברצון חכמים. ואלו\u0004 שלושת הדברים שעשו \u0003שלא ברצון חכמים:\u0004 היו \u0003גודשין לפני העומר;\u0004 \u0003ו\u0004היו \u0003מתירין\u0004 ליהנות מן ה\u0003גמזיות\u0004 (ענפים) \u0003של הקדש של\u0004 עץ ה\u0003חרוב ושל\u0004 עץ ה\u0003שקמה; ו\u0004היו \u0003פורצין פרצות בגנותיהן ובפרדסותיהן\u0004 על מנת \u0003להאכיל נשר\u0004 (הפירות הנושרים מן העצים שבגנות ובפרדסים) \u0003לעניים בשני\u0004 (בשנות) \u0003בצורת בשבתות ובימים טובים,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר לו ר' יהודה:\u0004 אי אפשר לומר כדבריך, שהרי \u0003אם ברצון חכמים הן\u0004 היו \u0003עושין, יהו כל אדם עושין כן,\u0004 ומדוע לא היה זה אלא מנהגם של אנשי יריחו בלבד! \u0003אלא אלו ואלו\u0004 כולם נעשו \u0003שלא ברצון חכמים.\u0004 \u0003ו\u0004אולם \u0003על שלשה\u0004 מתוך אלה \u0003מיחו\u0004 חכמים \u0003בידם\u0004 של אנשי יריחו, למונעם מלעשות כן, \u0003ו\u0004אילו \u0003על שלשה\u0004 האחרים \u0003לא מיחו בידם.\u0004","ומפרט ר' יהודה את דבריו: \u0003ואלו\u0004 שלושת הדברים \u0003שלא מיחו\u0004 חכמים \u0003בידם:\u0004 על זה שהם היו \u0003מרכיבין דקלים כל היום; ו\u0004על זה שהם היו \u0003כורכין את שמע; ו\u0004על זה שהם היו \u0003קוצרין וגודשין לפני העומר. ואלו\u0004 שלושת הדברים \u0003שמיחו\u0004 חכמים \u0003בידם\u0004 של אנשי יריחו:"],["על שהיו אנשי יריחו \u0003מתירין גמזיות של הקדש של\u0004 עצי \u0003חרוב ושל\u0004 עצי \u0003שקמה,\u0004 \u0003ו\u0004כן על שהיו \u0003פורצין פרצות בגנותיהן ובפרדסותיהן כדי להאכיל נשר לעניים בשני בצורת בשבתות ובימים טובים.\u0004 \u0003ו\u0004כן על שהיו \u0003נותנין פאה\u0004 לעניים מערוגות ה\u0003ירק,\u0004 שאינן חייבות בפאה, וחייבות בתרומות ומעשרות (בעוד שהפאה פטורה מתרומות ומעשרות). \u0003ומיחו בידם\u0004 חכמים. הרי שלדעת ר' יהודה אף הקצירה לפני העומר של אנשי יריחו היתה שלא ברצון חכמים, ושלא כאמור במשנתנו!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה סומך על דיוקה של ברייתא זו, הרי נאמר בה שהיו \u0003ששה\u0004 דברים שעשו אנשי יריחו שלא ברצון חכמים, והרי לא ששה אלא \u0003שבעה\u0004 דברים \u0003הוו\u0004 \u0005[היו]\u0006 מנויים שם, משמע שאין דברי ר' יהודה שבברייתא מדוייקים, ויש לגרוע אחד משבעת הדברים שמנה, \u0003אלא סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן\u0004 מדברי ר' יהודה שבברייתא את ענין ה\u0003קצירה\u0004 לפני העומר שהיתה שלא ברצון חכמים. ונמצא איפוא שאין סתירה בין דברי ר' יהודה שבברייתא לבין דברי משנתנו.","שנינו במשנתנו כי אף לפני העומר \u0003קוצר\u0004 אדם \u0003לשחת ומאכיל לבהמה,\u0004 ונחלקו ר' יהודה ור' שמעון בפרטי היתר זה. ובענין זה מביאים, \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במסכת פאה\u0005]\u0006 בדינם של הדברים הנחשבים כחוצים את השדה לשתים, שיש לתת פאה מכל אחת מהן, \u0003ואלו מפסיקין\u0004 (חוצים) את השדה \u0003ל\u0004ענין נתינת \u0003פאה: הנחל\u0004 העובר בתוך השדה, \u0003והשלולית\u0004 (תעלת מים), \u0003ודרך היחיד\u0004 (שרוחבה ארבע אמות), \u0003ודרך הרבים\u0004 (שרוחבה שש עשרה אמות), \u0003ושביל\u0004 צר, המשמש את \u0003הרבים\u0004 העוברים בו לשדותיהם, \u0003ושביל היחיד הקבוע\u0004 למעבר בו, בין \u0003בימות החמה\u0004 בין \u0003בימות הגשמים, והבור\u0004 (שדה לא מעובדת), \u0003והניר\u0004 (שדה שנחרש ולא נזרע), \u0003ו\u0004כן \u0003זרע\u0004 ממין \u0003אחר\u0004 שנזרע בשדה, כגון שזרע חלקת חיטים בתוך שדה שעורים — כל אחד מאלה נחשב כהפסק,","\u0003ו\u0004נחלקו חכמים בדינו של ה\u0003קוצר\u0004 תבואה \u0003ל\u0004צורך \u0003שחת\u0004 מתוך השדה, האם נחשב הדבר כהפסק בשדה, והרי זה \u0003מפסיק,\u0004 ואלו הם \u0003דברי ר' מאיר. ו\u0004אילו \u0003חכמים אומרים\u0004 ש\u0003אין\u0004 הקוצר לשחת \u0003מפסיק\u0004 את השדה, \u0003אלא אם כן\u0004 הוסיף ו\u0003חרש\u0004 את המקום הקצור, ואזי מפסיק הדבר, כדרך שניר מפסיק את השדה. ואולם הקצירה לשחת כשלעצמה אינה נחשבת כדי לעשות את המקום כשדה בפני עצמו, משום שרואים חכמים את הקצירה לשחת כתחילתה של קצירת השדה.","ובהסבר שיטת ר' מאיר \u0003אמר רבה בר בר חנה,\u0004 \u0003אמר ר' יוחנן: ר' מאיר\u0004 הסבור בדין הפאה שאין הקצירה לשחת נחשבת כתחילת קצירת כל השדה (ולכך היא מפסיקה את השדה) \u0003בשיטת ר' שמעון\u0004 חבירו, שבמשנתנו, \u0003אמרה\u0004 את שיטתו זו, שכן \u0003אמר\u0004 ר' שמעון במשנתנו: \u0003יקצור\u0004 לפני העומר \u0003ויאכיל\u0004 מן התבואה החדשה \u0003אף משהביאה שליש, אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005הוא סבור]\u0006 כי \u0003כל\u0004 שקוצר \u0003לשחת\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 כ\u0003קצירה היא\u0004 נחשבת.","ומוסרים כי כאשר \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבה וקאמר לה להא שמעתא\u0004 \u0005[ואמר את השמועה הזו]\u0006 של ר' יוחנן, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בר הונא לרבא\u0004 ממה ששנינו בברייתא בדין הפסק השדה לענין הפאה: אם חלק מתבואת השדה אבדה שלא על ידי מעשה אדם, כגון ש\u0003אכלה\u0004 ה\u0003חגב,\u0004 וכתוצאה מכך נותר חלק מן השדה ריק מתבואה, או שמקצת מתבואת השדה \u0003קרסמוה נמלים,\u0004 או ש\u0003שברתהו הרוח\u0004 — \u0003הכל מודים\u0004 שאם \u0003חרש\u0004 באותו מקום — הרי זה \u0003מפסיק,\u0004 ואם \u0003לא חרש\u0004 — \u0003אינו מפסיק.\u0004 ויש לדייק בדברי הברייתא: הביטוי \u0003\"הכל מודים\"\u0004 רומז לתנא מסויים החולק בנושא דומה, אף כי כאן הוא מודה, ו\u0003מאן\u0004 \u0005[מיהו]\u0006 תנא זה? ודאי הכוונה היא ל\u0003ר' מאיר,\u0004 ה\u0003סבור שהקוצר לשחת אף בלא חרישה הרי זה מפסיק, ואילו כאן מודה שאין אלה מפסיקים בלא חרישה. ויש להקשות:\u0004","\u0003אי אמרת בשלמא מתניתין\u0004 \u0005[נניח אם אומר אתה\u0006 כי \u0005משנתנו\u0006 במסכת פאה\u0005],\u0006 שאינה מתנה את ההפסק בקצירה לשחת (לשיטת ר' מאיר) בחרישה, מדברת \u0003ב\u0004קצירתה של שחת \u0003שלא הביאה שליש\u0004 (וכשיטת ר' יהודה במשנתנו), בעוד ש\u0003ברייתא\u0004 זו המתנה את ההפסק בחרישה, ולכך דווקא אם \u0003חרש\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מפסיק, ואם \u0003לא חרש\u0004 — \u0003לא\u0004 מפסיק, מדברת \u0003בשהביא שליש,\u0004 נמצא שאין סתירה בין המשנה לברייתא.","\u0003אלא אי אמרת מתניתין נמי\u0004 \u0005[אם אומר אתה\u0006 ש\u0005משנתנו\u0006 במסכת פאה מדברת \u0005גם כן]\u0006 \u0003בשהביא שליש, השתא\u0004 \u0005[מעתה]\u0006 יש מקום להקשות: \u0003ומה התם\u0004 \u0005[שם,\u0006 בקצירה לשחת לענין פאה\u0005]\u0006 ב\u0003קצירה דהתם\u0004 \u0005[של שם],\u0006 שנעשית על ידי אדם, \u0003אמר ר' מאיר\u0004 כי \u0003לא שמה\u0004 (אין היא נחשבת) כתחילת ה\u0003קצירה\u0004 ולכך היא מפסיקה לפאה, \u0003הכא\u0004 \u0005[כאן,\u0006 בברייתא\u0005],\u0006 שאין זה מעשה אדם, אלא מעשה חגבים או רוח — \u0003לא כל שכן\u0004 הוא, לדעת ר' מאיר שאין זו נחשבת כתחילת הקצירה, והרי זה הפסק אף אם לא חרש. ושלא כדברי הברייתא שר' מאיר מודה (\"הכל מודים\") שאין זה נחשב הפסק אלא אם כן חרש!","\u0003אלא\u0004 יש לדחות את הסברו של ר' יוחנן, ולומר כי \u0003ר' מאיר\u0004 שבמסכת פאה האומר שקצירה לשחת נחשבת כהפסק לענין הפאה, \u0003בשיטת ר' יהודה\u0004 שבמשנתנו, \u0003אמרה\u0004 לשיטתו. שכן \u0003אמר\u0004 ר' יהודה במשנתנו: \u0003אימתי\u0004 מותר לקצור מהתבואה החדשה לפני העומר לצורך שחת? רק \u0003בזמן שהתחיל\u0004 לקצור \u0003עד שלא\u0004 (טרם) \u0003הביא\u0004 היבול \u0003שליש\u0004 גידולו, שסבור ר' יהודה שאין זו נחשבת כתחילת הקצירה. ואף ר' מאיר שבמסכת פאה סבור שקצירה לשחת מפסיקה רק בקצירה של דבר שטרם הביא שליש גידולו. \u0003אבל אם התחיל\u0004 לקצור \u0003עד\u0004 (אחר) \u0003שהביא\u0004 כבר \u0003שליש\u0004 גידולו — \u0003אסור\u0004 לקצור לפני העומר.","ומקשים על הסבר זה: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו],\u0006 את \u0003ר' יהודה\u0004 שקצירה לשחת של התבואה שעדיין לא הביאה שליש אינה נחשבת כקצירה, אלא בקצירה \u0003לבהמה,\u0004 ואולם בקצירה \u0003ל\u0004צורך אכילת \u0003אדם\u0004 (כגון לעשות מגרגרי התבואה הללו קליות), \u0003מי\u0004 \u0005[האם]\u0006 גם כן \u0003שמעת ליה\u0004 \u0005[אותו]?!\u0006 שהרי אם תאמר ששיטת ר' יהודה אמורה בין בקצירה לבהמה ובין בקצירה לאדם, \u0003אם כן, הוו להו תלתא תנאי\u0004 \u0005[הרי אלה\u0006 במשנתנו, \u0005שלוש\u0006 דעות \u0005תנאים],\u0006 דעת תנא קמא (המתיר קצירה לשחת רק לבהמה), דעת ר' יהודה (המתיר קצירה לשחת אף לאדם, בטרם הביאה שליש), ודעת ר' שמעון (המתיר לקצור אף לאדם, אפילו לאחר שהביאה שליש)!","\u0003אלא\u0004 יש לדחות אף הסבר זה. ומוסרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל הביא עמו הסבר אחר \u0003ו\u0004\u0003אמר: ר' מאיר\u0004 במסכת פאה \u0003בשיטת ר' עקיבא רבו אמר\u0004 את דבריו, שכן סבור ר' עקיבא ש\u0003אף\u0004 קצירת שחת \u0003לאדם נמי\u0004 \u0005[גם כן]\u0006 \u0003לא הויא\u0004 \u0005[אין היא]\u0006 נחשבת כתחילת \u0003ה\u0004\u0003קצירה.\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת פאה, \u0005בדין הפסק בשדה לחיוב נתינת פאה מכל חלק שבה:\u0006 \u0003המנמר שדה\u0004 (הקוצר מקומות פזורים במקומות שונים בשדה, בהם בשלו פירותיה, ומשאיר מקומות אחרים בלתי קצורים, ונראית השדה על ידי כך כעורו של הנמר בו כתמי צבע פזורים), \u0003ושייר בו\u0004 עדין \u0003קלחים לחים\u0004 (שטרם הבשילו), מה דין השדה לענין הפאה? \u0003ר' עקיבא אומר:\u0004 אין קצירה שכזו נחשבת כתחילת הקצירה הכללית, ולכך כל אחד מהחלקים הלא קצורים נחשב כשדה בפני עצמו, ולכשיחזור ויקצור את הנשארים, הריהו נותן \u0003פאה לכל אחד ואחד\u0004 מהם.","\u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 קצירה זו נחשבת כתחילת הקצירה, ולכך אין היא מפסקת בין החלקים שלא נקצרו, והריהו נותן פאה \u0003מ\u0004מקום \u0003אחד\u0004 שבה \u0003על הכל. ו\u0004בהסבר שיטתו זו של ר' עקיבא \u0003אמר רב יהודה, אמר שמואל: לא חייב ר' עקיבא\u0004 לתת פאה מכל חלק וחלק לעצמו, \u0003אלא במנמר ל\u0004צורך עשיית \u0003קליות\u0004 מגרגרי התבואה הנקצרת, שאין התבואה הנקצרת בשלה עדיין, והריהי כקצירה לשחת. \u0003אבל במנמר\u0004 את השדה \u0003ל\u0004צורך שמירתה ב\u0003אוצר\u0004 (מחסן), שהתבואה הביאה כבר שליש גידולה — \u0003לא\u0004 אמר ר' עקיבא שמפריש פאה מכל חלק וחלק, שכן באופן זה הקצירה הריהי תחילתה של הקצירה הכללית. הרי ששיטת ר' עקיבא היא שאין הקצירה לשחת כשהתבואה עדיין לא הביאה שליש נחשבת תחילת הקצירה הכללית, והרי זו כשיטת ר' מאיר לענין הפסק השדה בקצירה לשחת.","ומקשים על מסורת זו בשמו של שמואל: \u0003איני\u0004 \u0005[האם כך הוא]?\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מחייב היה ר' עקיבא אף במנמר לאוצר,\u0004 כלומר, סבור הוא שהרי זה הפסק אף בקוצר תבואה שהביאה שליש, ושלא כשיטת ר' מאיר המבחינה בין קצירת התבואה שהביאה שליש לקצירת תבואה שלא הביאה שליש!"],["ומתרצים: אין זו קושיה, שכן ר' מאיר \u0003סבר לה כוותיה\u0004 \u0005[סבור הוא כשיטתו,\u0006 של ר' עקיבא רבו\u0005]\u0006 \u0003בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד],\u0006 בדינה של התבואה שלא הביאה עדיין שליש, שאין קצירתה נחשבת כתחילת \u0003הקצירה הכללית,\u0004 \u0003ופליג\u0004 \u0005[וחולק]\u0006 ר' מאיר \u0003עליה\u0004 \u0005[עליו,\u0006 על ר' עקיבא\u0005],\u0006 \u0003בחדא\u0004 \u0005[ב\u0006דבר \u0005אחר],\u0006 בתבואה שהביאה שליש, שבעוד שלר' עקיבא אף בזו אין הקצירה נחשבת כתחילת הקצירה הכללית, ר' מאיר סבור שזו נחשבת קצירה ואפילו כשהיא לצורך בהמה, ולכך אין היא מפסיקה את השדה לענין פאה.","שנינו במשנתנו כי אף שאין קוצרים את התבואה החדשה לפני העומר מכל מקום \u0003קוצרין\u0004 אותה \u0003מפני הנטיעות, ומפני בית האבל, ומפני בית המדרש.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מה מקור הדברים\u0005]?\u0006 ומשיבים: בדין העומר \"...והבאתם את עומר ראשית \u0003קצירכם\u0004 אל הכהן\" (ויקרא כג, י) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והרי זה בא למעט: קצירת העומר היא הקצירה הראשונה לקצירות הרשות (\"קצירכם\") — \u0003ו\u0004אולם היא \u0003לא\u0004 הקצירה הקודמת ל\u0003קציר מצוה,\u0004 כגון אלה המנויים במשנתנו, שלשם מצוה נקצרת התבואה אף לפני העומר.","\u0003ו\u0004עוד שנינו במשנתנו כי אף באלה שהותרה הקצירה בהם לפני העומר, \u0003לא יעשה\u0004 את התבואה הנקצרת \u0003כריכות, אבל מניחן צבתים.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: אף שהתירו חכמים את הקצירה, מכל מקום כל \u0003כמה\u0004 ש\u0003אפשר\u0004 להימנע מטירחת יתר, וכגון עשיית כריכות, \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים].\u0006","ובדיני מצות העומר לכתחילה, שנינו במשנתנו שלוש הלכות: \u0003מצות העומר\u0004 הראויה היא \u0003להביא\u0004 את התבואה החדשה \u0003מן הקמה\u0004 העומדת בשדה. ואולם אם לא מצא קמה לקצור, וכגון שכבר נקצר הכל — יביא מן העומרים (אלומות קצורות וכרוכות מן התבואה החדשה); מצות העומר הראויה היא שיביאו מן התבואה הלחה. ואולם אם לא מצא מן הלח — יביא מן היבש; מצות העומר הראויה היא להביאו מן הנקצר בלילה, במוצאי יום טוב ראשון של פסח. ואולם אם לא נקצר העומר בלילה — יביא מן הנקצר ביום. ועוד שנינו במשנתנו כי קיום מצות העומר דוחה את השבת. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר במצות העומר \u0003\"ואם תקריב מנחת בכורים\u0004 לה' אביב קלוי באש גרש כרמל תקריב את מנחת בכוריך\" (ויקרא ב, יד). ודנים בכתוב זה: \u0003מה תלמוד לומר\u0004 (מה מלמדנו האמור) בתחילת הפסוק \"ואם תקריב מנחת בכוריך\", שהרי כדבר הזה נאמר בסוף הפסוק \"תקריב את מנחת בכוריך\"? — \u0003לפי שמצות העומר\u0004 לכתחילה היא \u0003להביא\u0004 אותו \u0003מן הקמה\u0004 דווקא, ויתור הכתוב מלמדנו על כך. \u0003מנין\u0004 לנו \u0003שאם לא מצא\u0004 להביא עומר \u0003מן הקמה,\u0004 ש\u0003יביא מן העומרין?\u0004 — \u0003תלמוד לומר \"תקריב\u0004 את מנחת בכוריך\" — לרבות אף את הבא מן העומרים.","\u0003דבר אחר\u0004 (דרשה אחרת מן הכתוב הזה): מה מלמדנו הכתוב \u0003\"תקריב\u0004 את מנחת בכוריך\"? — \u0003לפי ש\u0004ה\u0003מצוה\u0004 היא \u0003להביא\u0004 את העומר \u0003מן\u0004 יבול התבואה \u0003הלח\u0004 דווקא, \u0003ומנין\u0004 לנו \u0003שאם לא מצא\u0004 להביא עומר \u0003מן הלח,\u0004 ש\u0003יביא מן היבש?\u0004 לכך \u0003תלמוד לומר \"תקריב\u0004 את מנחת בכוריך\" — לרבות אף את הבא מן היבש. \u0003דבר אחר:\u0004 מה מלמדנו הכתוב \u0003\"תקריב\u0004 את מנחת בכוריך\"? — \u0003לפי שמצותו\u0004 הראויה של הקרב לעומר \u0003לקצור\u0004 אותו \u0003בלילה\u0004 של מוצאי יום טוב הראשון של פסח, בליל ט\"ז בניסן. \u0003מנין\u0004 לנו \u0003שאם\u0004 לא \u0003נקצר\u0004 אלא \u0003ביום\u0004 שהוא \u0003כשר\u0004 להבאה? לכך \u0003תלמוד לומר \"תקריב\u0004 את מנחת בכוריך\" — לרבות אף את הנקצר ביום.","\u0003ו\u0004עוד מדרשות הכתוב הזה, לענין ארבע הלכות שבו: מנין שהוא \u0003דוחה את\u0004 איסור מלאכת \u0003השבת\u0004 ומתירו בעשייה; \u0003תלמוד לומר \"תקריב\".\u0004 ועוד אתה לומד מלשון זו: \u0003\"תקריב\"\u0004 — שיש להביאו ב\u0003כל\u0004 אופן \u0003שהוא,\u0004 ואף מן העומרים (אם אין בנמצא קמה לצורך קצירת העומר); \u0003\"תקריב\"\u0004 — שיש להביאו \u0003מכל מקום\u0004 שהוא (אם לא נמצא במקום הקרוב לירושלים), ואף מהמקום המרוחק מירושלים; \u0003\"תקריב\"\u0004 — \u0003ואפילו בשבת; \"תקריב\"\u0004 — \u0003ואפילו בטומאה,\u0004 שהריהו דוחה את הטומאה.","שנינו במשנתנו שאף שמצות העומר היא להיקצר בלילה, ואולם אם \u0003נקצר ביום\u0004 — הריהו \u0003כשר.\u0004 ושואלים על כך: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת מגילה\u0005]:\u0006 \u0003כל הלילה\u0004 של ליל ט\"ז בניסן \u0003כשר לקצירת העומר, ולהקטיר\u0004 (לשרוף על המזבח) את ה\u0003חלבים\u0004 של הקרבנות שנזרק דמם ביום, \u0003ו\u0004את ה\u0003אברים\u0004 של קרבן עולה. \u0003זה הכלל:\u0004 כל \u0003דבר ש\u0004זמן קיום \u0003מצותו כל היום\u0004 — הריהו \u0003כשר כל היום,\u0004 וכיוצא בו, כל \u0003דבר\u0004 מצוה \u0003ש\u0004זמן \u0003מצותו בלילה\u0004 — הריהו \u0003כשר כל הלילה.\u0004","ויש לדייק בדברי משנה זו: \u0003קתני\u0004 \u0005[שנה]\u0006 בה דין דבר שמצוותו ב\u0003לילה דומיא\u0004 \u0005[בדומה]\u0006 לדבר שמצוותו ב\u0003יום,\u0004 ומעתה כיון שהושוו זה לזה, נלמד עוד מהשוואתם: \u0003מה\u0004 (כמו) שדברי מצוה של \u0003יום\u0004 הריהם כשרים דווקא אם נעשו ביום, ואם נעשו \u0003בלילה\u0004 — \u0003לא\u0004 התקיימה מצוותם, \u0003אף\u0004 בדברי מצוה של \u0003לילה\u0004 שנעשו \u0003ביום\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 התקיימה מצוותם. ושלא כמשנתנו האומרת שהנקצר ביום הריהו כשר למצות העומר!","\u0003אמר רבה: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן ניתן לומר \u0003ש\u0004\u0003הא\u0004 \u0005[\u0006משנתנו \u0005זו]\u0006 האומרת שמצוה של לילה, כגון קצירת העומר, כשרה אם נעשתה ביום — הריהי כשיטת \u0003רבי, ו\u0004אילו \u0003הא\u0004 \u0005[זו,\u0006 המשנה במסכת מגילה\u0005]\u0006 שדבר מצוה של לילה שנעשה ביום פסול — הריהי כשיטת \u0003ר' אלעזר בר' שמעון.\u0004 והיכן נחלקו? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה עומד ומקריב\u0004 את \u0003מנחת העומר ו\u0004בתוך כך \u0003נטמאת\u0004 המנחה בידו, מה יעשה? \u0003אם יש\u0004 אפשרות להביא את העומר מתבואה \u0003אחרת\u0004 מן החדש — \u0003אומר לו\u0004 החכם למביא העומר: \u0003\"הבא\u0004 את מנחת העומר ה\u0003אחרת תחתיה\u0004 (במקומה)\". \u0003ואם לאו\u0004 \u0005[אין]\u0006 אפשרות להביא את העומר מתבואה אחרת — \u0003אומר לו: \"הוי\u0004 (היה) \u0003פקח, ושתוק,\u0004 והבא אותה כפי שהיא\" (שכן טומאה דחויה בקרבן ציבור, כעומר), אלו \u0003דברי רבי.\u0004","ואילו \u0003ר' אלעזר בר' שמעון אומר: בין כך\u0004 כשאין אפשרות להביא מנחת עומר אחרת, \u0003ובין כך\u0004 כשיש אפשרות להביא מנחת עומר אחרת, \u0003אומר לו: \"הוי פקח, ושתוק\",\u0004 שהרי אף כשיש תבואה אחרת — אין היא כשרה להבאה לעומר, שהרי לא נקצרה בלילה כמצוות העומר, וכלל הוא: \u0003שכל העומר שנקצר שלא כמצותו\u0004 — \u0003פסול\u0004 להבאה. הרי שנחלקו בדבר זה רבי ור' אלעזר בר' שמעון.","למעלה הובאו דברי ר' אלעזר בנו של ר' שמעון הסבור שכל שלא נקצרה התבואה בלילה של מוצאי יום טוב ראשון של פסח, אינה כשרה לעומר. ובענין זה \u0003אמר רבה בר בר חנה, אמר ר' יוחנן: ר' אלעזר בר' שמעון בשיטת ר' עקיבא רבו של אביו אמרה\u0004 לשיטתו זו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003כלל אמר ר' עקיבא: כל מלאכה\u0004 האסורה בשבת, \u0003ש\u0004היה \u0003אפשר לו לעשותה מערב שבת\u0004 — גם אם יש בה מצוה, \u0003אינה דוחה את השבת,\u0004 שאין השבת נדחית מפני מצוה שזמנה בשבת אלא כאשר אי אפשר לעשות את ההכנה לה קודם לכן.","\u0003ו\u0004כמו כן \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 ר' אלעזר בנו של ר' שמעון \u0003כ\u0004שיטת \u0003ר' ישמעאל,\u0004 ש\u0003אומר\u0004 כי \u0003קצירת העומר,\u0004 בהיותה \u0003מצוה,\u0004 הריהי דוחה את השבת. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 נאמר בדין השנה השביעית \"בחריש ובקציר תשבות\" (שמות לד, כא), ולכאורה אין צורך בכתוב זה, שהרי נאמר מקרא מלא ומפורט \"שדך לא תזרע וכרמך לא תזמור את ספיח קצירך לא תקצור...\" (ויקרא כה, ד— ה). אלא \u0003ר' ישמעאל אומר:\u0004 בא כתוב זה ללמדנו לענין שבת, ובאופן זה: \u0003מה חריש\u0004 האסור בשבת אינו אלא \u0003של\u0004 \u0003רשות\u0004 (שהרי אין חריש של מצוה) — \u0003אף קציר\u0004 האסור בשבת אינו אלא זה של \u0003רשות, יצא\u0004 מכלל איסור שבת \u0003קציר העומר שהיא\u0004 של \u0003מצוה. ו\u0004מעתה נאמר:","\u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שהעומר ה\u0003נקצר שלא כמצותו,\u0004 כגון זה שנקצר ביום \u0003כשר\u0004 להבאה, \u0003אמאי דחי\u0004 \u0005[מדוע\u0006 אם כן \u0005דוחה]\u0006 קציר העומר את איסור ה\u0003שבת\u0004 (כדעת ר' ישמעאל), \u0003נקצריה\u0004 \u0005[שיקצרנו]\u0006 \u0003מערב שבת,\u0004 והרי זו איפוא מלאכה שאפשר לעשותה בערב שבת, שאינה דוחה את השבת! \u0003אלא מדדחי\u0004 \u0005[מ\u0006תוך \u0005ש\u0006קציר העומר \u0005דוחה]\u0006 את ה\u0003שבת, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאם \u0003נקצר שלא כמצותו\u0004 — \u0003פסול.\u0004 ונמצא איפוא ששיטת ר' אלעזר בנו של ר' שמעון הריהי כשיטת ר' עקיבא רבו של ר' שמעון אביו (וכשיטת ר' ישמעאל).","ותוהים: \u0003ו\u0004האם \u0003רבי,\u0004 החולק על ר' אלעזר בנו של ר' שמעון, \u0003לאו תלמידיה\u0004 \u0005[לא תלמידו]\u0006 של \u0003ר' שמעון\u0004 (שהוא תלמידו של ר' עקיבא) \u0003הוא?\u0004 וכשם שר' אלעזר בנו של ר' שמעון הולך בשיטת ר' עקיבא (רבו של ר' שמעון), אף דעת רבי החולק על ר' אלעזר בר' שמעון \u0003צריכה להיות כשיטת ר' עקיבא. ואף רבי סבור שכל מצוה שאפשר לעשותה מערב שבת —\u0004 אינה דוחה את השבת, ואם העומר הנקצר ביום כשר לדעת רבי אף שהוא שלא כמצוותו — אם כן יקצרנו מערב שבת ולא ידחה את השבת!","\u0003ו\u0004מנין לנו שרבי הוא תלמידו של ר' שמעון, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: כשהיינו למדין תורה אצל ר' שמעון ב\u0004ישוב \u0003תקוע, היינו\u0004 תלמידיו \u0003מעלין\u0004 (מביאים) \u0003לו\u0004 בשבת \u0003שמן\u0004 לסוך בו את גופו, \u0003ואלונטית\u0004 לנגב בה. וכיצד היינו מעבירים אותם? שלא כדרך הרגילה, אלא היינו מעלים אותם \u0003מחצר\u0004 הבית \u0003לגג\u0004 הבית, \u0003ומגג\u0004 הבית \u0003לקרפיף\u0004 (החצר האחורית של הבית), \u0003ומקרפיף\u0004 בית זה \u0003לקרפיף\u0004 בית \u0003אחר,\u0004 ובאופן זה היינו מעבירים אותם \u0003עד שאנו מגיעין למעיין שאנו רוחצין בו!\u0004","ומשיבים: אכן רבי הוא תלמידו של ר' שמעון, וראוי היה איפוא שילך כשיטת ר' עקיבא רבו של ר' שמעון, ואולם רבי \u0003סבר לה כאידך\u0004 \u0005[סבור הוא כ\u0006ברייתא \u0005אחרת]\u0006 של \u0003ר' שמעון. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון: בא וראה כמה חביבה\u0004 היא קיום \u0003מצוה בשעתה, שהרי הקטר\u0004 (הקרבת) ה\u0003חלבים ואברים\u0004 של קרבנות התמידים והמוספים של \u0003שבת\u0004 \u0003כשרים כל הלילה,\u0004 ואפשר היה איפוא להמתין לצאת השבת, ולהקריבם במוצאי השבת וללא עשיית מלאכה בשבת, \u0003ו\u0004בכל זאת לא נהגו כן במקדש, ש\u0003לא היה\u0004 הכהן המקריב אותם \u0003ממתין להן\u0004 מלהקריבם \u0003עד שתחשך\u0004 (שתצא השבת), אלא היה מקריבם בשבת עצמה, משום חביבותה של המצוה המקויימת בשעתה. ואף בקציר העומר, אף שהנקצר ביום הריהו כשר, ואפשר היה לקצור את העומר לפני השבת בכל זאת קציר העומר דוחה את השבת, משום חביבות קיום המצוה בשעתה."],["","","","","","","","","","","","","","","","","","","","","","","ושואלים על הסבר זה בשיטת רבי: \u0003ו\u0004האם \u0003ר' אלעזר בר' שמעון לא שמיע ליה\u0004 \u0005[לא שמע\u0006 קביעה עקרונית \u0005זו]\u0006 של אביו שחביבה היא המצוה המקויימת בשעתה, ולכך אין ממתינים במצוה שיש בה מלאכה בשבת למוצאי שבת?! \u0003אלא שאני התם\u0004 \u0005[שונה\u0006 הוא הענין \u0005שם,\u0006 בהקטר חלבים ואברים בשבת\u0005]\u0006 שהותרה מלאכה זו בשבת, \u0003שהרי\u0004 כבר \u0003דחתה\u0004 ה\u0003שחיטה\u0004 של הקרבן (שהיא תחילת ההקרבה) \u0003את השבת,\u0004 והקטרת החלבים והאברים הבאה שלאחר מכן, היא כהשלמה להקרבה זו. ואין ללמוד מכאן להתיר בשבת את קצירת העומר כיון שאפשר לה שתיעשה שלא בחילול שבת ולא היתה מלאכה קודמת לה שנעשתה כבר בשבת. ושואלים: \u0003ו\u0004הלא אף \u0003ל\u0004שיטת \u0003רבי הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש להבחין בין מצות הקטר חלבים ואברים לבין מצות קצירת העומר, שהרי בהקטר חלבים ואברים כבר \u0003דחתה שחיטה את השבת,\u0004 מה שאין כן בקציר העומר! \u0003אלא\u0004 צריכים לומר הסבר אחר בשיטת רבי: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רבי\u0004 כי \u0003קצירת העומר לא דחיא\u0004 \u0005[אינה דוחה]\u0006 את ה\u0003שבת,\u0004 ושלא כשיטת ר' ישמעאל, ולכך אין להביא ראיה מכאן (כסברת ר' אלעזר בנו של ר' שמעון החולק על רבי) שקציר העומר שנעשה שלא בזמנו פסול. ולדעת רבי קציר העומר שנעשה שלא בזמנו כשר. \u0003ו\u0004מקשים על כך: והאם סבור רבי שקצירת העומר \u0003לא\u0004 דוחה את השבת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה בתחילת פרקנו\u0005]\u0006 במחלוקתם של \u0005ר' ישמעאל וחכמים כאשר חל ט\"ז בניסן (זמן קציר העומר) בשבת, שלדעת ר' ישמעאל ממעטים את הכמות הנקצרת לכדי שלוש סאים בלבד (בעוד שביום חול קוצרים חמש סאים),\u0006 \u0003ו\u0004\u0005אילו\u0006 \u0003חכמים אומרים\u0004 כי \u0003אחד\u0004 ב\u0003שבת ואחד\u0004 הנעשה ב\u0003חול\u0004 — \u0003משלש\u0004 סאים תבואה נקצרת \u0003היה\u0004 העומר \u0003בא.\u0004 הרי שאף חכמים, החולקים על ר' ישמעאל (במספר הסאים הנקצרים בחול) סבורים שהעומר נקצר בשבת, ואף רבי לכאורה סבור כן! ומתרצים: משנה זו הריהי ש\u0003לא כ\u0004שיטת \u0003רבי,\u0004 שהוא סבור שאין קציר העומר דוחה את השבת. ומוסיפים ושואלים מן האמור עוד באותה משנה שר' חנינא סגן הכהנים אומר שהעומר היה נקצר בשבת על ידי אדם אחד, ובמגל אחד, וניתנת התבואה הנקצרת לתוך קופה אחת, \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 כי \u0003אחד\u0004 קציר העומר הנעשה ב\u0003שבת ואחד\u0004 קציר העומר הנעשה ב\u0003חול\u0004 — נעשה \u0003בשלשה\u0004 אנשים, וניתנת התבואה הנקצרת \u0003בשלש קופות ו\u0004מתבצע הקציר \u0003בשלש מגלות.\u0004 הרי שלדעת הכל העומר נקצר בשבת, ואף רבי לכאורה סבור כן! ומשיבים: אף דברי משנה זו הם ש\u0003לא כ\u0004שיטת \u0003רבי,\u0004 שהוא סבור שאין קציר העומר דוחה את השבת. \u0003ו\u0004מוסיפים ושואלים ממה ששנינו עוד לאחר מכן (לעיל מנחות סה,א), בדרך בה היה נקצר העומר בשבת, שמלבד השאלות הקבועות שהיו הקוצרים שואלים את כל בני העיירות שהתקבצו לאותו מקום בו נקצר העומר, \u0003בשבת יאמר להם\u0004 גם את השאלה \"האם אקצור ב\u0003שבת זו?\".\u0004 והרי איפוא שקציר העומר דוחה את השבת, וכן היא לכאורה גם דעת רבי! ודוחים שוב: אף משנה זו הריהי ש\u0003לא כ\u0004שיטת \u0003רבי,\u0004 שהוא סבור שאין קציר העומר דוחה את השבת. ומקשים עוד ממה ששנינו במשנתנו, שאם \u0003נקצר\u0004 העומר \u0003ביום\u0004 — הריהו \u0003כשר, ודוחה את השבת.\u0004 ויש לדייק בדברים הללו: \u0003מאן\u0004 \u0005[מיהו]\u0006 התנא ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 בדין העומר ש\u0003נקצר ביום\u0004 שהוא \u0003כשר?\u0004 הלוא זה \u0003רבי,\u0004 החולק על ר' אלעזר בנו של ר' שמעון, \u0003וקתני\u0004 \u0005[ושנה]\u0006 עוד התנא במשנתנו בענין העומר \u0003ודוחה את השבת, מאי לאו\u0004 \u0005[האם לא]\u0006 מוסבים דברים אלה אף לענין ה\u0003קצירה,\u0004 שקצירת העומר דוחה את השבת, הרי \u0003שאף רבי סבור שקציר העומר דוחה את השבת! ודוחים:\u0004 \u0003לא,\u0004 אין זו ראיה, שכן ניתן לומר שדחיית השבת במשנתנו היא \u0003ל\u0004ענין \u0003ה\u0004\u0003הקרבה\u0004 של העומר, אך לא לענין קצירתו. ושואלים על תירוץ זה: לדעתך, רבי סבור שדחיית השבת בעומר היא דווקא בהקרבתו, \u0003אבל ל\u0004ענין ה\u0003קצירה\u0004 של העומר בשבת סבור רבי שהיא \u0003לא\u0004 דוחה את השבת? \u0003ו\u0004אולם יש להקשות על כך, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר בפסוק החותם את פרשת המועדות שבפרשת אמור \u0003\"וידבר משה את מעדי ה'\u0004 אל בני ישראל\" (ויקרא כג, מד), ויש לשאול: \u0003מה תלמוד לומר\u0004 (איזה לימוד בא להשמיענו) כתוב זה? שהרי כבר נאמר בפסוקים הפותחים את פרשת המועדים \"וידבר ה' אל משה לאמר. דבר אל בני ישראל ואמרת אליהם מועדי ה' אשר תקראו אותם מקראי קודש אלה הם מועדי\" (שם א— ב). אלא בא כתוב זה ללמדנו: \u0003לפי שלא למדנו\u0004 עד כה \u0003אלא ל\u0004קרבנות ה\u0003תמיד ו\u0004ה\u0003פסח\u0004 בלבד שהם דוחים את השבת ואת הטומאה, \u0003ש\u0004כן \u0003נאמר בהן\u0004 הלשון \u0003\"במועדו\"\u0004 (בקרבן התמיד: \"צו את בני ישראל ואמרת אליהם את קרבני לחמי לאשי ריח ניחוחי תשמרו להקריב לי במועדו. ואמרת להם זה האשה אשר תקריבו לה' כבשים בני שנה תמימים שנים ליום עולה תמיד\", במדבר כח, ב— ג. בקרבן הפסח: \"ויעשו בני ישראל את הפסח במועדו\". שם ט, ב). והלשון \u0003\"במועדו\"\u0004 באה להורות שקרבנות אלה קרבים תמיד במועד הקבוע להם, \u0003ואפילו ב\u0004יום \u0003ה\u0004\u0003שבת,\u0004 שדוחה הקרבתם את איסורי השבת. ועוד באה לשון \u0003\"במועדו\"\u0004 להורות שקרבנות אלה קרבים תמיד במועד הקבוע להם, \u0003ואפילו בטומאה.\u0004 ויש עוד לדון: שכך הוא הדין בקרבן תמיד ופסח שמענו, ואולם אף ב\u0003שאר קרבנות הצבור מנין\u0004 לנו? לכך \u0003תלמוד לומר\u0004 בחתימת פרשת קרבנות המועדים שבפרשת פינחס, שקרבנות ציבור הם אלה: \u0003\"אלה תעשו לה' במועדיכם\"\u0004 (שם כט, לט), ובאה המלה \"במועדיכם\" להורות שהם קרבים אף בשבת ואף בטומאה.","","","","","ודנים עוד: ו\u0003מנין\u0004 לנו שיש \u0003לרבות\u0004 לענין דחיית השבת ודחיית הטומאה אף את ה\u0003עומר\u0004 הקרב בפסח, \u0003ו\u0004כן את קרבן הכבש \u0003הקרב עמו,\u0004 וכן את \u0003שתי הלחם\u0004 הקרבים בשבועות, \u0003ו\u0004את קרבן שני הכבשים \u0003הקרב עמהן,\u0004 שאינם נזכרים בפרשה זו? לכך \u0003תלמוד לומר\u0004 בחתימת פרשת המועדות שבפרשת אמור (שבה נאמרו בין שאר קרבנות המועדים אף העומר וקרבנותיו, שם פסוק יא— יג, ושתי הלחם וקרבנותיהם, שם יז— כ) \u0003\"וידבר משה את מעדי ה'\u0004 אל בני ישראל\" — \u0003הכתוב קבע מועד לכולן,\u0004 ומכאן שאף הם דוחים את השבת ואת הטומאה. ומעתה יש לברר: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין מענייני העומר\u0005]\u0006 אמר רבי בברייתא זו שהעומר דוחה את השבת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא \u0003להקרבה\u0004 של העומר, ובדומה לכך הקרבת שתי הלחם — יש להקשות על כך: וכי \u0003שתי הלחם בני הקרבה נינהו\u0004 \u0005[הם]?\u0006 והרי אין מקריבים אותם! \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור מאליו\u0005]\u0006 שהכוונה בשתי הלחם היא \u0003ל\u0004ענין \u0003טחינה\u0004 של הקמח הבא לשתי הלחם, \u0003ו\u0004כן ל\u0003הרקדה\u0004 (ניפוי הקמח), שהן מלאכות שיכול לעשותן אף מערב שבת, ובכל זאת סבור רבי שהן דוחות את השבת. \u0003ו\u0004מכאן נסיק כי אף \u0003דכותה\u0004 \u0005[כיוצא בה],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003עומר\u0004 הכוונה אינה להקרבתו בשבת, אלא \u0003ל\u0004ענין ה\u0003קצירה, ו\u0004לדעת רבי \u0003קא דחי\u0004 \u0005[הוא דוחה]\u0006 \u0003את השבת,\u0004 והרי איפוא שסבור רבי שקציר העומר דוחה את השבת! ודוחים: לא כך יש לפרש את דברי רבי שבברייתא, \u0003אלא\u0004 באופן אחר, ומה שאמר רבי שה\u0003עומר\u0004 דוחה את השבת, אין הכוונה לענין הקצירה אלא \u0003ל\u0004ענין ה\u0003הקרבה\u0004 של העומר, \u0003ו\u0004מה שאמר רבי ב\u0003שתי הלחם\u0004 שהם דוחים את השבת — אין הכוונה לטחינה ולהרקדה, אלא \u0003לאפיה, ו\u0004הותרה האפיה בשבת, משום שאין זו מלאכה שיכולה להיעשות מערב שבת, כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רבי\u0004 שה\u0003תנור\u0004 בו נאפים שתי הלחם הוא ש\u0003מקדש\u0004 אותם באפיה, ולכן אי אפשר לאפותם מערב שבת, שכן \u0003אי אפי לה\u0004 \u0005[אם אופה אותה,\u0006 את שתי הלחם\u0005]\u0006 \u0003מאתמול\u0004 — הרי \u0003איפסילה\u0004 \u0005[נפסלה]\u0006 \u0003לה\u0004 בכך \u0003בלינה. ו\u0004שואלים על כך: האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003רבי\u0004 כי ה\u0003תנור\u0004 הוא ש\u0003מקדש\u0004 את שתי הלחם? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כבשי עצרת\u0004 הבאים עם שתי הלחם בחג השבועות, \u0003אין מקדשין את הלחם אלא בשחיטה. כיצד\u0004 (באיזה אופן) בשחיטת הכבשים מתקדש הלחם? אם \u0003שחטן\u0004 את כבשי העצרת \u0003לשמן\u0004 כדין, \u0003ו\u0004כן גם \u0003זרק\u0004 את \u0003דמן\u0004 על המזבח \u0003לשמן\u0004 כדינם הראוי — בכך \u0003קדש הלחם.\u0004 ואולם אם \u0003שחטן שלא לשמן, ו\u0004כן גם \u0003זרק\u0004 את \u0003דמן שלא לשמן\u0004 — \u0003לא קדש הלחם\u0004 בשחיטת הכבשים. ואם \u0003שחטן\u0004 \u0003לשמן, ו\u0004אולם \u0003זרק\u0004 את \u0003דמן שלא לשמן\u0004 — נחלקו בכך חכמים, שיש האומר כי \u0003הלחם קדוש ואינו קדוש,\u0004 והם \u0003דברי רבי.\u0004 ואילו \u0003ר' אלעזר בר' שמעון אומר\u0004 כי \u0003לעולם\u0004 שתי הלחם \u0003אינו קדוש\u0004 (מתקדש) \u0003עד ש\u0004גם \u0003ישחוט\u0004 את הכבשים \u0003לשמן ו\u0004גם \u0003יזרוק\u0004 את \u0003דמן לשמן.\u0004 הרי שסבור רבי שלא התנור הוא שמקדש את שתי הלחם! \u0003אמר רב נחמן בר יצחק\u0004 בתשובה לשאלה זו: לדעת רבי אכן התנור הוא המקדש את שתי הלחם, ואולם כוונת דברי רבי בבריייתא לענין קדושת הלחם (\"קדש הלחם\", \"לא קדש הלחם\", \"קדוש ואינו קדוש\") אינם לעצם קדושת הלחם, שכן כבר התקדשו באפייתם, אלא \u0003הוקבעו\u0004 או \u0003לא הוקבעו קא אמר\u0004 \u0005[אומר הוא]\u0006 רבי. שכוונתו היא לענין היקבעותם של שתי הלחם לכבשים, אם יכול הוא לייעד את הלחם לקרבן אחר אם לאו (שאם נשחטו הכבשים ונזרק דמם כדין — אין הוא יכול לשנות את יעוד הלחם, ואם לא נשחטו ולא נזרק דמם כדין — יכול הוא לשנות, ואם נשחטו הכבשים כדין ואולם נזרק דמם שלא כדין — הרי זה תלוי במחלוקת החכמים). \u0003ואלו\u0004 הן ה\u0003מנחות\u0004 ה\u0003נקמצות\u0004 על ידי הכהן, \u0003ושיריהן\u0004 שנותרו לאחר שניטל מהן הקומץ נאכלים בעזרה \u0003לכהנים:\u0004 חמש מנחות נדבה של זכר יחיד מישראל, שהן: \u0003מנחת הסלת\u0004 (ויקרא ב, א— ג); \u0003ו\u0004מנחת \u0003המחבת\u0004 (שם ה— ו); \u0003ו\u0004מנחת \u0003המרחשת\u0004 (שם ז); \u0003ו\u0004מנחת מאפה תנור, והיא שני מינים: \u0003ה\u0004באה כולה \u0003חלות, וה\u0004באה כולה \u0003רקיקין\u0004 (שם ד), \u0003מנחת גוים\u0004 (שהתנדבו אותן גוים), \u0003ו\u0004כן \u0003מנחת נשים. ו\u0004נוסף עליהן מנחות חובה, אם של ציבור, שהיא \u0003מנחת העומר\u0004 הבאה בט\"ז בניסן מן השעורים, \u0003ו\u0004אם של יחיד, שהיא \u0003מנחת חוטא\u0004 שמביא אדם מישראל שחטא בשבועת העדות או בשבועת ביטוי או בטומאת מקדש וקדשיו, שאם הוא עני ביותר הריהו מביא עשירית האיפה סולת (שם ה, יא— יב), \u0003ו\u0004כן \u0003מנחת קנאות\u0004 (מנחת סוטה. במדבר ה, יב— טו). \u0003ר' שמעון אומר: מנחת חוטא של כהנים,\u0004 אף שאין שייריה נאכלים על ידי הכהנים, שכן כל המנחה כולה עולה כליל על המזבח (\"וכל מנחת כהן כליל תהיה לא תאכל\", ויקרא ו, טז), הריהי \u0003נקמצת, ו\u0004ה\u0003קומץ קרב\u0004 על המזבח \u0003לעצמו,\u0004 \u0003ו\u0004ה\u0003שירים\u0004 שאינם נאכלים, \u0003קריבים\u0004 על המזבח \u0003לעצמן.\u0004 \u0003אמר רב פפא\u0004 ככלל: \u0003כל היכא דתנן\u0004 \u0005[כל מקום\u0006 \u0005ששנינו\u0006 במשנה\u0005]\u0006 לשון \"ואלו מנחות\" — ברשימה זו \u0003עשר\u0004 מנחות \u0003תנן\u0004 \u0005[שנינו].\u0006 ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]\u0006 בכך? הרי אפשר לספור ולהיווכח שהן עשר! ומשיבים: כלל זה בא ללמד, שהן עשר בלבד ולא יותר, ו\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שהנודר להביא מנחת מאפה — יכול להביאה בעשר חלות, או בעשרה רקיקים. ואם רצה להביא \u0003מחצה\u0004 (חמש מהן) \u0003חלות ומחצה\u0004 (וחמש אחרות) \u0003רקיקין\u0004 — \u0003יביא.\u0004 ונמצא איפוא כי לשיטה זו יש אחת עשרה מנחות. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 רב פפא \u0005משמיע לנו]\u0006 ש\u0003לא\u0004 כך סבורה משנתנו, אלא שמביאים \u0003עשרה לחמים רק מאותו סוג, ומשום כך אין כלל המנחות אלא עשר בלבד.\u0004 \u0003ו\u0004עוד שנינו במשנתנו כי \u0003שיריהן\u0004 של כל המנחות הנקמצות ניתנים \u0003לכהנים\u0004 לאכילה. ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הדין? ותוהים על עצם השאלה: מה מקום לשאלה זו, שהרי מהמנחות המנויות במשנתנו, זו \u0003דכתיבא\u0004 \u0005[שנאמר]\u0006 בה במפורש בתורה ששייריה ניתנים לכהנים לאכילה (כגון מנחות הנדבה של יחיד) — הלא \u0003כתיבא\u0004 \u0005[אמורה],\u0006 \u0003ו\u0004אף זו ש\u0003לא כתיבא\u0004 \u0005[לא נאמרה]\u0006 בה במפורש הלכה זו — הרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בתחילת פרשת המנחה, בלשון כוללת: \u0003\"וזאת\u0004 \u0003תורת המנחה הקרב אתה בני אהרן\u0004 לפני ה' אל פני המזבח. והרים ממנו בקומצו מסולת המנחה ומשמנה ואת כל הלבונה אשר על המנחה והקטיר המזבח ריח ניחוח אזכרתה לה'. \u0003והנותרת ממנה יאכלו אהרן ובניו\u0004 מצות תאכל במקום קדוש בחצר אהל מועד יאכלוה\" (ויקרא ו, ז— ט), ולמדנו מכאן דין כולל (\"וזאת תורת\") ששיירי המנחה נאכלים לכהנים לאחר הקמיצה! אלא מסבירים את השאלה: במנחה שהיא \u0003באה\u0004 מן ה\u0003חיטין\u0004 — \u0003לא קמיבעיא לן\u0004 \u0005[לא נשאלה לנו]\u0006 מה המקור ששייריה ניתנים לכהנים, שנאמר בה \"הנותרת ממנה יאכלו אהרן ובניו\", ואולם \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה הרי זה במנחה \u0003ה\u0004\u0003באה\u0004 מן ה\u0003שעורין\u0004 (מנחת העומר, ומנחת הסוטה), מה המקור ששייריהן של אלה ניתנים לכהנים. ומקשים: המנחה ה\u0003באה\u0004 מן ה\u0003שעורין נמי\u0004 \u0005[גם כן]\u0006 פשוט ששייריה ניתנים לכהנים, שכן \u0003מ\u0004תוך שהיא \u0003נקמצת\u0004 (כנאמר בתורה בדינה) — אף \u0003שיריה לכהנים!\u0004 ומסבירים: אכן \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים]\u0006 שבמשנתנו, המונים את המנחות הנקמצות, שכולן שייריהן נאכלים לכהנים — \u0003לא קא מיבעיא לן\u0004 \u0005[לא נשאלה לנו]\u0006 שאלה זו, ואולם \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה הרי זה \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 כי \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מנחה דמיקמצא\u0004 \u0005[שנקמצת]\u0006 \u0003ו\u0004אולם היא (כלומר, שייריה) \u0003לא מיתאכלא\u0004 \u0005[לא נאכלת],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003ר' שמעון אומר\u0004 ש\u0003מנחת חוטא של כהנים נקמצת,\u0004 אבל שייריה אינם נאכלים לכהנים, אלא קריבים על המזבח, ש\u0003הקומץ קרב בעצמו, והשירים קריבין בעצמן,\u0004 ועל כך היתה השאלה \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שלשיטת ר' שמעון השיריים של המנחות הבאות מן השעורים נאכלות לכהנים, שהרי לשיטתו יש מנחה נקמצת ואינה נאכלת? ומשיבים: המקור הריהו כדרך ש\u0003אמר חזקיה:\u0004 ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדיני המנחות הניתנות לכהנים (לאכילה): \u0003\"וכל מנחה בלולה בשמן וחרבה לכל בני אהרן תהיה\u0004 איש כאחיו\" (שם ז, י) למדנו שכל המנחות ניתנות לכהן. ובודאי לא בא כתוב זה ללמדנו שכך הוא דין המנחות הבאות מן החיטים, שהרי למדנו כבר שהן ניתנות לכהנים מן הכתוב \"והנותרת ממנה יאכלו אהרן ובניו\" (שם ו, ט), ומה הוסיף כתוב זה ללמדנו? אלא ש\u0003אם\u0004 הנלמד מהפסוק הזה \u0003אינו ענין ל\u0004מנחה ה\u0003בלולה\u0004 בשמן הבאה מ\u0003של חיטין\u0004 — \u0003תנהו ענין ל\u0004מנחה ה\u0003בלולה\u0004 בשמן הבאה מ\u0003של שעורין,\u0004 היא מנחת העומר. \u0003ו\u0004כמו כן יש לומר: \u0003אם\u0004 הנלמד מהפסוק \u0003הזה\u0004 \u0003אינו ענין ל\u0004מנחה \u0003חרבה\u0004 (יבשה, שאין נותנים בה שמן) הבאה \u0003מ\u0004\u0003של חיטין\u0004 שהרי כבר נאמר דינה של זו — \u0003תנהו ענין ל\u0004מנחה \u0003חרבה\u0004 הבאה מ\u0003של שעורין,\u0004 היא מנחת הסוטה. ומקשים על דרשתו זו של חזקיה: \u0003ו\u0004האם \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003להכי\u0004 \u0005[לכך],\u0006 לדרשה זו \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד? \u0003הא מיבעי ליה\u0004 \u0005[והרי נצרך הוא]\u0006 \u0003ל\u0004לימוד הלכה אחרת, \u0003כ\u0004דרך \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003מנין שאין\u0004 הכהנים \u0003חולקין\u0004 (מחליפים) ביניהם \u0003מנחות כנגד זבחים,\u0004 שלא יאמר כהן אחד לכהן אחר: קח אתה ממני זבחים שנפלו בחלקי תמורת מנחות באותו שווי שנפלו בחלקך?"],["לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בתורה \u0003\"וכל המנחה אשר תאפה\u0004 וכל נעשה במרחשת ועל מחבת לכהן המקריב אותה לו תהיה. וכל מנחה בלולה בשמן וחרבה \u0003בתנור לכל בני אהרן תהיה איש כאחיו\"\u0004 (ויקרא ז, ט— י), ובא הכתוב ללמדנו שכל בני אהרן מחלקים בשווה את המנחה, ומודגש שדווקא את המנחה חולקים הכהנים, ואולם אין הם חולקים את המנחה כנגד הזבחים.","וממשיכים לדון: \u0003יכול\u0004 ש\u0003לא יחלקו\u0004 ביניהם הכהנים \u0003מנחות כנגד זבחים,\u0004 וסברה היא: \u0003ש\u0004הרי המנחות \u0003לא קמו\u0004 (אינן מובאות) \u0003תחתיהן\u0004 (במקומם) של הזבחים \u0003בדלות,\u0004 שגם הדל, שאינו יכול להביא בהמה לקרבן (כגון בקרבן חטאת עולה ויורד) — אינו מביא מנחה במקום הזבח, \u0003אבל\u0004 שמא תאמר ש\u0003יחלקו\u0004 הכהנים ביניהם \u0003מנחות כנגד עופות, שהרי קמו תחתיהן בדלות,\u0004 שאם היה המקריב עני מאד (\"דלי דלות\"), ואין הוא יכול להביא קרבן עוף בקרבנו, \u0003הריהו מביא מנחה —\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"וכל נעשה במרחשת... לכל בני אהרן תהיה...\",\u0004 והרי זה מקרא יתר הבא להורות שדווקא באותה מנחה חולקים הכהנים, ואין הם חולקים במנחות אף כנגד עופות.","ועדיין \u0003יכול\u0004 אתה לומר כי \u0003לא יחלקו מנחות כנגד עופות, ש\u0004הרי \u0003הללו\u0004 העופות הם \u0003מיני דמים\u0004 (שיש בהם נתינת דם על המזבח), \u0003ו\u0004אילו \u0003הללו\u0004 (המנחות) הינן \u0003מיני קמחים,\u0004 ואולם שמא \u0003יחלקו\u0004 ביניהם \u0003עופות כנגד זבחים, ש\u0004כן \u0003הללו והללו מיני דמים?\u0004 \u0003—\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"ועל מחבת... לכל בני אהרן תהיה...\",\u0004 ואף מקרא זה יתר, ובא ללמד שדווקא באלה הכהנים חולקים, ואין הם חולקים בדבר אחר. ומאחר שכבר למדנו שאינם חולקים מנחות כנגד עופות, בא פסוק זה להורות שאף אינם חולקים בעופות כנגד זבחים.","ועדיין \u0003יכול\u0004 ש\u0003לא יחלקו\u0004 דווקא ב\u0003עופות כנגד זבחים,\u0004 שכן יש ביניהם הבדל, \u0003שהללו\u0004 (העופות) \u0003עשייתן\u0004 (שחיטתן) נעשית \u0003ביד\u0004 (במליקה בצפורן), \u0003ו\u0004אילו \u0003הללו\u0004 (הזבחים) \u0003עשייתן\u0004 (שחיטתם) נעשית \u0003בכלי\u0004 (בסכין), \u0003אבל\u0004 שמא \u0003יחלקו מנחות\u0004 מסוג אחד \u0003כנגד מנחות\u0004 מסוג אחר, \u0003ש\u0004הרי דומות הן, שכן \u0003אלו ואלו עשייתן\u0004 (קמיצתן) \u0003ביד?\u0004 \u0003—\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"וכל מנחה בלולה בשמן... לכל בני אהרן תהיה...\",\u0004 ואף מקרא זה יתר, ובא ללמד שאין חולקים מנחות כנגד מנחות.","ועדיין \u0003יכול\u0004 ש\u0003לא יחלקו\u0004 מנחת \u0003מחבת כנגד\u0004 מנחת \u0003מרחשת ו\u0004מנחת \u0003מרחשת כנגד\u0004 מנחת \u0003מחבת,\u0004 משום שהן שונות זו מזו, \u0003ש\u0004הרי \u0003זו\u0004 (המחבת) \u0003מעשיה\u0004 (הדברים הנעשים בה, בשל היותה רחבה ואינה עמוקה) \u0003קשין, ו\u0004אילו \u0003זו\u0004 (המרחשת) \u0003מעשיה\u0004 (הדברים הנעשים בה, בשל היותה עמוקה) \u0003רכין, אבל\u0004 שמא \u0003יחלקו\u0004 מנחת \u0003מחבת\u0004 שהביא אדם זה, \u0003כנגד\u0004 מנחת \u0003מחבת\u0004 שהביא אדם \u0003אחר.\u0004 \u0003ו\u0004כן מנחת \u0003מרחשת\u0004 שהביא אדם זה \u0003כנגד\u0004 מנחת \u0003מרחשת\u0004 שהביא אדם אחר? \u0003—\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"וחרבה לכל בני אהרן תהיה...\",\u0004 ואף זה מקרא יתר, ללמד שגם אופן זה של חלוקת מנחה כנגד אותה מנחה אסורה.","ועדיין שואלים: \u0003יכול\u0004 ש\u0003לא יחלקו\u0004 \u0003בקדשי קדשים,\u0004 כמו מנחות, \u0003אבל יחלקו בקדשים קלים?\u0004 \u0003—\u0004 לכך \u0003תלמוד לומר\u0004 עוד בסוף הכתוב הזה \u0003\"איש כאחיו\",\u0004 ובסמוך לו נאמר דין הקדשים הקלים: \"וזאת תורת זבח השלמים אשר יקריב לה'. \u0003אם על תודה\u0004 יקריבנו והקריב על זבח התודה...\" (שם י— יא) — לומר: \u0003כשם שאין חולקין בקדשי קדשים, כך אין חולקים בקדשים קלים\u0004 כגון תודה.","ועוד נדרש מהכתוב \"איש כאחיו\": \u0003\"איש\"\u0004 — ללמד כי דווקא כהן שהוא \u0003איש\u0004 (בוגר) הוא ש\u0003חולק\u0004 (נוטל חלק בקרבנות המשמר), \u0003ואפילו\u0004 הוא \u0003בעל מום,\u0004 ו\u0003אין\u0004 הכהן ה\u0003קטן חולק\u0004 (נוטל חלק בקרבנות המשמר, שאינו אוכל אלא מחלק אביו), \u0003ואפילו\u0004 הוא \u0003תם\u0004 (שאין בו מום). הרי שנדרשו הכתובים \"וכל מנחה בלולה בשמן וחרבה\" ללמדנו לענין איסור חלוקה בין הכהנים, וכיצד איפוא דרש חזקיה מייתור הכתובים הללו לענין אכילת שיירי מנחת עומר ומנחת הסוטה!","ומשיבים: הלימוד \u0003ההוא\u0004 המובא בברייתא מהכתובים הללו לענין איסור החלוקה אינו מכל הכתוב \"וכל מנחה בלולה בשמן וחרבה\", אלא רק \u0003מ\u0004מה שנאמר \u0003\"כל\"\u0004 (\"וכל מנחה\") \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 ואילו חזקיה למד לענין אכילת שתי המנחות הללו מגוף הכתוב. ושואלים על כך: \u0003והא אפיקתיה\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת אותו,\u0006 למדת ממנו, מהמלה \"כל\"\u0005]\u0006 דרשה אחרת, \u0003ל\u0004כמו מה שאמר \u0003ר' יוסי בר' יהודה\u0004 (לעיל מנחות דף סג,ב) שאין הנודב מנחת מאפה תנור מביא שני מיני מנחות, אלא עשר חלות או עשרה רקיקים! ומשיבים: \u0003אלא\u0004 הלימוד \u0003ההוא\u0004 לענין חלוקה הריהו \u0003מ\u0004תוספת האות ו' במלה \u0003\"וכל\"\u0004 (\"וכל מנחה\") הבאה לרבות.","\u0003רבינא אמר:\u0004 המקור (לשיטת ר' שמעון) שאף מנחת העומר ומנחת הקנאות נאכלות \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003מדתני\u0004 \u0005[מ\u0006אותה ברייתא \u0005ששנה]\u0006 החכם \u0003לוי, דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003לוי\u0004 ברייתא: נאמר בתחילת פרשת מתנות הכהונה: \"זה יהיה לך מקודש הקדשים מן האש \u0003כל קרבנם לכל מנחתם ולכל חטאתם ולכל אשמם\u0004 אשר ישיבו לי קודש קדשים לך הוא ולבניך\" (במדבר יח, ט), ותוספת \"כל\" בכל אחד מן הפרטים שבפסוק זה באה לרבות:","\u0003\"כל קרבנם\"\u0004 — \u0003לרבות לוג שמן של מצורע,\u0004 שניתן לכהנים למאכל. ויש צורך בריבוי מיוחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 כי כיון ש\u0003\"מן האש\"\u0004 (שם) \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 בפסוק זה, ולוג שמן של מצורע, אינו עולה על המזבח, לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו]\u0006 שגם זה בכלל הניתנים לכהנים.","וממשיכה הברייתא: \u0003\"לכל מנחתם\"\u0004 — בא \u0003לרבות\u0004 שאף \u0003מנחת העומר ומנחת קנאות\u0004 ניתנות לכהנים לאכילה. ונצרך לכך ריבוי, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0005כיון ש\u0006בענין אכילת הכהנים מן הקדשים \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 (שמות כט, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והיה מקום לומר כי רק דבר הבא לכפר ניתן לכהנים, \u0003והאי\u0004 \u0005[וזו]\u0006 מנחת העומר — \u0003להתיר\u0004 את אכילת התבואה החדשה \u0003קא אתיא\u0004 \u0005[היא באה]\u0006 ולא לכפרה, \u0003ואידך נמי\u0004 \u0005[והאחרת,\u0006 מנחת קנאות, \u0005גם כן]\u0006 אינה באה לכפרת האשה הסוטה, אלא \u0003לברר\u0004 אם חטאה האשה בניאוף \u0003קא אתיא\u0004 \u0005[היא באה],\u0006 והיה מקום לומר שלא תינתנה אלה לכהנים לאכילה, לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו],\u0006 שאף אלה ניתנות לכהנים.","וממשיכה עוד הברייתא: ומה שנאמר \u0003\"לכל חטאתם\"\u0004 — הרי הוא \u0003לרבות חטאת העוף,\u0004 שניתנת לכהנים. ונצרך לכך ריבוי מיוחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שאינה ניתנת לכהנים לאכילה לפי ש\u0003נבילה היא,\u0004 שהרי היא נמלקת מן העורף (ויקרא ה, ח), ואסורה באכילה, על כן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו]\u0006 שהיא ניתנת לכהנים לאכילתם.","ומה שנאמר בכתוב זה \u0003\"לכל אשמם\"\u0004 — בא \u0003לרבות\u0004 אף את \u0003אשם נזיר\u0004 שנטמא, \u0003ואשם מצורע\u0004 שניתנים לכהנים. ותוהים: מה צורך בדרשה מיוחדת ללמד על \u0003אשם מצורע,\u0004 שניתן לכהנים לאכילה, והרי \u0003בהדיא כתיב ביה\u0004 \u0005[במפורש נאמר בו]\u0006 שהוא נאכל על ידי הכהנים, שכן נאמר \u0003\"כי כחטאת האשם הוא לכהן\"\u0004 (שם יד, יג)!","\u0003אלא\u0004 כוונת הדברים היא, שבא כתוב זה \u0003לרבות אשם נזיר\u0004 שנטמא, לומר שיהא דינו \u0003כאשם מצורע,\u0004 שאף הוא נאכל. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שאשם נזיר אינו בא לכפר, אלא רק \u0003להכשיר\u0004 (לאפשר לו) להתחיל מחדש את נזירותו \u0003קא אתי\u0004 \u0005[הוא בא],\u0006 ואילו אשם מצורע מכשירו לאכול מן הקדשים, והרי אכילת הכהנים נאמרה ביחס לקדשים המכפרים (\"ואכלו אותם אשר כופר בהם\"), לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הכתוב \u0005משמיע לנו]\u0006 שגם אלה ניתנים לכהנים לאכילה.","ומה שנאמר בכתוב זה \u0003\"אשר ישיבו\"\u0004 — \u0003זה\u0004 הוא \u0003גזל הגר,\u0004 שהגוזל מן הגר שאין לו יורשים, צריך לתת לכהנים את הגזילה בתוספת חומש מערכה. ומה שנאמר עוד בכתוב \u0003\"לך היא ולבניך\"\u0004 — לומר כי \u0003שלך היא,\u0004 לכל דבר, \u0003ו\u0004הינך נוהג בה כקניינך הממוני, שאתה מורישה \u0003לבניך\u0004 \u0003ו\u0004\u0003אפילו\u0004 יכול אתה \u0003לקדש בו את האשה,\u0004 שאין זה דבר השייך למקדש.","ועוד בדין אכילת כהנים מן הקדשים, \u0003אמר רב הונא:\u0004"],["\u0003שלמי הגוים,\u0004 שנדר הגוי בהמה שתוקרב כקרבן שלמים במקדש — אין הם קרבים כשלמים, אלא הריהם קרבים כ\u0003עולות\u0004 הנשרפות כליל על אש המזבח. ומסבירים את טעם הדבר, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שיש ראיה לכך מ\u0003קרא\u0004 \u0005[\u0006מן ה\u0005מקרא],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי מן ה\u0003סברא\u0004 היא. ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003סברא\u0004 היא: ה\u0003גוי\u0004 הנודר קרבן למקדש — מחשבת \u0003לבו\u0004 הינה שיהיה הקרבן מוקדש כולו \u0003לשמים\u0004 (כקרבן עולה), ולא שיאכלו ממנו בני אדם. ולכך קרבנותיו קרבים כעולה.","\u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 כי \u0005ראיה לכך מן ה\u0006\u0005מקרא],\u0006 שכן נאמר \"...איש איש מבית ישראל ומן הגר בישראל אשר יקריב קרבנו לכל נדריהם ולכל נדבותם \u0003אשר יקריבו לה' לעלה\"\u0004 (ויקרא כב, יח) — ללמד ש\u0003כל\u0004 קרבנות \u0003דמקרבי\u0004 \u0005[שמקריבים,\u0006 שנודרים ונודבים להקריב\u0005]\u0006 הגויים, קרבן \u0003עולה ליהוי\u0004 \u0005[שיהיה].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חמא בר גוריא\u0004 על דברי רב הונא ממה ששנינו בברייתא: \u0003גוי שהתנדב להביא שלמים\u0004 למקדש, אם \u0003נתנן\u0004 \u0003לישראל\u0004 כדי שיאכלם — אותו \u0003ישראל\u0004 הוא ה\u0003אוכלן,\u0004 ואם \u0003נתנן לכהן\u0004 שיאכלם — אותו \u0003הכהן אוכלן.\u0004 הרי ששלמי הגויים קרבים ונאכלים כשלמים!","\u0003אמר רבא\u0004 בתירוץ דברי רב הונא: \u0003הכי קא אמר\u0004 \u0005[כך היא אמרה,\u0006 זו כוונת הברייתא\u0005]:\u0006 גוי שהתנדב להביא שלמים למקדש, \u0003על מנת שיתכפר בהן\u0004 (שיצא בהם ידי חובתו) \u0003ישראל\u0004 שנדב שלמים — אותו \u0003ישראל אוכלן.\u0004 וכן אם התנדב הגוי שלמים למקדש \u0003על מנת שיתכפר בהן\u0004 \u0003כהן\u0004 שנדב שלמים — אותו \u0003כהן אוכלן.\u0004 ומה שאמר רב הונא שאין שלמי הגויים נאכלים אלא קרבים כליל, הרי זה כאשר נדר הגוי שלמים לשם עצמו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב שיזבי\u0004 על דברי רב הונא ממה ששנינו במשנתנו: \u0003אלו מנחות נקמצות ושיריהן\u0004 נאכלים \u0003לכהנים,\u0004 ובכללן אף \u0003מנחת גוים,\u0004 הרי שניתנת מנחת הגויים לאכילת הכהנים, ומכאן שאף שלמי הגוי ניתנים לאכילת כהנים (שכן דין המנחה כדין השלמים, לענין אכילת כהנים)! \u0003אמר ר' יוחנן:\u0004 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 משנתנו, הסבורה ששלמי הגויים נאכלים — הריהי כשיטת \u0003ר' יוסי הגלילי,\u0004 ואילו \u0003הא\u0004 \u0005[זו],\u0006 דעת רב הונא, שאין שלמי הגויים נאכלים — הריהי כשיטת \u0003ר' עקיבא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"איש איש מבית ישראל ומן הגר בישראל אשר יקריב קרבנו לכל נדריהם ולכל נדבותם... לעולה\". ודנים בכתוב: אחר שנאמר \u0003\"איש\", מה\u0004 אם כן \u0003תלמוד לומר\u0004 (מלמדנו עוד האמור) \u0003\"איש איש\"?\u0004 — הרי זה בא \u0003לרבות\u0004 אף \u0003את הגוים שנודרין נדרים ונדבות\u0004 קרבנות להקריבם במקדש, \u0003כישראל.\u0004","ומה ש\u0003נאמר עוד בכתוב זה\u0004 \u0003\"אשר יקריבו לה' לעולה\"\u0004 — \u0003אין לי\u0004 מכאן \u0003אלא\u0004 שהגוים נודרים ונודבים קרבנות ל\u0003עולה,\u0004 ואולם שהם נודרים גם \u0003קרבנות\u0004 \u0003שלמים מנין\u0004 לנו? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) כתוב יתר \u0003\"נדריהם\"\u0004 ללמד על כך. ומבררים עוד: שמביאים הגויים אף קרבנות \u0003תודה\u0004 \u0003מנין\u0004 לנו? \u0003תלמוד לומר\u0004 כתוב יתר \u0003\"נדבותם\".\u0004","\u0003ו\u0004\u0003מנין\u0004 \u0003לרבות\u0004 אף את עולות \u0003העופות, ו\u0004נסכי \u0003היין, והלבונה, והעצים\u0004 שמביאים אותם הגויים? \u0003תלמוד לומר \"נדריהם\",\u0004 הבא בלשון כוללת — \u0003\"לכל נדריהם\",\u0004 וכן גם האמור \u0003\"נדבותם\"\u0004 הבא בלשון כוללת — \u0003\"לכל נדבותם\".\u0004","ומעתה יש לשאול, אחר שהתרבו הגויים לכל אלה, \u0003אם כן מה תלמוד לומר\u0004 \"אשר יקריבו לה' ל\u0003עולה\"\u0004 — הרי זה בא למעט: \u0003עולה\u0004 סתם הגויים מביאים, \u0003פרט\u0004 (מלבד) \u0003ל\u0004עולת \u0003נזירות,\u0004 שאם הגוי נדר נזירות — אין זו חלה עליו, ואין הוא חייב איפוא בהבאת עולה. אלו הם \u0003דברי ר' יוסי הגלילי.\u0004 ואילו \u0003ר' עקיבא אומר:\u0004 ממה שנאמר \u0003\"אשר יקריבו לה' לעלה\"\u0004 — \u0003אין לי\u0004 שמביא הגוי \u0003אלא\u0004 קרבן \u0003עולה בלבד.\u0004","ולענין דרשתו של ר' יוסי הגלילי שואלים: \u0003והאי\u0004 \u0005[וזה]\u0006 הלימוד שהוא למד מן הכתוב \"אשר \u0003יקריבו לה' לעולה\" —\u0004 \u0003פרט לנזירות,\u0004 האם \u0003מהכא נפקא\u0004 \u0005[מכאן,\u0006 מפסוק זה הוא \u0005יוצא,\u0006 נלמד\u0005]?\u0006 והרי \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 מפסוק אחר הדבר \u0005יוצא,\u0006 נלמד\u0005],\u0006 ממה שנאמר בתחילת פרשת הנזירות \u0003\"דבר אל בני ישראל ואמרת אלהם איש\u0004 או אשה \u0003כי יפלא לנדר נדר נזיר להזיר\u0004 לה' \" (במדבר ו, ב) — לומר ש\u0003בני ישראל נודרין\u0004 בנזיר, \u0003ואין הגוים נודרים\u0004 בנזיר!","ומשיבים: אף שמשם נלמד שאין הגויים נודרים נזירות, עדיין נזקקים אנו לדרשת הכתוב \"אשר יקריבו לה' לעולה\". שכן \u0003אי\u0004 \u0005[אם]\u0006 היינו למדים \u0003רק\u0004 \u0003מהתם\u0004 \u0005[משם,\u0006 מהאמור בפרשת נזירות\u0005]\u0006 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003קרבן\u0004 נזירות \u0003הוא\u0004 \u0003דלא לייתי\u0004 \u0005[שלא יביא]\u0006 הגוי שנדר נזירות, \u0003אבל\u0004 ה\u0003נזירות\u0004 עצמה היינו אומרים ש\u0003חלה עלייהו\u0004 \u0005[עליהם],\u0006 על הגוי שנדר נזירות, לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"אשר יקריבו לה' לעולה\" \u0005משמיע לנו]\u0006 שאף עצם הנזירות אינה חלה בגוי הנודר נזירות.","למעלה הובאה מחלוקת ר' יוסי הגלילי ור' עקיבא אם מביאים הגויים לקרבן רק עולות (כשיטת ר' עקיבא), או אף שאר קרבנות (כשיטת ר' יוסי הגלילי). \u0003ומבררים:\u0004 \u0003כמאן אזלא הא דתנן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 \u0005הולכת,\u0006 נשנתה, משנה \u0005זו ששנינו]\u0006 במסכת שקלים: \u0003אמר ר' שמעון, שבעה דברים\u0004 בעניינים שונים \u0003התקינו בית דין, וזה אחד מהן: גוי ששלח\u0004 את קרבן \u0003עולתו ממדינת הים ושילח עמה\u0004 את דמי \u0003נסכיה\u0004 — נסכי קרבן זה \u0003קריבין משלו,\u0004 מדמי הנסכים ששלח. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שלח הגוי דמי נסכים עם הקרבן — \u0003קריבין\u0004 הנסכים \u0003משל ציבור\u0004 (מתרומת הלשכה). הרי שהגוי מקריב אף לנסכים, ולא רק לעולה.","ושואלים: האם \u0003לימא\u0004 \u0005[לומר]\u0006 שכשיטת \u0003ר' יוסי הגלילי\u0004 הם דברים אלה, \u0003ולא\u0004 כשיטת \u0003ר' עקיבא!\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהם כשיטת \u0003ר' עקיבא,\u0004 ואולם אף הוא סבור שהגוי מביא את קרבן ה\u0003עולה ו\u0004את \u0003כל חבירתה\u0004 (הנלווה לקרבן), ובכלל זה נסכים.","ושואלים עוד: כשיטת \u0003מאן\u0004 \u0005[מי]\u0006 דין זה ש\u0003תנא להא דתנו רבנן\u0004 \u0005[שנה את\u0006 מה \u0005ששנו חכמים]\u0006 בברייתא על האמור בדין הנסכים \"כל ה\u0003אזרח\u0004 יעשה ככה להקריב אשה...\" (שם טו, יג) — \u0003אזרח\u0004 (אדם מישראל) הוא ה\u0003מביא נסכים, ואין הגוי מביא נסכים\u0004 לעצמם. ויש לברר: \u0003יכול\u0004 שאף \u0003לא תהא עולתו\u0004 של הגוי \u0003טעונה\u0004 (חייבת) \u0003נסכים?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בפסוק \u0003\"ככה\"\u0004 — שהבאת הנסכים עם העולה מעכבת, שאין עולה בלא נסכים עמה. ומעתה יש לשאול: כשיטת \u0003מני\u0004 \u0005[מי היא]\u0006 ברייתא זו, שכן הריהי ש\u0003לא\u0004 כשיטת \u0003ר' יוסי הגלילי ו\u0004אף \u0003לא\u0004 כשיטת \u0003ר' עקיבא.\u0004","ומסבירים את השאלה: שהרי \u0003אי\u0004 \u0005[אם]\u0006 תרצה לומר שהיא כשיטת \u0003ר' יוסי הגלילי\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 ר' יוסי הגלילי \u0003אמר\u0004 בברייתא ש\u0003אפילו יין\u0004 לנסכים לעצמם \u0003נמי\u0004 \u0005[גם כן]\u0006 מביא הגוי! \u0003ו\u0004\u0003אי\u0004 \u0005[אם]\u0006 תרצה לומר שהיא כשיטת \u0003ר' עקיבא\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 ר' עקיבא \u0003אמר\u0004 באותה ברייתא כי \u0003עולה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מביא הגוי, ואולם כל \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא\u0004 מביא!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהברייתא היא כשיטת \u0003ר' יוסי הגלילי, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהברייתא היא כשיטת \u0003ר' עקיבא.\u0004 ומסבירים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי הברייתא כשיטת \u0003ר' יוסי הגלילי\u0004 היא, ואין להקשות שר' יוסי הגלילי הזכיר בדבריו בברייתא שהגוי מביא אף יין לנסכים לעצמם, שכן \u0003סמי מההיא\u0004 \u0005[מחק מאותה\u0006 ברייתא\u0005]\u0006 מדברי ר' יוסי את המלה \u0003יין,\u0004 ואף לדעתו אין הגוי מביא נסכים לעצמם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי כשיטת \u0003ר' עקיבא\u0004 היא ברייתא זו, ואף שאמר ר' עקיבא בברייתא שאין הגוי מביא אלא עולה בלבד — כוונתו שהגוי מביא \u0003עולה ו\u0004את \u0003כל חבירתה\u0004 (הנלוה לה), כנסכים.","שנינו במשנתנו כי \u0003ר' שמעון אומר\u0004 ש\u0003מנחת חוטא של כהנים\u0004 נקמצת, והכל נשרף. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006","ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 בברייתא: נאמר במנחת חוטא \"והביאה אל הכהן וקמץ הכהן ממנה מלוא קומצו את אזכרתה והקטיר המזבחה על אשי ה' חטאת היא. וכפר עליו הכהן על חטאתו אשר חטא מאחת מאלה ונסלח לו והיתה לכהן כמנחה\" (ויקרא ה, יב— יג). ויש לשאול: מה מלמדנו כתוב זה \u0003\"והיתה לכהן כמנחה\",\u0004 והרי במנחה אמורים הדברים? אלא בא הכתוב ללמדנו \u0003שתהא עבודתה\u0004 של מנחת חוטא \u0003כשרה\u0004 אף \u0003בו,\u0004 בכהן שחטא ומביא מנחה זו.","ודנים בדבר: \u0003אתה אומר\u0004 שלמדים מכתוב זה \u0003שתהא עבודתה\u0004 של מנחת החוטא \u0003כשרה\u0004 אף \u0003בו, או אינו\u0004 בא \u0003אלא להתיר\u0004 את אכילתה של \u0003מנחת חוטא של כהנים,\u0004 כמנחת חוטא של ישראל? \u0003ו\u0004לפי זה \u0003מה\u0004 (כיצד) \u0003אני מקיים\u0004 את האמור \u0003\"וכל מנחת כהן כליל תהיה לא תאכל\"\u0004 (שם ו, טז)? ואף שאולי מדובר רק ב\u0003מנחת נדבתו\u0004 של כהן — \u0003אבל\u0004 מנחת \u0003חובתו תהא נאכלת?\u0004","לכך \u0003תלמוד לומר \"והיתה לכהן כמנחה\", מקיש\u0004 (משווה) הכתוב דין מנחת \u0003חובתו\u0004 של כהן \u0003ל\u0004דין מנחת \u0003נדבתו,\u0004 \u0003מה\u0004 מנחת \u0003נדבתו\u0004 של כהן — \u0003אינה נאכלת, אף\u0004 מנחת \u0003חובתו\u0004 של כהן — \u0003אינה נאכלת.\u0004 כנגד דרך דרשה זו \u0003אמר ר' שמעון: וכי נאמר\u0004 בכתוב \u0003\"והיתה לכהן כמנחתו\",\u0004 שנלמד ממנו כי יש להקיש דין מנחת חוטא של כהן לדין מנחת נדבתו? \u0003והלא לא נאמר אלא\u0004 \"והיתה לכהן \u0003כמנחה\"\u0004 — כמנחה סתם, שאינה מנחת כהנים! \u0003אלא\u0004 בא הכתוב \u0003להקיש\u0004"]]};
